SELECT 'moj-all-verified-judgments-review-002-chunk-039' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"bbf6ebd0-3591-5705-811f-045b6b5b0509","document_type":"judgment","category":"judicial","subcategory":"general","title":"زنا -خلوة محرمة -اعتداء بالضرب -إحداث إصابات -ممارسة دعارة -إقرار املدعى عليهم -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","document_number":"34349928","case_number":"34213064","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/4","year":"1434","subject":"زنا -خلوة محرمة -اعتداء بالضرب -إحداث إصابات -ممارسة دعارة -إقرار املدعى عليهم -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34349928 :‬تاريخه ‪1434/11/4 :‬هـ‬\n                   ‫رقم الدعوى‪34213064 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34389266‬تاريخه‪1434/12/26 :‬هـ‬\n\n\n‫زنــا ‪ -‬خلــوة محرمــة ‪ -‬اعتــداء بالضــرب ‪ -‬إحــداث إصابــات ‪ -‬ممارســة‬\n‫دعــارة ‪ -‬إقــرار املدعــى عليهــم ‪ -‬تعزيــر بالســجن واجللــد والتوصيــة‬\n                                                 ‫باإلبعــاد عــن البــاد‪.‬‬\n\n\n\n‫‪ -‬قولــه صلــى اهلل عليــه وســلم ( مــا خــا رجــل بامرأة إال كان الشــيطان‬\n                                                                ‫ثالثهما ) ‪.‬‬\n                       ‫‪ -‬املادة ( ‪ )162‬من نظام اإلجراءات اجلزائية ‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليهــم األولــى والثانية والثالثــة والرابع‬\n‫باالختــاط احملــرم ‪ ،‬واتهــام املدعــى عليهــا الثانيــة مبمارســة الدعــارة‪،‬‬\n‫واتهــام املدعــى عليــه الرابــع بإيوائهــن واالعتــداء عليهــن بالضــرب‬\n‫وإحــداث إصابــات بهــن‪ ،‬وطلــب املدعــي العــام إثبــات إدانتهــم مبــا أســند‬\n‫إليهــم وتعزيرهــم لذلــك‪ ،‬أقــر املدعــى عليهــم مبــا جــاء بدعــوى املدعــي‬\n‫العــام‪ ،‬حكمــت احملكمــة بتعزيــر املدعــى عليهــم بالســجن واجللــد‬\n‫والتوصيــة باإلبعــاد عــن البــاد بعــد انتهــاء محكوميتهــم‪ ،‬قنــع املدعــى‬\n‫عليهــم باحلكــم‪ ،‬و قــرر املدعــي عليهــم االعتــراض بــدون الئحــة‪ ،‬صــدق‬\n                                           ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n                                                                                      ‫‪290‬‬\n\f      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة الرئيــس‬\n      ‫برقــم وتاريــخ ‪1434/05/07‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ‬\n      ‫‪1434/05/07‬ه ـ يف يــوم االثنــن املوافــق‪ 1434/11/03‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة احلاديــة عشــرة وخمــس دقيقــة وفيهــا حضــر املدعــي‬\n      ‫ال مــن ‪ ... -1‬اندونيســية اجلنســية‬ ‫العــام ‪ ...‬وادعــى علــى احلاضــر معــه ك ً‬\n      ‫بطاقــة بديلــة رقــم (‪ ...-2 )../..‬اندونيســية اجلنســية بطاقــة بديلــة رقــم‬\n      ‫(‪ ...-3 )../..‬اندونيســية اجلنســية بطاقــة بديلــة رقــم (‪ ...-4 )../..‬بنغالــي‬\n      ‫ا يف دعــواه عليهــم قــد انتهــى التحقيــق إلــى‬  ‫اجلنســية إقامــة رقــم ‪ ...‬قائ ـ ً‬\n      ‫توجيــه االتهــام للمدعــى عليهــم باالختــاط احملــرم شــرع ًا واتهــام املدعى‬\n      ‫عليهــا ‪ ...‬مبمارســة الدعــارة واتهــام املدعــى عليــه ‪ ...‬بإيوائهــن واالعتــداء‬\n      ‫عليهــن بالضــرب وأحــداث اصابــات بهــن املوصوفــة بالتقاريــر املرفقــة‬\n      ‫لــذا أطلــب إثبــات مــا أســند إليهــم واحلكــم عليهــم بعقوبــة تعزيريــة‬\n      ‫(علمـ ًا بــأن احلــق اخلــاص الزال قائمـاً) وبعــرض ذلــك علــى املدعــى عليهــم‬\n      ‫بواســطة املترجمــن ‪ ...‬و‪ ..‬أجابــت كل واحــدة مــن املدعــى عليهــن‬\n      ‫األولــى والثانيــة والثالثــة قائلــة مــا ذكــره املدعــي العــام يف دعــواه كلــه‬\n      ‫صحيــح هكــذا أجابــت كل واحــدة منهــن وأجــاب املدعــى عليــه الرابــع‬\n      ‫مــا ذكــره املدعــي العــام يف دعــواه كلــه صحيــح هكــذا أجــاب ثــم‬\n      ‫جــرى منــي االطــاع علــى أوراق املعاملــة ومحاضــر القبــض والتقاريــر‬\n      ‫الطبيــة فوجدتهــا كمــا ذكــر املدعــي العــام واســتناد ًا للمــادة رقــم‬\n      ‫(‪ )162‬مــن نظــام اإلجــراءات اجلزائيــة اكتفيــت باعتــراف املدعــى‬\n\n‫‪291‬‬\n\f‫عليهــم وإقرارهــم مبجلــس احلكــم فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واجلــواب وإقــرار املدعــى عليهــم مبــا نســب إليهــم وملــا يف فعلهــم مــن اجلرأة‬\n‫يف الباطــل والتعــرض لألعــراض واالختــاء احملــرم شــرع ًا ولقولــه عليــه‬\n‫الصــاة والســام ‪(:‬مــا خــا رجــل بامــرأة إال كان الشــيطان ثالثهمــا)‬\n‫ولــكل مــا تقــدم فقــد ثبــت لــدي إدانــة املدعــى عليهــم مبــا نســب إليهــم‬\n‫يف دعــوى املدعــي العــام مــن دعــوى املدعــي العــام وحكمــت علــى كل‬\n‫واحــد منهــم بســجنه مــدة ســبعة أشــهر وجلــده مائتــي جلــدة مفرقــة عليــه‬\n‫أربــع مــرات كل مــرة خمســون جلــدة بــن كل مــرة والتــي تليهــا ســبعة‬\n‫أيــام وأوصــي بإبعادهــم جميع ـ ًا لبالدهــم بعــد انتهــاء محكومياتهــم‬\n‫وعــدم الســماح لهــم بدخــول هــذه البــاد إال مبــا تقضــي بــه تعليمــات‬\n‫احلــج والعمــرة وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليهــم قــرر‬\n‫املدعــي العــام اإلعتــراض بــدون الئحــة وقــرروا املدعــى عليهــم جميع ـ ًا‬\n‫القناعــة بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم جــرى النطــق باحلكــم الســاعة احلاديــة وثالثــن دقيقــة‬\n                                                       ‫بتاريــخ ‪1434/11/03‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد جــرى‬\n‫منــا نحــن قضــاة الدائــرة اجلزائيــة الســابعة مبحكمــة االســتئناف يف‬\n‫منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الواردة مــن فضيلة رئيس‬\n‫احملكمــة اجلزائيــة مبكــة املكرمــة رقــم وتاريــخ ‪1434/12/1‬ه ـ‬\n‫املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪ ...‬القاضــي باحملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة رقــم وتاريــخ ‪1434/11/4‬ه ـ احملكــوم فيــه‬\n‫مبــا دون بباطــن القــرار املتضمــن دعــوى املدعــى العــام ضــد‪ ...‬بنغالــي‬\n‫اجلنســية ورفيقاتــه املتهــم يف االختــاط احملــرم شــرع ًا وبدراســة القــرار‬\n\n\n                                                                                        ‫‪292‬‬\n\f      ‫وصــورة ضبطــه تقــررت املوافقــة علــى احلكم باألكثريــة ‪ ،‬واهلل املوفق‪.‬‬\n                      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪293‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":290,"source_page_end":293,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"18edc82e89d64675c20e1fb1eda7e998958f61c9fa34792a772c44862816662a","normalized_text_hash":"0b5c11f5f233faad7a277d0a6d6e26ac66c18054aebcd46a1436fa5d5c8c82cf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p290-34349928"},{"id":"42c008b3-8691-54bc-b8e9-3f21649d9241","document_type":"judgment","category":"judicial","subcategory":"general","title":"ممارسة الدعارة -حيازة مقاطع جنسية وإرسالها -إقرار -تعزير بالسجن واجللد -مصادرة -توصية باإلبعاد .","document_number":"34334680","case_number":"34410155","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"ممارسة الدعارة -حيازة مقاطع جنسية وإرسالها -إقرار -تعزير بالسجن واجللد -مصادرة -توصية باإلبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34334680 :‬تاريخه‪1434/1/20:‬هـ‬\n                  ‫رقم الدعوى‪34410155 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34380498‬تاريخه‪1434/12/18 :‬هـ‬\n\n\n‫ممارســة الدعــارة ‪ -‬حيــازة مقاطــع جنســية وإرســالها ‪ -‬إقــرار ‪ -‬تعزيــر‬\n                     ‫بالســجن واجللــد ‪ -‬مصــادرة ‪ -‬توصيــة باإلبعــاد ‪.‬‬\n\n\n\n‫‪ -‬قولــه تعالــى « إن الذيــن يحبــون أن تشــيع الفاحشــة يف الذيــن آمنــوا‬\n                                  ‫لهــم عــذاب أليــم يف الدنيــا و اآلخــرة )‪.‬‬\n       ‫‪-‬أن الشريعة جاءت بحفظ الضروريات اخلمس ومنها العرض ‪.‬‬\n\n\n\n‫أقــام املدعــى العــام دعــواه ضــد املدعــى عليهمــا مبمارســة أعمــال‬\n‫الدعــارة والفســاد‪ ،‬وحيــازة األولــى مقاطــع جنســية علــى هاتفهــا اخللــوي‬\n‫وطلــب احلكــم عليهمــا بعقوبــة تعزيريــة وعلــى األولــى باملــادة السادســة‬\n‫مــن نظــام مكافحــة اجلرائــم املعلوماتيــة حيــث قبــض عليهمــا يف أحــد‬\n‫األســواق وهمــا يف غايــة الســفور والتبــرج وعثــر يف هاتفهمــا علــى رســائل‬\n‫تــدل علــى ممارســتهما العالقــات احملرمــة ومبواجهتهمــا بذلــك اعترفتــا‬\n‫وعليــه قــررت احملكمــة ســجن كل واحــدة منهمــا مــدة ســنة وجلــد‬\n‫كل واحــدة تســعة وثالثــن جلــدة مكــررة ‪ 3‬مــرات ومصــادرة اجلــواالت‬\n‫املضبوطــة والتوصيــة باإلبعــاد عــن البــاد بعــد تنفيــذ احلكــم وجــرى‬\n‫االعتــراض مــن املدعــى العــام وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n                                                                                  ‫‪294‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ‪ .‬فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبحافظــة جــدة برقــم ‪ 34410155‬وتاريــخ‬\n      ‫‪1434/09/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 342086437‬وتاريــخ‬\n      ‫‪1434/08/29‬ه ـ ففــي يــوم االثنــن املوافــق ‪1434/10/19‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر املدعــي العــام ‪ ... -:‬ســعودي‬\n      ‫ال من‪-:‬‬  ‫اجلنســية بالســجل املدنــي رقــم ‪ ....‬وقــدم الئحتــه مدعيـ ًا علــى ك ً‬\n      ‫‪ )20( ،....-1‬عامـاً‪ ،‬اندونيســية اجلنســية مبوجــب البطاقــة البديلــة رقــم‬\n      ‫(‪ )...‬الصــادرة مــن مركــز شــرطة الشــمالية ‪ ،‬غيــر محصنــة‪ ،‬ال تعمــل‪،‬‬\n      ‫موقوفــة بالســجن العــام بأمــر التمديد رقــم (‪ )56280‬يف ‪1434/8/17‬هـ‬\n                            ‫اســتناد ًا للمــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة ‪.‬‬\n      ‫‪ )21( ،....-2‬عام ـاً‪ ،‬اندونيســية اجلنســية مبوجــب البطاقــة البديلــة‬\n      ‫رقــم (‪ )...‬الصــادرة مــن مركــز شــرطة الشــمالية ‪ ،‬غيــر محصنــة‪،‬‬\n      ‫ال تعمــل‪ ،‬موقوفــة بالســجن العــام بأمــر التمديــد رقــم (‪ )56278‬يف‬\n      ‫‪1434/8/17‬ه ـ اســتناد ًا للمــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة ‪.‬‬\n      ‫فإنــه بتاريــخ ‪1434/8/12‬ه ـ قبــض علــى املدعــى عليهمــا مــن قبــل هيئــة‬\n      ‫األمــر باملعــروف والنهــي عــن املنكــر بعــد أن شــاهدوهما تتجــوالن يف‬\n      ‫ســوق (‪ )...‬وهمــا يف غايــة التبــرج والســفور وترتديــان مالبــس قصيــرة‬\n      ‫وباســتيقافهما حاولتــا إخفــاء هواتفهمــا اخللويــة‪ ،‬وبتفتيــش هاتــف‬\n      ‫األولــى ُضبطــت بــه محادثــات ورســائل مــع رجــال تــدل علــى ممارســتها‬\n      ‫للدعــارة كمــا شــوهد رســالة تــدل علــى مســاومتها لشــخص يطلــب منهــا‬\n\n‫‪295‬‬\n\f‫أن تســهر معــه فــردت عليــه وطلبــت مقابــل ذلــك ألــف ريــال‪ .‬وبتفتيــش‬\n‫هاتــف املدعــى عليهــا الثانيــة شــوهد بــه عــدة رســائل بأســماء رجــال‬\n‫يرغبــون إقامــة عالقــات محرمــة معهــا ويطلبــون منهــا أن تعرفهــم علــى‬\n‫نســاء أخريــات فأرســلت لهــم أســماء عــدد مــن النســاء ومــن تلك الرســائل‬\n‫رســالة مــن شــخص طلــب منهــا أن تســهر معــه فطلبــت منــه رصيــد شــحن‬\n                                              ‫اتصــال وقــال لهــا (بكــرة أجــي)‪.‬‬\n‫وبإســتجواب املدعــى عليهــا األولــى اعترفــت بتجولهــا يف ســوق (‪)....‬‬\n‫وهــي تضــع املســاحيق التجميليــة بوجههــا وكانــت تريــد الذهــاب إلــى‬\n‫إحــدى صديقاتهــا كمــا اعترفــت بأنهــا تقيــم عالقــات محرمــة مــع‬\n‫رجــال لغــرض التعــارف وأنهــا واعدتهــم كــي تقابلهــم‪ ،‬وأضافــت أنهــا‬\n                                        ‫حتــوز بهاتفهــا اخللــوي مقاطــع جنســية‪.‬‬\n‫باســتجواب املدعــى عليهــا الثانيــة اعترفــت أنهــا كانــت تتجــول بســوق‬\n‫(‪ ).. ..‬وكانــت ترغــب بالذهــاب إلــى إحــدى صديقاتهــا وكانــت ترتــدي‬\n‫مالبــس قصيــرة (برمــودا) كمــا اعترفــت بأنهــا تقيــم عالقــات محرمــة‬\n‫مــع رجــال ‪ .‬وقــد أســفر التحقيــق عــن توجيــه االتهــام إلــى املدعــى عليهمــا‬\n‫ممارســة أعمــال الدعــارة والفســاد‪ ،‬وحيــازة األولــى مقاطــع جنســية‬\n‫بهاتفهــا اخللــوي وإرســال صورتهــا لشــخص وهــي عاريــة وذلــك لألدلــة‬\n                                                             ‫والقرائــن التاليــة‪-:‬‬\n                         ‫املنوه عنه املدون ص (‪ )5-1‬لفة (‪)11‬‬   ‫‪-1‬اعترافهما ّ‬\n                                 ‫املنوه عنه لفة (‪)6‬‬\n                                                 ‫‪-2‬ما جاء مبحضر القبض ّ‬\n              ‫املنوه عنه املرفق لفة (‪)13.12‬‬    ‫‪-3‬ما جاء مبحضر املشاهدة ّ‬\n‫وباإلطــاع علــى صحيفــة ســوابقهما لــم تــرد حتــى تاريخــه ‪ .‬حيــث إن مــا‬\n‫أقدمــت عليــه املذكورتــان وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا فعــل‬\n\n\n                                                                                      ‫‪296‬‬\n\f      ‫محــرم ومعاقــب عليــه شــرع ًا ومــا قامــت بــه األولــى هــو مجــرم نظام ـ ًا‬\n      ‫طبق ـ ًا لنظــام مكافحــة جرائــم املعلوماتيــة لــذا أطلــب إثبــات مــا أســند‬\n      ‫إليهمــا واحلكــم عليهمــا بعقوبــة تعزيريــة رادعــة واحلكــم علــى األولــى‬\n      ‫مبــا ورد يف الفقــرة األولــى مــن املــادة السادســة مــن نظــام مكافحــة‬\n      ‫اجلرائــم املعلوماتيــة واحلكــم مبصــادرة الهاتفــن اخللويــن املضبوطــن‬\n      ‫(نــوع جالكســي) املــدون بهــا األرقــام التسلســلية التاليــة (‪)............‬‬\n                                      ‫و(‪ )............‬هــذه دعــواي وأســألهما اجلــواب ‪.‬‬\n      ‫وبســؤال املدعــى عليهمــا عــن الدعــوى أجابتــا قائلتــن وهمــا يتكلمــان‬\n      ‫اللغــة العربيــة مــا ذكــره املدعــي العــام صحيــح ونحــن تائبتــن ونادمتــن‬\n      ‫وعازميــن علــى عــدم العــودة ملثــل مــا بــدر منــا هكــذا أجابتــا ‪ .‬وباالطالع‬\n      ‫علــى أوراق املعاملــة واملتضمنــة اعتــراف املدعــى عليهمــا وكذلــك مــا‬\n      ‫جــاء يف محضــر القبــض ومحضــر املشــاهدة حيــث إن مــا أقدمتــا عليــه‬\n      ‫فعــل محــرم شــرع ًا وفيــه نشــر للفســاد والرذيلــة مــع املجاهــرة وألن‬\n      ‫الشــريعة جــاءت بحفــظ الضروريــات اخلمــس ومنهــا العــرض ‪ .‬لقولــه‬\n      ‫تعالــى « إن الذيــن يحبــون أن تشــيع الفاحشــة يف الذيــن آمنــوا لهــم عــذاب‬\n      ‫أليــم يف الدنيــا و اآلخــرة»‪ .‬وألن املدعــى عليهمــا أجنبيتــان وال مصلحــة يف‬\n      ‫إطالــة ســجنهما‪ .‬ولــكل مــا تقــدم قــررت تعزيــر كل واحــدة منهمــا مبــا‬\n      ‫يلــي‪ -:‬أو ًال ‪ :‬ســجن كل واحــدة منهمــا ملــدة ســنة كاملــة حتتســب منهــا‬\n      ‫مــدة إيقافهمــا يف هــذه القضيــة‪ .‬ثاني ـاً‪ :‬جلــد كل واحــدة منهمــا تســعة‬\n      ‫وثالثــن (‪ )39‬جلــدة مكــررة ثالثــة مــرات وبــن كل دفعــة واألخــرى‬\n      ‫عشــرة أيــام‪ .‬ثالثـاً‪ :‬مصــادرة اجلــواالت املضبوطــة يف هــذه القضيــة‪ .‬رابعـاً‪:‬‬\n      ‫أوصيــت بإبعادهمــا عــن البــاد بعــد انتهــاء محكوميتهمــا مــع منعهمــا‬\n      ‫ال إال وفــق تعليمــات احلــج والعمــرة ‪ .‬وبذلــك كلــه‬    ‫مــن دخولهــا مســتقب ً‬\n\n\n‫‪297‬‬\n\f‫حكمــت وبعرضــه عليهمــا قررتــا قناعتهمــا باحلكــم وأبــدى املدعــي‬\n‫العــام اعتراضــه وطلــب متييــزه بالئحــة فأفهــم بنــص النظــام ‪ .‬وصلــى اهلل‬\n‫علــى ســيدنا محمــد وعلــى آلــه وصحبه وســلم حــرر يف ‪1434/10/19‬هـ‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ ...‬نحــن رئيــس‬\n‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة اإلســتئناف مبنطقــة‬\n‫مكــة املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪34334680‬‬\n‫وتاريــخ ‪1434/10/20‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ..../‬القاضــي‬\n‫باحملكمــة اجلزائيــة مبحافظــة جــدة‪ ،‬املتضمــن دعــوى املدعــي العــام‬\n‫ضــد‪ ..../‬اندونيســية اجلنســية ورفيقتهــا ‪ ،‬املتهمتــان مبمارســة أعمــال‬\n‫الدعــارة‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة القــرار وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل‬\n‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،،،،،‬‬\n\n\n\n\n                                                                                  ‫‪298‬‬\n\f299\n\f300\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":294,"source_page_end":300,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ae5eabee964bd7f443e8681e827ebae36204fbe5fda17ee362bb71e228d7b92b","normalized_text_hash":"62ced452a832fd75a46e428c7a5be56da278ef9258875683094efca5ae5b73dc","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p294-34334680"},{"id":"3605225b-b6e0-5a02-851a-d69c0b972245","document_type":"judgment","category":"judicial","subcategory":"general","title":"خلوة محرمة -إقامة عالقة محرمة -انتهاك حرمة منزل -ثبوت اإلدانة باإلقرار -املدعى عليه محصن -التعزير بالسجن واجللد وأخذ التعهد واإلبعاد عن الباد.","document_number":"3420794","case_number":"345694","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/24","year":"1434","subject":"خلوة محرمة -إقامة عالقة محرمة -انتهاك حرمة منزل -ثبوت اإلدانة باإلقرار -املدعى عليه محصن -التعزير بالسجن واجللد وأخذ التعهد واإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3420794:‬تاريخه ‪1434/01/24 :‬هـ‬\n                           ‫رقم الدعوى‪345694 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34182428‬تاريخه‪1434/4/8 :‬هـ‬\n\n\n      ‫خلــوة محرمــة ‪ -‬إقامــة عالقــة محرمــة ‪ -‬انتهــاك حرمــة منــزل ‪ -‬ثبــوت‬\n      ‫اإلدانــة باإلقــرار ‪ -‬املدعــى عليــه محصــن ‪ -‬التعزيــر بالســجن واجللــد‬\n                                            ‫وأخــذ التعهــد واإلبعــاد عــن البــاد‪.‬‬\n\n\n\n                       ‫‪ -1‬قوله تعالى‪( :‬وال تفسدوا يف األرض بعد إصالحها)‪.‬‬\n                         ‫‪ -2‬قوله تعالى‪( :‬وال تعتدوا إن اهلل ال يحب املعتدين)‪.‬‬\n      ‫‪ -3‬قولــه صلــى اهلل عليــه وســلم‪( :‬كل املســلم علــى املســلم حــرام دمــه‬\n                                                                  ‫ومالــه وعرضــه)‪.‬‬\n      ‫‪ -4‬قولــه صلــى اهلل عليــه وســلم‪( :‬مــا خــا رجــل بامــرأة إال كان‬\n                                                           ‫الشــيطان ثالثهمــا)‪.‬‬\n\n\n\n\n      ‫توجيــه االتهــام للمدعــى عليــه مقيم غير مســلم محصــن بإقامة عالقة مع‬\n      ‫امــرأة عاملــة منزليــة ال متــت لــه بصلــة ودخــول منــزل كفيلهــا واالختــاء‬\n      ‫بهــا ‪ ،‬حيــث تقــدم أحــد املواطنــن ببــاغ لــدى الشــرطة يتضمــن قيــام‬\n      ‫املدعــى عليــه بدخــول منزلــه واالختــاء باخلادمــة يف فنــاء املنــزل ومكــث‬\n      ‫مــدة مــن الزمــن ثــم خــرج وهــو يرتــدي عبــاءة نســائية وقــد شــاهد دخولــه‬\n      ‫وخروجــه شــاهدان همــا مــن قامــا باإلبــاغ عنــه ومت القبــض عليــه بعــد‬\n\n‫‪301‬‬\n\f‫خروجــه مــن املنــزل‪ ،‬طلــب املدعــي العــام إثبــات مــا أســند للمدعــى عليــه‬\n‫واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره‪ ،‬أقــر املدعــى عليــه‬\n‫مبــا نســب إليــه وذكــر أنــه قــد أســلم يف الســجن‪ ،‬حكمــت احملكمــة‬\n‫بثبــوت مــا أســند للمدعــى عليــه وتعزيــره لقــاء ذلــك بســجنه ثالثــة أشــهر‬\n‫مــن تاريــخ إيقافــه وجلــده ثمانــن جلــدة علــى دفعتــن وأخــذ التعهــد عليــه‬\n                       ‫واإلبعــاد‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫ـدي‬\n ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ النبــي بعــده وبعــد فلـ َّ‬\n‫ـاء علــى‬\n        ‫أنــا ‪ ................‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫املعاملــة الــواردة إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة‬\n‫األحســاء برقــم ‪ 28‬وتاريــخ ‪1434/01/03‬ه ـ واملقيــدة بهــذه احملكمــة‬\n‫برقم‪3426307‬وتاريــخ ‪1434/01/05‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n‫الرئيــس برقــم ‪ 345694‬وتاريــخ ‪1434/01/05‬ه ـ فتحــت اجللســة‬\n‫األولــى الســاعة احلاديــة عشــرة والنصــف وفيهــا حضــر املدعــي العــام‬\n‫‪ ........‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطــاب ســعادة‬\n‫رئيــس دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء ذي الرقــم‬\n‫ا بصفتــي مدعيـ ًا‬     ‫‪ 13415‬والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه قائـ ً‬\n‫عامـ ًا بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي علــى ‪،................‬‬\n‫البالــغ مــن العمــر(‪ )28‬عامـ ًا ‪ ،‬فلبينــي اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫رقــم (‪ ).............‬غيــر مســلم‪ ،‬محصــن‪ ،‬ميكانيكــي ســيارات‪ ،‬قبــض‬\n‫علي ــه بـتـاري ــخ ‪1433/12/11‬ه ـ أوق ــف بـم ــوجب أمــر التوقيــف رقــم (ه ـ‬\n‫ق‪ )11453/2/2‬وتاريــخ ‪1433/12/12‬ه ـ اســتنادا للقــرار الــوزاري‬\n\n                                                                                        ‫‪302‬‬\n\f      ‫(‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ وجــرى متديــد توقيفــه (‪ )25‬يـوم ـ ًا اعتبارا‬\n      ‫مــن ‪1433/12 /16‬ه ـ مبوجــب أمــر التمديــد رقــم (ه ـ ق ‪)58020/3/ 1‬‬\n      ‫وتاريــخ ‪1433/12/15‬ه ـ اســتنادا للمــادة (‪ )114‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة وأحيــل إلــى شــعبة ســجن محافظــة األحســاء‪ .‬أنــه بتاريــخ‬\n      ‫‪1433/12/11‬ه ـ مت القبــض عليــه بنــاء علــى بــاغ يتضمــن قيــام املدعــى‬\n      ‫عليــه بدخــول منــزل ‪....../‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫(‪ ).......‬وأنــه يوجــد شــاهدين شــاهدوه وهــو يخــرج مــن املنــزل يرتــدي‬\n      ‫عباءة نســائية‪ .‬وبضبط أقوال الشــاهد األول‪........‬باكســتاني‪ -‬اجلنســية‬\n      ‫مبوجــب رخصــة اإلقامــة رقــم (‪ ).....‬أفــاد أنــه كان يجلــس مــع زميلــه‬\n      ‫وشــاهدا املدعــى عليــه وهــو يدخــل املنــزل وبقيــا أمــام املنــزل وبعــد قرابــة‬\n      ‫الســاعة والنصــف خرجــت اخلادمــة مــن املنــزل وألقــت نظرة علــى الطريق‬\n      ‫وشــاهدها وزميلــه وبعــد دخولهــا بحوالــي عشــر دقائــق خــرج املدعــى‬\n      ‫عليــه مــن املنــزل وهــو يرتــدي عبــاءة نســائية وقامــا باإلبــاغ عنــه ومت‬\n      ‫القبــض عليــه‪ .‬وبضبــط أقــوال الشــاهد الثاني‪.....‬باكســتاني‪ -‬اجلنســية‬\n      ‫مبوجــب رخصــة اإلقامــة رقــم (‪ ).....‬جــاءت أقوالــه مطابقــة ألقــوال‬\n      ‫الشــاهد األول‪ .‬وبضبــط أقــوال اخلادمة‪.....‬فلبينيــة‪ -‬مبوجــب رخصــة‬\n      ‫اإلقامــة رقــم (‪( ).......‬صــدر لهــا أمــر حفــظ أوراق) أفــادت أنهــا تعــرف‬\n      ‫املتهــم يف الســابق وأنــه اتصــل عليهــا وأخبرهــا عــن رغبتــه يف مقابلتهــا‬\n      ‫وقامــت بوصــف منــزل كفيلهــا لــه وحضــر لهــا املدعــى عليــه ومكنتــه‬\n      ‫مــن دخــول منــزل كفيلهــا وجلــس معــه يف فنــاء املنــزل وملــا شــعر بــأن‬\n      ‫هنــاك أشــخاص شــاهدوه طلــب منهــا عبــاءة وقامــت بإعطائــه العبــاءة‪.‬‬\n      ‫وباســتجواب املدعــى عليــه ‪ ........ /‬أقــر بأنــه علــى عالقــة باخلادمــة يف‬\n      ‫الســابق وأنهــا مكنتــه مــن دخــول منــزل كفيلهــا ودخــل منــزل كفيلهــا‬\n\n\n‫‪303‬‬\n\f‫وبقــي معهــا يف فنــاء املنــزل وملــا شــعر بــأن هنــاك أشــخاص شــاهدوه قــام‬\n‫بلبــس عبــاءة نســائية بغــرض التخفــي‪ .‬وقــد أســفر التحقيــق عــن توجيــه‬\n‫االتهــام لــه بإقامــة عالقــة مــع امــرأة ال متــت لــه بصلــة و دخــول منــزل‬\n                ‫كفيلهــا واالختــاء بهــا وذلــك لألدلــة والقرائــن التاليــة ‪-:‬‬\n‫‪-1‬أقوالــه املدونــة علــى الصفحتــن رقــم (‪ )4،3‬مــن دفتــر التحقيــق‬\n                                                         ‫املرفــق علــى اللفــة (‪.)12‬‬\n‫‪-2‬أقــوال اخلادمــة املدونــة علــى الصفحــات (‪ )10،9‬مــن دفتــر‬\n                          ‫االســتدالالت األوليــة املرفــق علــى اللفــة (‪.)1‬‬\n‫‪-3‬مــا جــاء يف شــهادة الشــاهدين املدونــة علــى الصفحــات (‪ )14،13‬مــن‬\n                            ‫دفتــر االســتدالالت األوليــة املرفــق علــى اللفــة (‪.)1‬‬\n‫‪-4‬توافــق أقــوال املتهــم مــع مــا جــاء يف أقــوال اخلادمــة والشــاهدين‪.‬‬\n‫وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق مســجلة‬\n‫حتــى تاريخــه‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه‬\n‫املعتبــرة شــرع ًا ـ فعــل محــرم ومعاقــب عليــه شــرع ًا اطلــب إثبــات مــا‬\n‫أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره ‪( .‬علمـ ًا‬\n‫بــأن احلــق اخلــاص ال زال قائم ـاً) عليــه فقــد حضــر املدعــى عليــه وبعــد‬\n‫التأكــد مــن هويتــه جــرى عــرض دعــوى املدعــي العــام عليــه بواســطة‬\n‫املترجــم فلبينــي اجلنســية مبوجــب رخصــة اإلقامــة الصــادرة مــن جــوازات‬\n‫معروف لدينــا بالعدالة فأجاب قائالً‪:‬‬  ‫ٌ‬        ‫الهفــوف برقــم (‪ )....‬مســلم الديانــة‬\n‫مــا ذكــره املدعــي العــام مــن اتهامــي بإقامــة عالقــه مــع امــرأ ٍة المتــت‬\n‫لــي بصلــة ودخــول منــزل كفيلهــا واالختــاء بهــا فصحيــح وذلــك أننــي‬\n‫تعرفــت علــى املــرأة املذكــورة وهــي مــن جنســية فلبينيــة وحضــرت إلــى‬\n‫منــزل كفيلهــا وقامــت بتمكينــي مــن دخــول املنــزل وجلســت أتكلــم‬\n\n\n                                                                                         ‫‪304‬‬\n\f      ‫ـأن هنــاك أشــخاص ًا شــاهدوني طلبــت‬                    ‫ـعرت بـ َّ‬\n                                                                      ‫معهــا يف فنــاء املنــزل وملــا شـ ُ‬\n      ‫مت القبــض علــي وأنــا متــزوج لكننــي‬                 ‫منهــا عبــاءة ولبســتها وعنــد اخلــروج َّ‬\n      ‫مطلــق وقــد أســلمت بحمــد اهلل يف الســجن وأرجــو مــن اهلل التوبــة‬\n      ‫واملغفــرة هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة‬\n      ‫ومنهــا كــرت ســوابق املدعــى عليــه املتضمــن عــدم وجــود ســوابق عليــه‬\n      ‫كمــا جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه املتضمنــة‬\n      ‫ـاء علــى ماتقــدم مــن الدعــوى‬                 ‫أ َّنــه أوقــف بتاريخ‪1433/12/11‬ه ـ فبنـ ً‬\n      ‫واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه والتأكــد مــن أهليتــه وبعــد‬\n      ‫أن املدعــى عليــه أقـ َّـر بإقامــة عالقــة‬          ‫دراســة أوراق املعاملــة وتأملهــا ومبــا َّ‬\n      ‫أن‬‫مــع امــرأ ٍة المتــت لــه بصلــة ودخــول منــزل كفيلهــا واالختــاء بهــا ومبــا َّ‬\n      ‫{و َل ُت ْف ِسـ ُـدوا‬\n                          ‫مــا صــدر مــن املدعــى عليــه مــن احملــرم شــرع ًا قــال تعالــى ‪َ :‬‬\n                      ‫{وال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n      ‫الل ال ُي ِحـ ُّـب‬                            ‫ض َب ْعَــد ِإ ْص َلحِ َهــا } وقــال تعالــى ‪َ :‬‬         ‫ِف ْ َ‬\n                                                                                                        ‫ال ْر ِ‬\n      ‫ْال ُْع َتدِ يـ َـن } وقــال صلــى اهلل عليــه وســلم ‪(( :‬كلُّ املســلم علــى املســلم‬\n      ‫وعرضــه)) وقــال صلــى اهلل عليــه وســلم ‪ ( :‬مــا خــا‬                 ‫ُ‬       ‫دم ـ ُه وما ُل ـ ُه‬\n                                                                                                       ‫ـرام ُ‬‫حـ ٌ‬\n      ‫رجــل بامــرأة إال كان الشــيطان ثالثهمــا ) ممايســتوجب تعزيــر املدعــى‬\n      ‫عليــه علــى ذلــك لــذا كلــه وألجــل احلــق العــام حكمت علــى املدعى عليه‬\n      ‫ـدي إدانــة املدعــى عليــه بإقامــة عالقــة مــع امــرأ ٍة‬          ‫مبــا يلــي ‪ :‬أو ًال ‪ /‬ثبــت لـ َّ‬\n      ‫المتــت لــه بصلــة ودخــول منــزل كفيلهــا واالختــاء بهــا وعزرتــه لقــاء ذلــك‬\n      ‫بســجنه ثالثــة أشــهر مــن تاريــخ إيقافــه علــى ذمــة القضيــة وبجلــده ثمانني‬\n      ‫جلــدة علــى دفعتــن متســاويتني كل دفعــة أربعــون جلــدة بــن كل دفعــة‬\n      ‫وأخــرى مــدة التقــل عــن عشــرة أيــام ‪ .‬ثالث ـ ًا ‪/‬يؤخــذ عليــه التعهــد بعــدم‬\n      ‫العــودة ملثــل مــا صــدر منــه ويبعــد عــن اململكــة بعــد انتهــاء محكوميتــه‬\n      ‫ـاء لشــره ‪ .‬وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعــى عليــه بحقــه‬                              ‫اتقـ ً‬\n\n‫‪305‬‬\n\f‫يف متييــز احلكــم بواســطة مترجــم احملكمــة قــرر قناعتــه بــه وطلــب‬\n‫املدعــي العــام رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق‬\n‫احلكــم دون الئحــة اعتراضيــة مكتفي ـ ًا مبــا ورد يف الئحــة الدعــوى‬\n‫وأقفلــت اجللســة الســاعة الثانيــة عشــرة وصلــى اهلل وس ـلَّم علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر يف ‪1434/01/24‬هــ‪ .‬احلمــد‬\n‫هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة األولــى‬\n‫مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء برقــم ‪3426307‬‬\n‫وتاريــخ ‪1434/2/9‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪/34/371707‬ج‪1‬‬\n‫وتاريــخ ‪1434/2/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ املســجل برقــم ‪ 3420794‬وتاريــخ ‪1434/1/24‬ه ـ‬\n‫اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ ........ /‬فلبينــي اجلنســية يف قضيــة‬\n‫اختــاء محــرم وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                         ‫وصحبــه وســلم حــرر يف ‪1434/4/7‬ه ـ‬\n\n\n\n\n                                                                                          ‫‪306‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":301,"source_page_end":306,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0370bc5ce255dbccdb57ba72fb34fd8c15aa05e94f36cc5ec86f9d091b3169b1","normalized_text_hash":"4a327f25311af8fe035facf86a09cbc6903952c7e0855b49cb814bf4f0188d0e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p301-3420794"},{"id":"b6527ac6-dc7e-5fb6-836b-402064915b5a","document_type":"judgment","category":"judicial","subcategory":"general","title":"خلوة محرمة -إقامة عالقة محرمة -إيواء فتاة -تغرير بفتاة قاصر -تغييب فتاة عن أهلها -مطالبة بتعزير للحق اخلاص - إقرار املدعى عليه -مين -التعزير بالسجن واجللد -صرف النظر -قول اهلل تعالى ( :وتعاونوا على البر والتقوى وال تعاونوا على اإلثم والعدوان).","document_number":"3412775","case_number":"3370087","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/14","year":"1434","subject":"خلوة محرمة -إقامة عالقة محرمة -إيواء فتاة -تغرير بفتاة قاصر -تغييب فتاة عن أهلها -مطالبة بتعزير للحق اخلاص - إقرار املدعى عليه -مين -التعزير بالسجن واجللد -صرف النظر -قول اهلل تعالى ( :وتعاونوا على البر والتقوى وال تعاونوا على اإلثم والعدوان).","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3412775 :‬تاريخه ‪1434/1/14:‬هـ‬\n                         ‫رقم الدعوى‪3370087 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34229755‬تاريخه‪1434/6/4 :‬هـ‬\n\n\n      ‫خلــوة محرمــة ‪ -‬إقامــة عالقــة محرمــة ‪ -‬إيــواء فتــاة ‪ -‬تغريــر بفتــاة‬\n      ‫قاصــر ‪ -‬تغييــب فتــاة عــن أهلهــا ‪ -‬مطالبــة بتعزيــر للحــق اخلــاص ‪-‬‬\n      ‫إقــرار املدعــى عليــه ‪ -‬ميــن ‪ -‬التعزيــر بالســجن واجللــد ‪ -‬صــرف النظــر‬\n\n\n\n\n      ‫‪ -‬قــول اهلل تعالــى ‪( :‬وتعاونــوا علــى البــر والتقــوى وال تعاونــوا علــى‬\n                                                                ‫اإلثــم والعــدوان)‪.‬‬\n      ‫‪ -‬قولــه تعالــى (إن الذيــن يحبــون أن تشــيع الفاحشــة يف الذيــن آمنــوا‬\n                                         ‫لهــم عــذاب أليــم يف الدنيــا واآلخــرة )‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه عــن اتهامــه بالتغريــر بفتــاة‬\n      ‫قاصــر‪ ،‬وإقامــة عالقــة محرمــة‪ ،‬وتغييبهــا‪ ،‬وإيوائهــا يف منزلــه‪،‬‬\n      ‫حيــث تقــدم أحــد األشــخاص مخبــر ًا عــن تغيــب ابنتــه عــن منزلــه‪،‬‬\n      ‫وطلــب املدعــي العــام تعزيــر املدعــى عليــه لقــاء مــا نســب إليــه ومصــادرة‬\n      ‫اجلــوال املســتخدم يف اجلرميــة‪ ،‬أقــر املدعــى عليــه بدعــوى املدعــي العــام‬\n      ‫بخصــوص العالقــة وأنكــر مــا ســوى ذلــك‪ ،‬طلــب مــن املدعــي العــام‬\n      ‫بينتــه علــى دعــواه فذكــر انــه ليــس لديــه إال مــا جــاء يف أوراق املعاملــة‪:‬‬\n      ‫ومنهــا محضــر االســتجواب واملتضمــن انطبــاق مــا ذكرتــه الفتــاة علــى‬\n\n‫‪307‬‬\n\f‫صفــة الشــقة العائــدة للمدعــى عليــه ‪ ،‬حكمــت احملكمــة للشــبهة‬\n‫بتعزيــر املدعــى عليــه بالســجن واجللــد لقــاء توجــه التهمــة بحــق مــا جــاء‬\n‫يف دعــوى املدعــي العــام ‪ ،‬قنــع املدعــى عليــه باحلكــم ‪ ،‬واملدعــي العــام‬\n‫قــرر اعتراضــه علــى احلكــم بالئحــة اعتراضيــة ‪ ،‬صــدق احلكــم مــن‬\n‫محكمــة االســتئناف ‪ ،‬حضــر املدعــي اخلــاص وطلــب حقــه اخلــاص مــن‬\n‫املدعــى عليــه وذلــك بتعزيــر املدعــى عليــه ‪ ،‬أنكــر املدعــى عليــه مــا‬\n‫جــاء بدعــوى املدعــي اخلــاص ‪ ،‬طلــب مــن املدعــي اخلــاص بينتــه علــى‬\n‫دعــواه ضــد املدعــى عليــه ‪ ،‬فقــرر أنــه ليــس لديــه بينــة ســوى مــا جــاء‬\n‫يف أوراق املعاملــة ‪ ،‬وجــرى إفهامــه بــأن لــه ميــن املدعــى عليــه علــى نفــي‬\n‫دعــواه ‪ ،‬فوافــق علــى ذلــك وبعــرض اليمــن علــى املدعــى عليــه‪ ،‬حلفهــا‬\n‫علــى الصفــة املطلوبــة‪ .‬حكمــت احملكمــة بصــرف النظــر عــن دعــوى‬\n‫املدعــي اخلــاص ضــد املدعــى عليــه ‪ ،‬قنــع املدعــي اخلــاص واملدعــى عليــه‬\n‫باحلكــم ‪ ،‬أمــر القاضــي املدعــي العــام التحقيــق مــع الفتــاة ‪ ،‬وتطبيــق‬\n‫نظــام اإلجــراءات اجلزائيــة يف حقهــا حســب التعليمــات ألن املــرأة خرجــت‬\n                                                           ‫بطوعهــا واختيارهــا ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة‬\n‫اجلزائيــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم وتاريــخ‬\n‫‪ 1433/12/25‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ ‪1433/12/22‬‬\n‫ه ـ ففــي يــوم األربعــاء املوافــق‪ 1434/01/07‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 11 : 45‬وفيهــا حضــر املدعــي العــام املكلــف باالدعــاء العــام‬\n\n                                                                                     ‫‪308‬‬\n\f      ‫مبوجــب خطــاب هيئــة التحقيــق واالدعــاء العــام رقــم ‪ 15832‬وتاريــخ‬\n      ‫‪1433/3/6‬ه ـ وأدعــى قائــا بصفتــي عضــو هيئــة التحقيــق واالدعــاء‬\n      ‫العــام بدائــرة محافظــة جــدة أدعــي علــى ‪)36( ........‬عام ـ ًا محصــن‬\n      ‫‪ ........‬ســعودي اجلنســية ‪ ،‬مبوجــب ســجل مدنــي رقم(‪،)....‬قبــض‬\n      ‫عليــه بتاريــخ ‪1433/11/1‬ه ـ وأوقــف مبوجــب أمــر التوقيــف رقــم ه ـ‬\n      ‫م‪70692/3/2‬وتاريــخ ‪1433/11/2‬ه ـ وأحيــل لســجون محافظــة جــدة‬\n      ‫مبوجــب أمــر التمديــد رقــم ه ـ م‪ 73265/3/2‬وتاريــخ ‪1433/11/15‬ه ـ‬\n      ‫اســتنادا للمــادة (‪ )113‬مــن نظــام اإلجــراءات اجلزائيــة حيــث أنــه بتاريــخ‬\n      ‫‪1433/11/26‬ه ـ قبــض علــى املتهــم أعــاه بعــد أن تقــدم املواطــن‪........‬‬\n      ‫تغيــب ابنتــه‪)15(، ........‬عام ـ ًا ‪،‬عــن منــزل ذويهــا وبســماع أقــوال‬\n      ‫الفتــاة‪)15( ........‬عام ـ ًا ذكــرت أنهــا تعرفــت علــى املتهــم عــن طريــق‬\n      ‫اإلنترنــت وكان بينهمــا مكاملــات وقــد تقــدم خلطبتهــا مــن والدهــا ولــم‬\n      ‫يوافــق والدهــا علــى زواجهمــا‪ ،‬وأنــه قــام املتهــم باحلضــور إلــى منزلهــا يف‬\n      ‫‪ ........‬وأخذهــا ملنزلــه يف ‪ ........‬وبقيــت عنــده مــن يــوم األربعــاء إلــى يــوم‬\n      ‫األحــد وكان يوجــد معهــا شــقيقات املتهــم ‪ ،‬وبعــد ذلــك أعادهــا ملنــزل‬\n      ‫والدهــا يف ‪ ،........‬كمــا ذكــرت أن ســبب خروجهــا مــن منزلهــا هــو‬\n      ‫وجــود خــاف بينهــا وبــن والدهــا وبســؤال شــقيقة املتهــم الفتــاة‪، ........‬‬\n      ‫(‪)22‬عامـ ًا بأنهــا ليــس لهــا عالقــة باملدعيــة ولــم تكــن موجــودة باملنــزل‬\n      ‫أثنــاء تواجــد الفتــاة كمــا تدعــي‪ ،‬وبوصفهــا ملنــزل شــقيقها املتهــم‬\n      ‫انطبقــت األوصــاف علــى مــا ســبق وادعــت بــه املدعيــة وباســتجواب‬\n      ‫املتهم‪........‬أفــاد بأنــه تعــرف علــى الفتــاة عــن طريــق اإلنترنــت وأصبــح‬\n      ‫بينهمــا مكاملــات هاتفيــة وبعــد ذلــك ذهــب لوالــد الفتــاة خلطبتهــا والــذي‬\n      ‫قــام برفضــه ولكنــه لــم يحضرهــا ملنزلــه وبالبحــث عــن ســوابقه عثــر لــه‬\n\n\n‫‪309‬‬\n\f‫علــى قضيــة ســابقة أحيلــت للمحكمــة اجلزئيــة برقــم ه ـ م‪56518/3/2‬‬\n‫وتاريــخ ‪1433/8/20‬ه ـ بتهمــة إقامــة عالقــة بفتــاة واالختالء بهــا وتقبيله‬\n‫لهــا وقــد أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليــه بتغريــره‬\n‫بفتــاة قاصــر وإقامــة عالقــة محرمــة معهــا وتغييبهــا وإيوائهــا مبنزلــه‬\n‫‪،‬وذلــك لألدلــة والقرائــن التاليــة مــا جــاء بأقــوال املتهــم املدونــة مبحضــر‬\n‫االســتجواب املرفــق لفــه رقــم (‪ )13‬صفحــة رقــم (‪ )2-1‬مــا جــاء بأقــوال‬\n‫الفتــاة املدونــة مبحضــر االســتجواب لفــه رقــم (‪ )13‬صفحــة رقــم(‪)5-4‬‬\n‫وانطبــاق مــا ذكرتــه مــن وصــف علــى شــقة املتهــم وحيــث إن مــا أقــدم‬\n‫عليــه املذكــور يعــد فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات‬\n‫مــا نســب إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك كمــا أطلــب‬\n‫مصــادرة جهــاز اجلــوال املســتخدم يف اجلرميــة نــوع ‪ ....‬موديــل واحملجــوز‬\n                         ‫برقــم ه ـ م‪ 79422/3/2‬وتاريــخ ‪1433/12/18‬هــ‪.‬‬\n‫وبعــرض مــا ورد بدعــوى املدعــي العــام علــى املدعــي عليــه احلاضــر يف‬\n‫ا مــا ذكــر املدعــي العــام يف دعــواه مــن‬      ‫املجلــس الشــرعي قــرر قائ ـ ً‬\n‫توجيــه االتهــام لــي بالتغريــر بفتــاه قاصــر وإقامــة عالقــة محرمــه معهــا‬\n‫وتغيبهــا وإيوائهــا مبنزلــي فغيــر صحيــح جملــة وتفصيــا والصحيــح أننــي‬\n‫قــد تقدمــت لطلــب خطبــه الفتــاة املذكــورة عــن طريــق أحــد مواقــع‬\n‫الــزواج وأعطانــي املوقــع رقــم والدهــا وتواصلــت معــه وطلبــت منــه الــزواج‬\n‫مــن أبنتــه فرفــض ذلــك إال أن الفتــاه اتصلــت علــى وأخبرتنــي برغبتهــا‬\n‫بالــزواج منــي وأخــذت تتواصــل معــي وتخبرنــي عــن عــدم اقتناعهــا مبــا‬\n‫أتخــذه أهلهــا مــن قــرار بعــدم املوافقــة علــى الــزواج منــي وأخبرتنــي‬\n‫أنهــا ســتهرب إلــى جدهــا ألجــل الضغــط علــى أهلهــا إلقناعهــم بالــزواج‬\n‫فنصحتهــا بعــدم فعــل ذلــك ثــم أتصــل علــي والدهــا بعــد ذلــك وســألني‬\n\n\n                                                                                       ‫‪310‬‬\n\f      ‫عــن البنــت فأخبرتــه بذلــك وعــن عــدم معرفتــي مبكانهــا فأخــذ يســبني‬\n      ‫ثــم أغلــق اجلــوال هــذا مــا لــدي وبعــرض ذلــك علــى املدعــي العــام قــال‬\n      ‫الصحيــح مــا ذكــرت وبســؤال املدعــي العــام هــل لديــه بينــه علــى مــا‬\n      ‫ذكــر قــال بينتــي تتمثــل يف أقــوال املتهــم املدونــة مبحضــر االســتجواب‬\n      ‫املرفــق رقــم (‪ )13‬صفحــة رقــم (‪)2-1‬أقــوال الفتــاه املدونــة مبحضــر‬\n      ‫االســتجواب لفــة رقــم (‪)13‬صفحــة رقــم (‪)4-3‬وانطبــاق مــا ذكرتــه مــن‬\n      ‫وصــف علــى شــقة املتهــم عليــه فقــد جــرى االطــاع علــى أوراق املعاملــة‬\n      ‫فوجدتهــا طبقــا ملــا ذكــر املدعــي العــام يف الئحتــه كمــا وجــدت تطابــق‬\n      ‫أقــوال الفتــاه مــع أقــوال شــقيقة املتهــم يف وصــف الشــقة العائــدة لــه هــذا‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا ورديف أقــوال املدعــى‬\n      ‫عليــه وجوابــه علــى الدعــوى وحيــث أن املدعــى عليــه توجــد عليــه قضيــة‬\n      ‫أخــرى مشــابهه لهــذه القضيــة مشــار إليهــا يف الئحــة الدعــوى العامــة‬\n      ‫ولقولــه تعالــى (وتعاونــوا علــى البــر والتقــوى وال تعاونــوا علــى اإلثــم‬\n      ‫والعــدوان ) ولقولــه تعالــى (إن الذيــن يحبــون أن تشــيع الفاحشــة يف‬\n      ‫الذيــن آمنــوا لهــم عــذاب اليــم )وجلميــع مــا تقــدم وحيــث أن مــا ســبق ال‬\n      ‫يكفــى إلثبــات إدانــة املتهــم ويقــوى الشــبهة يف حقــه يف توجيــه االتهــام‬\n      ‫لــه مبــا ســبق وجلميــع مــا تقــدم فقــد حكمــت علــى املدعــى عليــه نظيــر‬\n      ‫ذلــك بســجنه ملــده ســنه ونصــف وجلــده مائتــي ســوط علــى دفعــات كل‬\n      ‫دفعــة خمســن ســوط وبــن كل والتــي تليهــا مــده ال تقــل عــن خمســة‬\n      ‫أيــام وبعرضــه علــى الطرفــن قــرر املدعــى عليــه القناعــة وقــرر املدعــي‬\n      ‫العــام عــدم القناعــة وطلــب االســتئناف فجــرى إجابتــه لذلــك وســيجرى‬\n      ‫اتخــاذ الــازم حســب إجــراءات االســتئناف جــرى النطــق باحلكــم يف‬\n      ‫متــام الســاعة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n‫‪311‬‬\n\f                                ‫وصحبــه وســلم حــرر يف ‪ 1434/01/07‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء املوافــق ‪1434/6/20‬ه ـ الســاعة‬\n‫العاشــرة والربــع فتحــت اجللســة لــدي القاضــي باحملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة والقائــم بعمــل القاضــي مبوجــب خطــاب التكليــف رقــم‬\n‫يف ‪1434/5/19‬ه ـ وجــرى اإلطــاع علــى أوراق املعاملــة وكانــت قــد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة وبرفقهــا‬\n‫قرارهــا رقــم يف ‪1434/6/4‬ه ـ باملصادقــة علــى احلكــم ونــص احلاجــة‬\n‫منــه (وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر‬\n‫املوافقــة علــى احلكــم واهلل املوفــق )وموقــع ومختــم مــن اصحــاب‬\n‫الفضيلــة أعضــاء الدائــرة اجلزائيــة الرابعــة وهــم كال مــن الشــيخ ‪........‬‬\n‫والشــيخ ‪ ........‬والشــيخ ‪ ........‬فجــرى تدوينــه حفظــا للواقــع وجــرى قفلهــا‬\n‫يف متــام الســاعة العاشــرة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/20‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي إنــا القاضــي باحملكمــة اجلزائيــة مبحافظة‬\n‫جــده وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة برقــم‬\n‫يف ‪1434/8/23‬ه ـ ويف يــوم األحــد املوافــق ‪1434/9/6‬ه ـ الســاعة‬\n‫الواحــدة وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ ........‬وادعــى علــى الســجني احلاضــر باملجلــس الشــرعي ‪ ........‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬قائــا يف دعــواه إن املدعــى‬\n‫عليــه احلاضــر إمامكــم يف املجلــس الشــرعي قــد قــام بالتغريــر بابنتــي‬\n‫وأخذهــا مــن منــزل جدهــا مبحافظــة ‪ ........‬إلــى منزلــه مبحافظــة ‪........‬‬\n‫وغيبهــا عنــده أربعــة أيــام كمــا ورديف الئحــة الدعــوى العامــة ثــم قــام‬\n‫بإعادتهــا لــذا فأنــي آمــل مــن فضيلتكــم معاقبــة املدعــى عليــه يف حقــي‬\n\n\n                                                                                      ‫‪312‬‬\n\f      ‫اخلــاص حيــال مــا بــدر منــه هــذه دعــواي واســأله اجلــواب وبعــرض مــا‬\n      ‫ورد بدعــوى املدعــي علــى املدعــى عليــه قــال مــا ورد يف دعــوى املدعــي‬\n      ‫اخلــاص فغيــر صحيــح جملــة وتفصيــا وبســؤال املدعــي عــن بينتــه فقــال‬\n      ‫بينتــي هــي مــا ورد يف أوراق املعاملــة وحيــث أن مــا ورد يف أوراق املعاملــة‬\n      ‫ال يكفــي إلثبــات مــا ورد يف دعــوى املدعــي كمــا تقــدم عليــه فقــد‬\n      ‫جــرى ســؤاله هــل لديــه بينــه علــى مــا ذكــر قــال ال بينتــه لــدي عليــه فقــد‬\n      ‫جــرى إفهامــه بــأن لــه ميــن املدعــى عليــه علــى نفــي مــا ورد يف دعــواه‬\n      ‫فقــال اطلــب ميينــه وبعــرض اليمــن علــى املدعــى عليــه اســتعد احللــف‬\n      ‫قائــا واهلل العظيــم الــذي ال الــه إال هــو عالــم الغيــب والشــهادة إن مــا‬\n      ‫ورد يف دعــوى املدعــي اخلــاص غيــر صحيــح فلــم أقــم بأخــذ بنــت املدعــي‬\n      ‫اخلــاص وال تغييبهــا وال إيوائهــا واهلل العظيــم هــذا فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة وحلــف املدعــى عليــه اليمــن كمــا طلــب منــه‬\n      ‫فقــد صرفــت النظــر عــن دعــوى املدعــي اخلــاص وبعرضــه علــى الطرفــن‬\n      ‫قــررا القناعــة وحيــث إن الفتــاة قــد خرجــت يطوعهــا واختيارهــا كمــا‬\n      ‫ورد يف ملــف القضيــة لــذا فقــد أمــرت املدعــي العــام التحقيــق مــع الفتــاة‬\n      ‫وتطبيــق نظــام اإلجــراءات اجلزائيــة يف حقهــا حســب التعليمــات وجــرى‬\n      ‫قفلهــا يف متــام الســاعة الواحــدة والنصــف وصلــى اهلل وســلم علــى نبينــا‬\n                                   ‫محمــد والــه وصحبــه وســلم حرر‪1434/9/6‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ ...‬نحــن رئيــس‬\n      ‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقة مكة‬\n      ‫املكرمــة جــرى منــا االطــاع علــى القــرار رقــم وتاريــخ ‪1434/1/14‬ه ـ‬\n      ‫الصــادر مــن فضيلــة الشــيخ‪ ........‬القاضــي باحملكمــة اجلزائيــة بجــدة‪،‬‬\n      ‫املتضمــن دعــوى املدعــي العــام ضــد‪ ، ........‬املتهــم بإقامــة عالقــة محرمــة‬\n\n\n‫‪313‬‬\n\f‫بفتــاة واالختــاء بهــا وتقبيلــه لهــا ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n‫وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة‬\n‫علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                             ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                 ‫‪314‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":307,"source_page_end":314,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3abf0dedfc6292e8890d6069ea64ae6a7eb2516be52ee812bbdd1850897719a1","normalized_text_hash":"4ae4d632c93d2750004c264c3a565c2202dbd0b61ac3fa594de37ff6f6550379","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p307-3412775"},{"id":"e4edca14-b96a-59b1-9798-cf21ad939ac8","document_type":"judgment","category":"judicial","subcategory":"general","title":"إقامة عالقة محرمة مع فتاة -ابتزاز فتاة -تهديد بنشر صور - عدم ثبوت اإلدانة -تعزير للشبهة -تعزير بالسجن واجللد.","document_number":"33299196","case_number":"33306253","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/15","year":"1434","subject":"إقامة عالقة محرمة مع فتاة -ابتزاز فتاة -تهديد بنشر صور - عدم ثبوت اإلدانة -تعزير للشبهة -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33299196 :‬تاريخه‪1433/6/15 :‬هـ‬\n                         ‫رقم الدعوى‪33306253 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 35272648‬تاريخه‪1435/6/17:‬هـ‬\n\n\n      ‫إقامــة عالقــة محرمــة مــع فتــاة ‪ -‬ابتــزاز فتــاة ‪ -‬تهديــد بنشــر صــور ‪-‬‬\n            ‫عــدم ثبــوت اإلدانــة ‪ -‬تعزيــر للشــبهة ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــول اهلل تعالــى‪( :‬إن الذيــن يحبــون أن تشــيع الفاحشــة يف الذيــن‬\n      ‫آمنوا لهم عذاب أليم يف الدنيا و اآلخرة و اهلل يعلم و أنتم ال تعلمون)‬\n                                                                       ‫النــور آيــة (‪.)19‬‬\n                                  ‫‪ -2‬قاعدة اإلقرار حجه على صاحبه مؤاخذ به ‪.‬‬\n      ‫‪ -3‬الرجــوع عــن اإلقــرار مبــا يوجــب التعزير حلق اهلل تعالى ال يقبل من‬\n      ‫صاحبــه جــاء يف املغنــي (‪( .)389/10‬وال يقبــل رجــوع املقــر عــن إقــراره إال‬\n      ‫فيمــا كان حــد ًا هلل تعالــى يــدرأ بالشــبهات ويحتــاط إلســقاطه فأمــا‬\n      ‫حقــوق اآلدميــن وحقــوق اهلل تعالــى التــي ال تدرأ بالشــبهات كالزكاة‬\n                   ‫والكفــارات فــا يقبــل رجوعــه عنهــا و ال نعلــم يف هــذا خالفـ ًا)‬\n\n\n\n      ‫توجــه االتهــام للمدعــى عليــه األول بالتســتر علــى املتهــم الثانــي يف قضيــة‬\n      ‫إقامــة عالقــة محرمــة مــع فتــاة وابتزازهــا وتهديــده للفتــاة وعلــى املدعــي‬\n      ‫عليــه الثانــي بإقامــة عالقــة محرمــة مــع فتــاة وابتزازهــا وتهديدهــا بنشــر‬\n      ‫صورهــا‪ ،‬حيــث تلقــى مركــز هيئــة األمــر باملعــروف والنهــي عن املنكر‬\n\n‫‪315‬‬\n\f‫اتصــا ًال هاتفيـ ًا مــن فتــاة تســتنجد وتســتغيث مــن قيــام شــاب بتهديدهــا‬\n‫وابتزازهــا بصــور قــد حتصــل عليهــا عــن طريــق عالقــة محرمــة بينهمــا‪،‬‬\n‫وأن الشــاب حتصــل علــى مبلــغ عشــرة آالف ريــال مــن الفتــاة عــن طريــق‬\n‫االبتــزاز‪ ،‬وأن الفتــاة حتصلــت علــى هــذا املبلــغ عــن طريــق الســرقة مــن‬\n‫والدتهــا ومكافأتهــا اجلامعيــة‪ ،‬حضــر املدعــى عليــه الثانــي برفقــة‬\n‫األول ملنــزل الفتــاة ألخــذ بطاقــة الصــراف ‪ ،‬ألقــت الفتــاة البطاقــة خــارج‬\n‫الســور‪ ،‬أخــذ املدعــى عليــه الثانــي البطاقــة فتــم القبــض عليــه مــن قبــل‬\n‫أعضــاء هيئــة األمــر باملعــروف والنهــي عــن املنكــر‪ ،‬بتفتيــش جــوال‬\n‫املدعــى عليــه الثانــي وجــدت رســائل التهديــد‪ ،‬طلــب املدعــي العــام إثبات‬\n‫إدانتهمــا مبــا نســب إليهمــا واحلكــم علــى املدعــى عليــه الثانــي بالســجن‬\n‫والغرامــة أو بإحــدى هاتــن العقوبتــن ومصــادرة الهاتــف اجلــوال العائــد‬\n‫للمدعــى عليــه الثانــي واحلكــم عليهمــا بعقوبــة تعزيريــة والتشــديد علــى‬\n‫املدعــى عليــه الثانــي‪ ،‬لــم يحضــر املدعــى عليــه األول‪ ،‬حضــر املدعــى‬\n‫عليــه الثانــي و جــرى عــرض الدعــوى عليــه فأنكــر جميع ما نســب إليه‪،‬‬\n‫أحضــر املدعــي العــام بينتــه عضــوي هيئــة األمــر باملعــروف و النهــي عــن‬\n‫املنكــر ‪ ،‬شــهدا مبــا جــاء يف محضــر القبــض‪ ،‬أقــر املدعــى عليــه الثاني‬\n‫بــأن بطاقــة الصــراف اخلاصــة بالفتــاة بحوزتــه وذلــك مــن أجــل اســتيفاء‬\n‫مســتحقات ماليــة‪ ،‬جــرى االطــاع علــى محاضــر التحقيــق ومشــاهدة‬\n‫الرســائل وبرنــت املكاملــات الصــادرة والــواردة مــن هاتــف املدعــى‬\n‫عليــه الثانــي‪ ،‬صــدر احلكــم بإدانــة املدعــى عليــه الثانــي بإقامــة عالقــة‬\n‫محرمــة مــع فتــاة ال متــت لــه بصلــة‪ ،‬لــم تثبــت اإلدانــة باالبتــزاز والتهديــد‬\n‫ونشــر الصــور وإمنــا توجــه الشــبهة لذلــك‪ ،‬حكمــت احملكمــة بتعزيــر‬\n‫املدعــى عليــه الثانــي بالســجن ســنتني وجلــده مائتــي جلــدة مفرقــة علــى‬\n\n\n                                                                                         ‫‪316‬‬\n\f      ‫أربــع دفعــات ‪ ،‬صــرف النظــر عــن طلــب املدعــي العــام بتطبيــق املادتــن‬\n      ‫(‪ )13/3‬مــن نظــام مكافحــة اجلرائــم املعلوماتيــة ‪ ،‬صــدق احلكــم مــن‬\n                                                            ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ .....‬القاضــي باحملكمــة اجلزئيــة بتبــوك‬\n      ‫بنــاء علــى املعاملــة الــواردة إلــى احملكمــة مــن هيئــة التحقيــق واإلدعــاء‬\n      ‫العــام بتبــوك بكتابهــم رقــم ‪ .....‬وتاريــخ ‪1433/4/28‬ه ـ واحملالــة إلــي‬\n      ‫مــن فضيلــة الرئيــس املســاعد برقــم ‪ 33306253‬وتاريــخ ‪1433/5/2‬ه ـ‬\n      ‫عليــه حضــر املدعــي العــام ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ .....‬واملكلــف لــدى احملكمــة مبوجــب كتــاب التعميــد رقــم يف‬\n      ‫‪1432/11/13‬ه ـ وادعــى علــى الغائــب عــن مجلــس احلكــم ‪ .....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬واحلاضــر معــه ‪ .....‬ســعودي‬\n      ‫ا يف حتريــر دعــواه إنــه‬    ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬قائـ ً‬\n      ‫بتاريــخ ‪1433/3/4‬ه ـ ورد ملركــز شــرطة اخلالديــة محضــر الدوريــات‬\n      ‫األمنيــة رقــم (‪ ).......‬ومحضــر مركــز هيئــة اخلالديــة لألمــر باملعــروف‬\n      ‫والنهــي عــن املنكــر رقــم (‪ ).....‬املتضمــن القبــض علــى كل مــن املدعــو‪/‬‬\n      ‫‪ .....‬واملدعــو‪ ..... /‬بتهمــة تهديــد وابتــزاز حيــث تضمن محضر هيئة األمر‬\n      ‫باملعــروف والنهــي عــن املنكــر تلقيهــم اتصــال هاتفــي مــن فتــاة تســتنجد‬\n      ‫وتســتغيث مــن قيــام شــاب بتهديدهــا وابتزازهــا بصــور قــد حتصــل عليها‬\n      ‫عــن طريــق عالقــة محرمــة بينهمــا التــي أصبــح يتخذهــا وســيلة للضغــط‬\n      ‫علــى الفتــاة حتــى تســتجيب ملطالبــه الدنيئــة واحلصــول علــى املبالــغ املاليــة‬\n      ‫التــي يريدهــا مبينـ ًا للفتــاة أنــه ســوف يقــوم بنشــر صورهــا وفضــح أمرهــا‬\n\n‫‪317‬‬\n\f‫عنــد إخوتهــا إن لــم تســتجب لــكل مطالبــه حيــث حتصــل علــى مبلــغ‬\n‫مالــي وقــدره عشــرة آالف ريــال أرغمهــا علــى ســرقته مــن أمهــا إضافــة‬\n‫إلــى مبالــغ ماليــة أخــرى حتصــل عليهــا عــن طريــق مكافــأة اجلامعــة‬\n‫ويطلــب منهــا أيض ـ ًا متكينــه مــن نفســها وقــد اختلــى بهــا عــدة مــرات‬\n‫وأفــادت أنــه يحتفــظ علــى صورهــا بذواكــر يضعهــا يف منزلــه وتقدمــت‬\n‫بشــكوى خطيــة مرفــق صــوره منهــا إضافــة إلــى محاضــر مشــاهدة‬\n‫للرســائل التــي قــام الشــاب بإرســالها إلــى جــوال الفتــاة مرفــق صــور‬\n‫منهــا ويف هــذا اليــوم قــام الشــاب باالتصــال علــى جــوال الفتــاة وطلــب‬\n‫منهــا إعطائــه مبلــغ مالــي وقــدره ألــف ريــال وألــح يف طلبهــا وأنــه ســوف‬\n‫ا لتقــوم الفتــاة برمــي بطاقــة‬  ‫يحضــر إلــى منزلهــا بعــد الســاعة ‪ 12‬لي ـ ً‬\n‫الصــراف اآللــي اخلاصــة بهــا أمــام املنــزل ليقــوم هــو بــدوره باحلصــول علــى‬\n‫املبلــغ املالــي مــن حســابها فتــم التنســيق مــع الدوريــات األمنيــة مســبق ًا‬\n‫واالنتقــال للموقــع للتحــري والتثبــت أثنــاء ذلــك حضــرت ســيارة مــن نــوع‬\n‫‪ .....‬حتمــل الرقــم (‪ ).....‬والتــي يســتقلها املدعــى عليهمــا األول والثانــي‬\n‫وقامــت بالوقــوف أمــام منــزل الفتــاة فقــام الراكــب وهــو املدعــى عليــه‬\n‫الثانــي (الــذي يقــوم بتهديــد الفتــاة) بالنــزول أمــام املنــزل حيــث قامــت‬\n‫الفتــاة برمــي بطاقــة الصــراف اآللــي لــه وعــاد إلــى ســيارة زميلــه وعنــد‬\n‫محاولــة قائــد الســيارة املدعــى عليــه األول وزميلــه املدعــى عليــه الثانــي‬\n‫مغــادرة املوقــع مت اســتيقافهما مبســاندة الدوريــات األمنيــة والقبــض‬\n‫عليهمــا فعثــر بحــوزة املدعــى عليــه الثانــي علــى جهــاز جــوال مــن نــوع‬\n‫‪ ......‬يحتــوي علــى الرقــم (‪ ).....‬الــذي يســتخدمه بتهديــد الفتــاة وابتزازهــا‬\n‫وبطاقــة الصــراف اآللــي التــي أخذهــا مــن الفتــاة وأفــاد أنــه حتصــل علــى‬\n‫مبلــغ مالــي قــدره عشــرة آالف ريــال مــن الفتــاة إضافــة إلــى مبالــغ ماليــة‬\n\n\n                                                                                       ‫‪318‬‬\n\f      ‫أخــرى وقــد حتصــل أيضـ ًا علــى صورهــا التــي اتخذهــا وســيلة لتهديدهــا‬\n      ‫وابتزازهــا وإرغامهــا لالســتجابة ملطالبــه أمــا الســائق وهــو املدعــى عليــه‬\n      ‫األول فهــو مــن قــام بإيصــال املدعــى عليــه الثانــي بســيارته إلــى منــزل‬\n      ‫الفتــاة وهــو علــى إطــاع مبــا يقــوم بــه املدعــى عليــه الثانــي مــن تهديــدات‬\n      ‫للفتــاة ويخشــى منــه أن يفضــح أمــر الفتــاة ومت إحالتهمــا ملركــز شــرطة‬\n      ‫‪ ........‬وقــد مت إعــداد محاضــر مشــاهدة للرســائل مــن قبــل أعضــاء هيئــة‬\n      ‫األمــر باملعــروف والنهــي عــن املنكــر وكانــت علــى النحــو التالــي أ‪/‬‬\n      ‫فهــذا مــا متــت مشــاهدته مــن رســائل مرســلة مــن جــوال الشــاب املهــدد‬\n      ‫رقــم (‪ ).....‬ورقــم (‪ ).....‬إلــى جــوال الفتــاة املبلغــة وهــي علــى النحــو التالــي‬\n      ‫‪(.1‬ورب البيــت مــو تهديــد إال فعــل وأنــا عــارف ليــش تســوي كــذا تبغــي‬\n      ‫متلكــي خيــر إن شــاء اهلل واهلل لفركشــها وأنــا دريــت بــكل شــيء)‬\n      ‫مــن جــوال رقــم (‪ ).....‬وتاريــخ ‪ 2012/1/23‬م يف متــام الســاعة ‪ 1:40‬م‬\n      ‫‪(.2‬تكفــي فزعتــك أبــي ‪ 1000‬واهلل غالتــك عنــدي مــا بنســاها لــك‬\n      ‫وبردهــا لــك بأســرع وقــت وعــد ولــي يســعدك حبيبتــي) مــن جــوال رقــم‬\n      ‫(‪ ).....‬وتاريــخ ‪ 2012/1/22‬م يف متــام الســاعة ‪10:40‬م ‪(.3‬تــري واهلل‬\n      ‫أدري انــه انتظــار حتــى لــو قفلتــي اخلــط لكــن تشــويف اليــوم ردت فعلــي)‬\n      ‫مــن جــوال رقــم (‪ ).....‬وتاريــخ ‪ 2012/1/22‬م يف متــام الســاعة ‪ 5:32‬م‬\n      ‫‪(.4‬يعنــي الزم اخربهــا معاكــي عشــان حتترمينــي طيــب) مــن جــوال رقــم‬\n      ‫(‪ ).....‬يف تاريــخ ‪ 2012/1/22‬م يف متــام الســاعة ‪ 1:12‬ص ‪(.5‬شــايفتيني‬\n      ‫غبــي يصيــر خيــر بــس خلينــي اتشــافى) مــن جــوال رقــم (‪ ).....‬ويف تاريــخ‬\n      ‫‪ 2012/1/21‬م ويف متــام الســاعة ‪ 7:31‬م ب‪ /‬فهــذا مــا متــت مشــاهدته‬\n      ‫مــن رســائل مرســلة مــن جــوال الشــاب املهــدد رقــم (‪ ).....‬إلــى جــوال الفتــاة‬\n      ‫املهــددة وهــي علــى النحــو التالــي ‪( :‬ال تســتحقريني ورب الكعبــة تــرى‬\n\n\n‫‪319‬‬\n\f‫أســويها) (كلمينــي احلــن وال واهلل أكــون أبــن حــرام لــو مــا ســويتها)‬\n‫(يازفــت احنــا ماتفقنــا الصبــاح وكيــف مــا تقــدري تكلمينــي وجوالــك‬\n‫كان انتظــار واهلل تــرى جــاد واهلل مــا يصبح الصبح إال واخوانك داريني‬\n‫بــكل شــيء واهلل عــادي إذا أنتــي مســتحقرتني ومنتــي شــايفتني شــيء‬\n‫واهلل مــا أشــوفك شــيء أبغــى افهــم ليــش مــا تبغــي تكلمينــي) (واهلل مــا‬\n‫لــو مــا تكلمينــي احلــن جليــب العيــد احلــن) (شــويف أنــا بكتــب بورقــة أنــا‬\n‫وأحطهــا عنــد البــاب احلــن بعــد الصــاة بــس قرصــة أذن لكــي علشــان‬\n‫تعــريف أنــي جــاد) (واهلل حلطهــا جــوا الســيارة علشــان مــا ميديــك تأخذيهــا‬\n‫بدخلهــا مــع فتحــة القــزاز) (كذابــة أنتــي وعدتينــي الصبــاح لكــن‬\n‫صادقــة اللــي قالــت عنــك راعيــت ســواقني لكــن طبيعــي واهلل ألخلــي‬\n‫أخوانــك مــن ظهــر رجــال) (وعنــدي اإلثبــات والدليــل واهلل ألربيكــي‬\n‫وال مــا أكــون مــن ظهــر رجــال) (مــا توقعــت أنــه يجــي يــوم وأســويها‬\n‫لكــن خلــي اهلل يكبــر برأســك ينفعــك علــى بالــك مــا أعــرف وضعــك‬\n‫أكثــر مــن ســنتني وأنــا معاكــي أدري لــو تبغــي تكلمينــي كلمتينــي‬\n‫لكــن أنــا احلــن واقــف عنــد املســجد الزنــك خليهــم بــس يدخلــوا بيوتهــم‬\n‫واهلل ألســويها) (واهلل رقــم وعنــدي ألعطيهــا صــورك) ج‪ /‬فهــذا مــا متــت‬\n‫مشــاهدته مــن رســائل مرســلة مــن جــوال الشــاب املهــدد رقــم (‪ ).....‬إلــى‬\n‫جــوال الفتــاة املهــددة وهــي علــى النحــو التالــي ( ‪ .....‬أنتــي وحــده كذابــة‬\n‫وتصرفاتكــي واضحــة لكــن خيــر إن شــاء اهلل اليــوم) (واهلل لربيكــي‬\n‫علــى احلركــة) (مكذبــة أيــن أســويها طيــب شــويف أيــش بحــط علــى‬\n‫الســيارة اللــي بــرا) (واهلل لقلبهــا عــزا الليلــة وأنــا احلــن طالــع لبيتــك)‬\n‫(شــغلي الوســائط يف شــيء راح يعجبــك) (علشــان االنتظــار واهلل حلطهــا‬\n‫احلــن يــاهلل طســي) (خليــك قدهــا) د ‪ /‬فهــذا مــا متــت مشــاهدته مــن‬\n\n\n                                                                                       ‫‪320‬‬\n\f      ‫رســائل مرســلة مــن جــوال الشــاب املهــدد رقــم (‪ ).....‬علــى جــوال الفتــاة‬\n      ‫املهــددة وهــي علــى النحــو التالــي (موعدنــا الصبــاح يــا ال تقولــي إنــي‬\n      ‫ماكلمتــك) (طيــب أرميهــا مــن فــوق مبحفظــه تــرى مــو اختــراع)‬\n      ‫(كلمتــي مــا أثنيهــا وال تنتظــري منــي أي رســالة بعــد هــذي الرســالة‬\n      ‫الصبــاح باتصــل اتصــال ولــو مــا رديتــي وقتهــا تشــويف ردة فعلــي)‪ .‬وقــد‬\n      ‫مت اإلطــاع علــى برنــت املكاملــات ووجــد فيــه عــدة اتصــاالت ورســائل‬\n      ‫واردة وصــادرة مــن رقــم جــوال املتهــم الثانــي (‪ ).....‬إلــى جــوال الفتــاة‪.....‬‬\n      ‫رقــم (‪ ).....‬وإلــى اجلــوال رقــم (‪ )....‬وبضبــط إفــادة الفتــاة املبتــزة ‪.....‬‬\n      ‫واملعرفــة مــن قبــل عضــو هيئــة األمــر باملعــروف والنهــي عــن املنكــر ‪.....‬‬\n      ‫أفــادت بأنهــا قبــل ســنتني قامــت بالتعــرف علــى املدعــى عليــه الثانــي عــن‬\n      ‫طريــق الترقيــم وبــدأت العالقــة بينهمــا باملكاملــات ثــم خرجــت معــه‬\n      ‫مــرات عديــدة وقــد قــام بتصويرهــا بوضــع مخــل وقــد أغواهــا الشــيطان‬\n      ‫وذلــك عــن طريــق جهــازه اجلــوال وكان ذلــك يف بيــت عمه ثــم أخبرها أنه‬\n      ‫سيمســح الصــور ولــم تــرى الصــور بعدهــا صــار يطلــب منهــا مبالــغ ماليــة‬\n      ‫وكانــت تســلمه هــذه املبالــغ بعدهــا صــار يرســل لهــا رســائل ويطلــب‬\n      ‫فيهــا مطالــب ويهددهــا بالصــور بعدهــا قامــت بكتابــة شــكوى ورفعهــا‬\n      ‫للهيئــة وذكــرت أن أرقــام اجلــواالت التــي يقــوم بتهديدهــا هــي ثالثــة‬\n      ‫أرقــام وأنهــا ال حتفــظ إال رقــم واحــد وهــو ( ‪ ).....‬وباســتجواب املدعــى‬\n      ‫عليــه األول‪ ..... /‬بعــد إحاطتــه علم ـ ًا باجلهــة التــي تباشــر التحقيــق معــه‬\n      ‫وبالتهمــة املنســوبة إليــه أنكــر قيامــه بالتســتر علــى املدعــى عليــه الثانــي‬\n      ‫يف قضيــة ابتــزاز فتــاة وذكــر بأنــه ال يعلــم عــن عالقــة املدعــى عليــه‬\n      ‫الثانــي بالفتــاة وأن املدعــى عليــه الثانــي لديــه عــدة أرقــام جــواالت لكنــه‬\n      ‫ال يحفــظ إال الرقــم (‪ )........‬وباســتجواب املدعــى عليــه الثانــي‪ ........‬بعــد‬\n\n\n‫‪321‬‬\n\f‫إحاطتــه علمـ ًا باجلهــة التــي تباشــر التحقيــق معــه وبالتهمــة املنســوبة إليــه‬\n‫أنكــر قيامــه بتهديــد وابتــزاز فتــاة وأعتــرف بعالقتــه بالفتــاة ‪ ........‬عــن‬\n‫طريــق الهاتــف واخلــروج مع ـ ًا برضاهــا وذكــر بــأن رقــم اجلــوال (‪)........‬‬\n‫يعــود لــه وأن رقــم اجلــوال (‪ )........‬يعــود لصديقــة الفتــاة ويرفــض ذكــر‬\n‫اســم صديقــة الفتــاة وذكــر بأنــه ال يعــرف الرقــم (‪ )........‬ملــن يعــود‬\n‫وبإجــراء املواجهــة بــن الفتــاة املبتــزة ‪ ........‬واملدعــى عليــه الثانــي أفــادت‬\n‫الفتــاة بقيــام املدعــى عليــه الثانــي بتصويرهــا بوضــع مخــل يف بيــت عمــه‬\n‫وقيامــه بأخــذ مبالــغ ماليــة منهــا وتهديدهــا بنشــر صورهــا وذلــك عبــر‬\n‫رســائل اجلــوال وبســؤال املدعــى عليــه الثانــي عــن دعــوى الفتــاة أنكــر‬\n‫مــا ذكرتــه جملــة وتفصيــا وذكــر املدعــى عليــه الثانــي بأنــه يطلــب‬\n‫إحضــار ولــي أمــر الفتــاة جلهــة التحقيــق لكــي يحلــون املوضــوع ولــم‬\n‫يتبــن جلهــة التحقيــق أثنــاء املواجهــة أي إجــراء وقــد أســفر التحقيــق إلــى‬\n‫توجيــه االتهــام للمدعــى عليــه األول‪ ........‬بالتســتر علــى املتهــم الثانــي يف‬\n‫قضيــة إقامتــه عالقــة محرمــة مــع فتــاة وابتــزازه وتهديــده للفتــاة وتوجيــه‬\n‫االتهــام للمدعــى عليــه الثانــي ‪ ........‬بقيامــة بإقامــة عالقــة محرمــة مــع‬\n‫فتــاة وابتزازهــا وتهديدهــا بنشــر صورهــا وذلــك لألدلــة والقرائــن التاليــة‬\n‫‪ .1‬اعتــراف املدعــى عليــه الثانــي بعالقتــه بالفتــاة وإرســاله رســائل مــن‬\n‫جوالــه رقــم (‪ )................‬للفتــاة املنــوه عنــه املــدون علــى الصفحــات‬\n‫رقــم (‪ )6-5-4‬مــن دفتــر التحقيــق املرفــق علــى اللفــة رقــم (‪.2 )32‬مــا‬\n‫جــاء بأقــوال املدعــى عليــه األول بــأن املدعــى عليــه الثانــي لديــه عــدة‬\n‫أرقــام جــواالت املنــوه عنــه املــدون علــى الصفحتــن رقــم (‪ )2-1‬مــن دفتــر‬\n                                        ‫التحقيــق املرفــق علــى اللفــة رقــم (‪)32‬‬\n‫‪.3‬مــا جــاء باحملضــر املعــد مــن قبــل أعضــاء هيئــة األمــر باملعــروف والنهــي‬\n\n\n                                                                                          ‫‪322‬‬\n\f      ‫عــن املنكــر املنــوه عنــه املرفــق علــى اللفتــن رقــم (‪.4 )20-19‬مــا جــاء‬\n      ‫مبحضــر مشــاهدة الرســائل املعــد مــن قبــل أعضــاء هيئة األمــر باملعروف‬\n      ‫والنهــي عــن املنكــر املنــوه عنــه املرفــق علــى اللفــات رقــم (‪-15-14-13‬‬\n      ‫‪.5 )16‬مــا جــاء ببرنــت املكاملــات املنــوه عنــه املرفــق علــى اللفــة رقم (‪)98‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا فعــل محــرم ومعاقــب عليــه‬\n      ‫شــرع ًا ومجــرم نظام ـ ًا اســتناد ًا للفقرتــن الرابعــة واخلامســة مــن املــادة‬\n      ‫الثالثــة واملــادة التاســعة مــن نظــام اجلرائــم املعلوماتيــة الصــادر بقــرار‬\n      ‫مجلــس الــوزراء رقــم ( م ‪ )17 /‬وتاريــخ ‪1428/3/8‬ه ـ لــذا أطلــب مايلــي‬\n      ‫‪.1‬إثبــات إدانتهمــا مبــا أســند إليهمــا ‪.2‬احلكــم علــي املدعــى عليــه الثانــي‬\n      ‫بالســجن والغرامــة أو بإحــدى هاتــن العقوبتــن اســتناد ًا للمــادة الثالثــة‬\n      ‫مــن الفقرتــن ( ‪ )5 ،4‬وانطبــاق املــادة التاســعة علــى املتهــم األول من ذات‬\n      ‫النظــام املشــار إليــه ‪.3‬مصــادرة جهــاز اجلــوال املســتخدم يف اجلرميــة جــوال‬\n      ‫مــن نــوع نوكيــا الــذي يحمــل الرقــم التسلســلي رقــم (‪ )........‬اســتناد ًا‬\n      ‫للمــادة (‪ )13‬مــن ذات النظــام املشــار إليــه العائــد للمدعــى عليــه الثانــي‬\n      ‫‪.4‬احلكــم عليهمــا بعقوبــة تعزيريــة رادعــة لهمــا وزاجــرة لغيرهمــا لقاء ما‬\n      ‫أســند إليهما وذلك بقيام املدعى عليه األول بالتســتر على املدعى عليه‬\n      ‫الثانــي يف قضيــة إقامتــه عالقــة محرمــة مــع فتــاة وابتزازه وتهديــده للفتاة‬\n      ‫وقيــام املدعــى عليــه الثانــي بإقامــة عالقــة محرمــة مــع فتــاة ‪.5‬التشــديد‬\n      ‫علــى املدعــى عليــه الثانــي يف العقوبــة ( علم ـ ًا بــأن احلــق اخلــاص مــا زال‬\n      ‫قائم ـ ًا ) هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n      ‫الثانــي ‪ ........‬وســؤاله أجــاب بقولــه مــا ذكــره املدعــي العــام مــن قيامــي‬\n      ‫بإقامــة عالقــة محرمــة مــع فتــاة وتهديدهــا وابتزازهــا بنشــر صورهــا غير‬\n      ‫ا هكــذا أجــاب وبســؤال املدعــي العــام إن كان‬         ‫صحيــح جملــة وتفصيـ ً‬\n\n\n‫‪323‬‬\n\f‫ـدي بينــة ومســتعد بإحضارهــا‬   ‫لديــه بينــة علــى دعــواه أجــاب بقولــه نعــم لـ َّ‬\n‫يف جلســة أخــرى هكــذا أجــاب ويف جلســة أخــرى حضــر املدعــي العــام‬\n‫واملدعــى عليــه وبســؤال املدعــي العــام عــن بينتــه التــي اســتعد بإحضارهــا‬\n‫احضر للشــهادة وأدائها كال من ‪ .....‬ســعودي اجلنســية مبوجب الســجل‬\n‫املدنــي رقــم ‪ .....‬املولــود بعــام ‪1405‬ه ـ يســكن تبــوك ويعمــل بهيئــة األمــر‬\n‫باملعــروف والنهــي عــن املنكــر وال تربطــه باملدعــى عليــه عالقــة قرابــة‬\n‫أو جتــارة حســب مــا أفــاد بــه وبســؤاله عمــا لديــه مــن شــهادة أجــاب‬\n‫بقولــه أشــهد هلل تعالــى بأنــه وردت لدينــا معلومــات حــول ابتــزاز املدعــى‬\n‫عليــه لفتــاة بنشــر صورهــا لتمكينــه مــن نفســها وأنــه يطلــب منهــا مبالــغ‬\n‫ماليــة كمــا أخبرتنــا الفتــاة أن املدعــى عليــه طلــب منهــا مبلــغ ألــف ريــال‬\n‫حتــت الضغــط وأنــه ســيحضر ألخذهــا فتــم االنتقــال للموقــع أمــام منــزل‬\n‫املدعيــة باحلــق اخلــاص ومت القبــض عليــه ووجــد بحوزتــه بطاقــة الصــراف‬\n‫العائــدة للفتــاة كمــا أنــه أقــر أمامــي داخــل الدوريــة األمنيــة أنــه أخــذ‬\n‫مــن الفتــاة املدعيــة مبلــغ عشــرة أالف ريــال ومســتعد بإعادتهــا ألجــل‬\n‫إنهــاء وضعــه هكــذا شــهد كمــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .....‬املولــود بعــام ‪1404‬ه ـ يســكن ‪ .....‬ويعمــل بهيئــة‬\n‫األمــر باملعــروف والنهــي عــن املنكــر وال تربطــه باملدعــى عليــه عالقــة‬\n‫قرابــة أو جتــارة حســب مــا أفــاد بــه وبســؤاله عمــا لديــه مــن شــهادة أجــاب‬\n‫بقولــه أشــهد هلل تعالــى بأنــه وردت لدينــا معلومــات حــول ابتــزاز املدعــى‬\n‫عليــه لفتــاة بنشــر صورهــا لتمكينــه مــن نفســها وأنــه يطلــب منهــا مبالــغ‬\n‫ماليــة كمــا أخبرتنــا الفتــاة أن املدعــى عليــه طلــب منهــا مبلــغ ألــف‬\n‫ريــال حتــت الضغــط وأنــه ســيحضر ألخذهــا فتــم االنتقــال للموقــع أمــام‬\n‫منــزل املدعيــة باحلــق اخلــاص ومت القبــض عليــه ووجــد بحوزتــه بطاقــة‬\n\n\n                                                                                          ‫‪324‬‬\n\f      ‫الصــراف العائــدة للفتــاة كمــا أن محضــر مشــاهدة الرســائل يــدل‬\n      ‫داللــة واضحــة علــى ابتــزاز املدعــى عليــه للفتــاة هكــذا شــهد وبعــرض‬\n      ‫الشــاهدين وشــهادتهما علــى املدعــى عليــه قــال أمــا الشــاهدان فليــس‬\n      ‫ـدي مــا أقــدح بــه فيهمــا أمــا بخصــوص الشــهادة فأنــا لــم أقــر بأخــذي‬‫لـ َّ‬\n      ‫ملبلــغ العشــرة أالف ريــال كمــا أن بطاقــة الصــراف ضبطــت بحوزتــي‬\n      ‫إال أنهــا كانــت ألجــل اســتيفاء مســتحقات ماليــة بينــي وبــن املدعيــة‬\n      ‫باحلــق اخلــاص هكــذا قــال وبســؤال املدعــي العــام إن كان لديــه مزيــد‬\n      ‫ـدي ســوى مــن أحضــرت ومــا يف أوراق املعاملــة‬   ‫بينــة أجــاب بقولــه ليــس لـ َّ‬\n      ‫هكــذا أجــاب فجــرى اإلطــاع علــى التحقيــق احملــرر علــى الصحيفــة‬\n      ‫رقــم (‪ )6-4‬املرفــق باملعاملــة لفــة رقــم (‪ )32‬املتضمــن مــا نصــه (س‪/‬‬\n      ‫كيــف مت القبــض عليــك ؟ ج‪ /‬أفيدكــم أنــه بتاريــخ ‪1433/3/4‬ه ـ‬\n      ‫ـاء قمــت باالتصــال علــى جــوال الفتــاة ‪ .....‬والتــي‬\n                                                            ‫حوالــي الســاعة ‪ 10‬مسـ ً‬\n      ‫تعرفــت عليهــا قبــل ســنتني تقريب ـ ًا عــن طريــق املعاكســة والترقيــم‬\n      ‫وجلســت أتواصــل معهــا ملــدة ثالثــة أشــهر عــن طريــق اجلــوال وكنــت‬\n      ‫أقــوم بإيصالهــا ملشــاوير حيــث أننــي أعمــل علــى توصيــل املشــاوير ثــم‬\n      ‫بعدهــا انقطعــت عالقتــي بهــا) كمــا ان فيــه مــا نصــه (أفيدكــم بأننــي‬\n      ‫أقمــت عالقــة معهــا عــن طريــق الهاتــف وقــد خرجــت معــي برضاهــا)‬\n      ‫ويظهــر مــن التحقيــق إقــرار املدعــى عليــه الثانــي ‪ .....‬بعالقتــه بالفتــاة‬\n      ‫املدعيــة وبعرضــه عليــه قــال حدثــت بينــي وبــن املدعيــة عالقــة بالهاتــف‬\n      ‫أمــا اخلــروج معــي فغيــر صحيــح هكــذا قــال كمــا جــرى اإلطــاع علــى‬\n      ‫محضــر مشــاهدة الرســائل املرفــق باملعاملــة لفــة رقــم (‪ )16-13‬وفيــه مــا‬\n      ‫نصــه (تــرى واهلل أدري أنهــا إنتظــار حتــى لــو قفلتــي اخلــط لكــن تشــويف‬\n      ‫اليــوم ردت فعلــي) (يعنــي الزم أخربهــا معاكــي عشــان حتترميني طيب)‬\n\n\n‫‪325‬‬\n\f‫(شــايفتيني غبــي يصيــر خيــر بــس خلينــي أتشــافى) واملرســلة مــن جــوال‬\n‫املدعــى عليــه ذي الرقــم (‪ ).....‬للمدعيــة وبعــرض ذلــك علــى املدعــى عليــه‬\n‫وســؤاله عنــه وعــن األرقــام التــي تعــود لــه أجــاب بقولــه الرقــم املذكــور‬\n‫يعــود لــي شــخصي ًا وســبب هــذه الرســائل كونــي أطالــب الفتــاة مبالــغ‬\n‫ماليــة وقمــت بإرســال هــذه الرســائل لهــا ألجــل ذلــك هكــذا أجاب كما‬\n‫جــرى تصفــح برنــت املكاملــات الــواردة والصــادرة املرفــق باملعاملــة لفــة‬\n‫رقــم (‪ )98‬والــذي يظهــر منــه جليـ ًا كثــرة االتصــاالت والرســائل الــواردة‬\n‫والصــادرة بــن املدعــى عليــه واملجنــي عليهــا ممــا يقــوي التهمــة بجانــب‬\n‫املدعــى عليــه وأن األمــر ليــس مجــرد عالقــة عمــل كمــا يزعــم فبنــاء‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وملَّــا أنكــر املدعــى عليــه الثانــي‬\n‫‪ .....‬التهمــة املنســوبة إليــه يف دعــوى املدعــي العــام وحيــث إن املدعــى‬\n‫عليــه أقــر بإقامــة لعالقــة محرمــة علــى مــدار ســنتني مــع فتــاة ال متــت‬\n‫لــه بصلــة عــن طريــق الهاتــف وحيــث إن اإلقــرار حجــة علــى صاحبــه‬\n‫مؤاخــذ بــه كمــا أقــر بخروجهــا معــه حتقيقـ ًا والــذي قــرر رجوعــه عنــه‬\n‫وحيــث إن الرجــوع عمــا يوجــب التعزيــر حلــق اهلل تعالــى ال يقبــل مــن‬\n‫(و َل ُي ْق َبــلُ ُر ُجــو ُع ْالُقِ ـ ِّـر َعــنْ ْإقـ َـرا ِر ِه َّإل‬\n                                                                       ‫صاحبــه جــاء يف املغنــي ‪َ 389/10‬‬\n‫اط ِه َف َأ َّمــا‬\n                 ‫ـاط ِ ِل ْسـ َـق ِ‬  ‫ات َو ُي ْح َتـ ُ‬‫الشـ ُـب َه ِ‬                                ‫ان َحـ ًّـدا ِ َّ ِ‬\n                                                                   ‫ل َت َعا َلــى ُيــدْ َر ُأ ِب ُّ‬                  ‫ك َ‬   ‫يمــا َ‬‫فِ َ‬\n‫كا ِة‬   ‫كالـ َّـز َ‬ ‫ات َ‬  ‫الشـ ُـب َه ِ‬                                               ‫ـوق َّ ِ‬\n                                      ‫الل َت َعا َلــى ا َّل ِتــي َل ُتــدْ َر ُأ ِب ُّ‬     ‫ن َو ُح ُقـ ُ‬   ‫ـوق ْال َدمِ ِّيـ َ‬‫ُح ُقـ ُ‬\n‫وع ـ ُه َع ْن َهــا َو َل ن َْع َلـ ُـم ِف َهـ َـذا خِ َل ًفــا) وحيــث‬             ‫ات َفـ َـا ُي ْق َبــلُ ُر ُج ُ‬ ‫ـار ِ‬‫ك َّفـ َ‬‫َوا ْل َ‬\n‫قامــت البينــة علــى ضبــط املدعــى عليــه وبحوزتــه بطاقــة الصــراف اآللــي‬\n‫العائــد للفتــاة املجنــي عليهــا وقــد أقــر املدعــى عليــه بذلــك ممــا يثيــر‬\n‫شــبهة قويــة جتاهــه باالبتــزاز ونظــر ًا لكــون مــا دفــع بــه مــن املطالبــات‬\n‫املاليــة ال يبــرر فعلتــه فاالســتحقاقات املاليــة ال تأخــذ بهــذه الطريقــة‬\n\n\n                                                                                                                                            ‫‪326‬‬\n\f      ‫مــن التخفــي وتبقــى علــى مــدار هــذا الوقــت الطويــل دون علــم ولــي أمــر‬\n      ‫الفتــاة بتلــك االســتحقاقات كمــا أن مــا شــهد بــه الشــاهد األول مــن‬\n      ‫إقــراره أمامــه بأخــذه ملبلــغ عشــرة أالف ريــال مــن الفتــاة واســتعداده‬\n      ‫لردهــا بغيــة إنهــاء املوضــوع يقــوي شــبهة االبتــزاز جتــاه املدعــى عليــه‬\n      ‫وحيــث إن التهديــد باالبتــزاز عمــل محــرم يــدل علــى شــدة جــرم صاحبــه‬\n      ‫وفســاد طبعــه وســوء خلقــه وفيــه إشــاعة للفاحشــة يف املجتمــع وقــد قــال‬\n                        ‫ـيع ا ْل َفاحِ َش ـ ُة ِف الَّذِ يـ َـن َ‬\n      ‫آم ُنــوا َل ُهـ ْـم‬                                            ‫ـون َأن َت ِشـ َ‬   ‫اهلل تعالــى ( ِإ َّن الَّذِ ي َــن ُي ِح ُّبـ َ‬\n      ‫ـون) «النــور ‪»19‬‬                                                     ‫الد ْن َيــا َو ْالخِ ــر ِة َو َّ ُ‬\n                              ‫الل َي ْع َلـ ُـم َو َأن ُتـ ْـم َل َت ْعل َُمـ َ‬                               ‫اب َأ ِليـ ٌـم ِف ُّ‬ ‫َعـ َـذ ٌ‬\n                                                                                       ‫َ‬\n      ‫ـدي إدانــة املدعــى عليــه الثانــي ‪.....‬‬                         ‫لــذا وجلميــع مــا تقــدم فقــد ثبــت لـ َّ‬\n      ‫ـدي إدانتــه‬    ‫بإقامتــه عالقــة محرمــة مــع فتــاة ال متــت لــه بصلــة ولــم يثبــت لـ َّ‬\n      ‫باالبتــزاز والتهديــد بنشــر الصــور وإمنــا توجــه الشــبهة لــه بذلــك وقــررت‬\n      ‫مــا يلــي أو ًال تعزيــر املدعــى عليــه الثانــي ‪ .....‬لقــاء مــا ثبــت بحقــه مــن‬\n      ‫إقامــة عالقــة محرمــة ولشــبهة االبتــزاز بســجنه ملــدة ســنتني يحتســب مــن‬\n      ‫ذلــك مــدة إيقافــه بســبب هــذه القضيــة وجلــده مائتــي جلــدة مفرقــة علــى‬\n      ‫أربــع دفعــات كل دفعــة خمســن جلــدة بــن كل دفعــة وأخــرى عشــرة‬\n      ‫أيــام ثانيـ ًا صرفــت النظــر عــن طلــب املدعــي العــام تطبيــق املادتــن (‪-3‬‬\n      ‫‪ )13‬مــن نظــام مكافحــة اجلرائــم املعلوماتيــة لعــدم ثبــوت موجــب لذلــك‬\n      ‫وبذلــك حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n      ‫قناعتــه بــه أمــا املدعــي العــام فقــد قــرر اعتــراض مكتفيـ ًا مبــا جــاء يف‬\n      ‫أوراق املعاملــة عــن تقــدمي الئحــة اعتراضيــة وســتتم محاكمــة املدعــى‬\n      ‫عليــه األول حــال إحضــاره بــإذن اهلل وللبيــان حــرر يف ‪1433/6/14‬ه ـ‬\n                           ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد وردت املعاملــة مــن محكمــة االســتئناف‬\n\n\n‫‪327‬‬\n\f‫مبنطقــة اجلــوف وذلــك مبوجــب كتــاب رئيــس محكمــة االســتئناف‬\n‫مبنطقــة اجلــوف برقــم وتاريــخ ‪1434/3/9‬ه ـ واملرفــق بــه قــرار املالحظــة‬\n‫الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم وتاريــخ ‪1434/3/8‬ه ـ ونــص‬\n‫احلاجــة منــه (وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ‬\n‫باألكثريــة أو ًال لــم يتطــرق فضيلتــه ملــا طلبــه املدعــي العــام مــن مصــادرة‬\n‫جهــاز اجلــوال املســتخدم يف اجلرميــة ثاني ـ ًا يوجــد خطــأ يف رقــم املادتــن‬\n‫(‪ )4‬و(‪ )5‬حيــث ذكــر فضيلتــه يف حكمــه رقمهــا (‪ )3‬و(‪ )13‬فعلــى‬\n‫فضيلتــه إكمــال الــازم حيــال مــا ذكــر وإضافــة مــا يجــد للضبــط‬\n‫وصورتــه والقــرار وســجله ومــن ثــم إعــادة املعاملــة كاملتبــع واهلل املوفــق)‬\n‫وعليــه أجيــب أصحــاب الفضيلــة مبــا يلــي أو ًال أنــه مت صــرف النظــر عــن‬\n‫طلــب املدعــي العــام تطبيــق املــادة (‪ )13‬مــن نظــام مكافحــة اجلرائــم‬\n‫املعلوماتيــة وهــي املــادة اخلاصــة باملصــادرة ثانيـ ًا أن املادتــن املشــار إليهما‬\n‫يف احلكــم صحيحــة أمــا مــا ذكره أصحــاب الفضيلة فهي فقرات املادة‬\n‫الثالثــة هــذا مــا لــزم اإلجابــة عنــه واهلل أســأل الهدايــة للحــق والصــواب‬\n‫وألصحــاب الفضيلــة قضــاة محكمــة االســتئناف املوقــرة فائــق التقديــر‬\n‫واالحتــرام وللبيــان حــرر يف ‪1434/4/1‬ه ـ وصلــى اهلل علــى نبينــا محمــد‬\n                                                     ‫وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n‫احلمــدهلل وحــده وبعــد ‪ ...‬فقــد أطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الثانيــة لتمييــز القضايــا اجلزائيــة مبحكمــة اإلســتئناف باجلــوف علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بتبــوك املكلــف‬\n‫الشــيخ‪ ...../‬برقــم وتاريخ‪1434/4/7‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة الشــيخ ‪ ..... /‬برقــم وتاريخ‪1433/6/15‬ه ـ اخلــاص بدعــوى‬\n‫املدعــي العــام ضــد‪ ..... /‬و رفيقــه يف اقامــة عالقــة محرمــة وقــد تضمــن‬\n\n\n                                                                                          ‫‪328‬‬\n\f      ‫القــرار حكــم فضيلتــه مبــا هــو مــدون و مفصــل فيــه وبدراســة القــرار‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة تقــرر املصادقــة علــى احلكــم بعــد‬\n      ‫اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                  ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪329‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":315,"source_page_end":329,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bf3f9cd36410608ebf9d2209e3ec1750de19edc46457b58afcad1d244c500170","normalized_text_hash":"c06727c9eb6c7d2fd33f1e1c4edce8e91c32117190a311d6abfd5e01d77a7925","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p315-33299196"},{"id":"f3c94604-7e9d-5f0a-97a3-cc9fe2a1d8e5","document_type":"judgment","category":"judicial","subcategory":"general","title":"خلوة محرمة -إقامة عالقة محرمة مع امرأة -املدعى عليه محصن -ممارسة مقدمات الفاحشة -أسباب تخفيف العقوبة - وقف تنفيذ العقوبة.","document_number":"33356003","case_number":"33464877","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1435/7/26","year":"1434","subject":"خلوة محرمة -إقامة عالقة محرمة مع امرأة -املدعى عليه محصن -ممارسة مقدمات الفاحشة -أسباب تخفيف العقوبة - وقف تنفيذ العقوبة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33356003 :‬تاريخه ‪1435/7/26 :‬هـ‬\n                     ‫رقم الدعوى‪33464877 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 3430186‬تاريخه‪1434/2/5 :‬هـ‬\n\n\n ‫خلــوة محرمــة ‪ -‬إقامــة عالقــة محرمــة مــع امــرأة ‪ -‬املدعــى عليــه‬\n ‫محصــن ‪ -‬ممارســة مقدمــات الفاحشــة ‪ -‬أســباب تخفيــف العقوبــة ‪-‬‬\n                                                 ‫وقــف تنفيــذ العقوبــة‪.‬‬\n\n\n\n ‫‪ -1‬قــول الرســول صلــى اهلل عليــه وســلم (ال يخلــون رجــل بامــرأة إال‬\n                                                 ‫كان الشــيطان ثالثهمــا)‬\n ‫‪ -2‬قــول الرســول صلــى اهلل عليــه وســلم (أقيلــوا ذوي الهيئــات عثراتهــم‬\n                                                              ‫إال يف احلــدود)‬\n ‫‪ -3‬نقــل ملــا ورد يف األحــكام الســلطانية أن تأديــب ذي الهيئــة مــن أهــل‬\n                     ‫الصيانــة أخــف مــن تأديــب أهــل البــذاءة والســفاهة‪.‬‬\n\n\n\n ‫توجيــه االتهــام للمدعــى عليــه باالرتبــاط بعالقــة محرمــة بفتــاة واالختالء‬\n ‫بهــا يف إحــدى الشــقق املفروشــة واســتغالل عملــه بذلــك‪ ،‬حيــث قبــض‬\n ‫عليــه مــن قبــل هيئــة األمــر باملعــروف والنهــي عــن املنكــر إثــر قيامــه‬\n ‫بــإركاب امــرأة (مت التســتر عليهــا) والتوجــه بهــا إلــى إحــدى الشــقق‬\n ‫املفروشــة‪ ،‬أقــر أمــام الفرقــة باالختــاء وممارســة مقدمــات الفاحشــة‪،‬‬\n ‫طلــب املدعــي العــام اتبــاع مــا أســند إليــه للمدعــى عليــه و احلكــم عليــه‬\n\n\n                                                                                      ‫‪330‬‬\n\f      ‫بعقوبــة تعزيريــة‪ ،‬أقــر املدعــى عليــه باالرتبــاط بعالقــة محرمــة مــع امــرأة‬\n      ‫ال حتــل لــه وأنــه جلــس معهــا أكثــر مــن مــرة يف مــكان عــام‪ ،‬أنكــر‬\n      ‫اخللــوة التــي متــت يف الســيارة وقــت الذهــاب للشــقة‪ ،‬كمــا أنكــر فعــل‬\n      ‫مقدمــات الفاحشــة‪ ،‬أظهــر املدعــى عليه التوبــة والندم‪ ،‬اكتفى املدعي‬\n      ‫العــام مبــا يف أوراق املعاملــة‪ ،‬ذكــر القاضــي أســباب تخفيــف احلكــم‪،‬‬\n      ‫حكمــت احملكمــة بإدانــة املدعــى عليــه بحصــول اخللــوة وتوجــه التهمــة‬\n      ‫مبمارســة مقدمــات الفاحشــة وتعزيــر املدعــى عليــه باجللــد مئــة وخمســن‬\n      ‫جلــدة بــن طائفــة مــن املؤمنــن علــى دفعتــن وســجنه شــهرين مــع وقــف‬\n      ‫عقوبــة الســجن املشــروط بعــدم العــودة ملثــل مــا بــدر منــه ‪ ،‬صــدق احلكــم‬\n                                                            ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬املــازم القضائــي لــدى فضيلــة‬\n      ‫الشــيخ ‪.........‬القاضــي يف احملكمــة اجلزائيــة بالريــاض واملكلــف مــن‬\n      ‫قبلــه بنظــر هــذه القضيــة وبنــاء على املعاملة احملالة لنــا من فضيلة رئيس‬\n      ‫احملكمة اجلزائية بالرياض برقم ‪ 33464877‬وتاريخ ‪1433/07/14‬هـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331322442‬وتاريــخ ‪ 1433/07/14‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافق‪1433/07/26‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 15‬‬\n      ‫وفيهــا قــدم املدعــي العــام ‪.........‬دعــواه ضــد ‪ 32،.........‬ســنه ‪ ،‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ،).........‬محصــن ‪ ،‬مقيــم مبدينــة‬\n      ‫الريــاض ‪ ،‬صــدر لــه أمــر اإلفــراج قم‪.........‬وتاريــخ ‪1433 /6 / 18‬ه ـ‬\n                           ‫اســتناد ًا للمــادة ‪ 120‬مــن نظــام اإلجــراءات اجلزائيــة‪.‬‬\n      ‫الوقائــع ‪ :‬انــه بتاريخ‪1433/6/17‬ه ـ قبــض علــى املذكــور مــن قبــل هيئة‬\n\n‫‪331‬‬\n\f‫األمــر باملعــروف والنهــي عــن املنكــر مركــز هيئــة ‪ .........‬و‪ ....‬أثر قيامه‬\n‫بــإركاب امــرأة ( مت التســتر عليهــا) والتوجــه بهــاء إلــى إحــدى الشــقق‬\n‫املفروشــة‪ ،‬وبانتقــال الفرقــة للموقــع مت مشــاهدته وقــد ظهــرت عليــه‬\n‫عالمــات اإلرتبــاك واخلــوف وبــادر بطلــب الســتر عليــه وأفــاد للفرقــة أنــه‬\n‫تعــرف علــى املــرأة عــن طريــق عملــه وأنــه اختلــى بهــا أكثــر مــن مــرة‬\n                                   ‫بســيارته ومــارس معهــا مقدمــات الفاحشــة ‪.‬‬\n‫وأســفرت إجــراءات التحقيــق عــن اتهــام املذكور بربــط العالقة احملرمة‬\n‫بفتــاة واالختــاء احملــرم بهــايف إحدى الشــقق املفروشــة واســتغالل عمله‬\n                                          ‫بذلــك‪ .‬وذلــك لألدلــة والقرائــن اآلتية ‪-:‬‬\n‫‪ -1‬مــا جــاء يف أقوالــه املدونــة علــى الصفحــة رقــم (‪ )4‬مــن دفتــر‬\n                                                         ‫االســتدالل املرفــق لفــه‪.‬‬\n                                         ‫‪ -2‬ما جاء مبحضر القبض املرفق لفه‪.‬‬\n‫وبالبحــث بســجله اجلنائــي لــم يعثــر لــه علــى ســوابق مســجلة حتــى‬\n‫تاريخــه‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه‬\n‫شــرع ًا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــه لقــاء‬\n‫مــا أســند إليــه‪ .‬هــذه دعــواي‪ ،‬وبســؤال املدعــى عليــه أجــاب بقولــه مــا‬\n‫ذكــره املدعــي العــام يف اجلملــة صحيــح فقــد قبــض علــي وكنــت قــد‬\n‫ربطــت عالقــة محرمــة مــع امــرأة ال حتــل لــي كمــا إننــي جلســت مــع‬\n‫هــذه املــرأة أكثــر مــن مــرة يف مــكان عــام ولــم اختـ ِـل بهــا إال يف ســيارتي‬\n‫وقمــت بالذهــاب إلــى الشــقة يف الوقــت الــذي مت القبــض علينــا مــن قبــل‬\n‫الهيئــة وأنــا رجــل عســكري وليــس علــي ســوابق جنائيــة وأنــا تائــب إلــى‬\n‫اهلل تعالــى وأتعهــد بعــدم العــودة ملثــل مــا بــدر منــي كما إن املــرأة كبيرة‬\n‫الســن وعمرهــا يقــارب اخلمســن ســنة وأنــا رجل متزوج ولــي عيال بحاجة‬\n\n\n                                                                                         ‫‪332‬‬\n\f      ‫إلــي كمــا إننــي لــم أمــارس مقدمــات الفاحشــة معهــا هكــذا أجــاب‬\n      ‫وجــرى االطــاع علــى محضــر الهيئــة املــدون علــى اللفــة (‪ )5‬مــن املعاملــة‬\n      ‫وقــد تضمــن ( فإنــه يف هــذا اليــوم وردتنــا معلومــات عــن املذكــور أعــاه‬\n      ‫بأنــه قــام بإدخــال امــرأة إلــى الشــقق املفروشــة ‪ .........‬وعنــد االنتقــال إلــى‬\n      ‫املوقــع اســتدعي الطــرف األول لتحقيــق مــن حالتــه وعنــد رؤيتــه للفرقــة‬\n      ‫ظهــرت عليــه عالمــات اخلــوف واالرتبــاك وبــادر الفرقــة بطلــب الســتر‬\n      ‫عليــه وأفــاد بأنــه تعــرف علــى املــرأة عــن طريــق عملــه بســكة احلديــد‬\n      ‫منــذ مــا يقــارب أربعــة أشــهر وأنــه اختلــى بهــا أكثــر مــن مــرة بســيارته‬\n      ‫ويف هــذا اليــوم اختلــى بهــا يف الشــقق املفروشــة ومــارس معهــا مقدمــات‬\n      ‫الفاحشــة جــرى تدويــن هــذا احملضــر حفظ ـ ًا للواقــع وإبــراء للذمــة )‬\n      ‫وبعرضــه علــى املدعــى عليــه قــرر بقولــه ‪ :‬الصحيــح أننــي اجتمعــت معهــا‬\n      ‫يف أمكنــة عامــة كاألســواق واملجمعــات التجاريــة كمــا إننــي اختليــت‬\n      ‫بهــا مــرة واحــدة ســاعة القبــض علــي مــن قبــل الهيئــة يف ســيارتي وقــد‬\n      ‫تعرفــت عليهــا عــن طريــق عملــي حيــث أعمــل عســكري يف ســكة‬\n      ‫احلديــد كمــا إنــه لــم يحصــل بيننــا مقدمــات الفاحشــة غيــر اخللــوة علــى‬\n      ‫مــا ذكــرت يف جوابــي هكــذا قــرر فبنــاء علــى مــا ســلف مــن الدعــوى‬\n      ‫واإلجابــة ونظــر ًا لكــون املدعــى عليــه صــادق علــى دعــوى املدعــي العــام‬\n      ‫وأقــر بحصــول اخللــوة وقــد قــال النبــي صلــى اهلل عليــه وســلم ( ال يخلــون‬\n      ‫رجل بامرأة إال كان الشــيطان ثالثهما ) إذ اخللوة مظنة وقوع الفاحشــة‬\n      ‫كمــا أن املدعــى عليــه أنكــر حصــول مقدمــات الفاحشــة مــن غيــر‬\n      ‫اخللــوة علــى مــا ذكــر يف محضــر الهيئــة بعاليــه وحيــث بنــي احملضر على‬\n      ‫إفــادة املدعــى عليــه واملــرء مؤاخــذ بإقــراره شــرع ًا وألن مــا أقــدم عليــه‬\n      ‫املدعــى عليــه يعــد أمــر ًا محرمـ ًا يســتحق العقوبــة عليهــا ومبــا أن العقوبــة‬\n\n\n‫‪333‬‬\n\f‫شــرعت لتكــون زاجــرة للنــاس عــن فعــل احملــرم وكفــارة عمــن وقــع‬\n‫فيهــا كمــا أن وقــف تنفيــذ العقوبــة وجعلهــا ســيف ًا مســلط ًا علــى املدعــى‬\n‫عليــه لــه األثــر البليــغ يف الــردع مــن اإليقــاع نفســه كمــا إن إيقــاف تنفيــذ‬\n‫عقوبــة الســجن فيهــا جتنيــب للمحكــوم مــن اآلثــار الســيئة علــى املدعــى‬\n‫عليــه نتيجــة االختــاط داخــل الســجن مــع معتــادي اإلجــرام إضافــة‬\n‫إلــى مــا ســبق ظهــر لــي صــدق توبــة املدعــى عليــه ولظروفــه الشــخصية‬\n‫املذكــورة بعاليــه وبعــد االطــاع علــى املعاملــة ثبــت لــدي إدانــة املدعــى‬\n‫عليــه بحصــول اخللــوة إلقــراره لــدي بذلــك كمــا توجهــت لــدي التهمــة‬\n‫مبمارســة املدعــى عليــه ملقدمــات الفاحشــة معهــا ومــن ثــم قــررت مــا يلــي‬\n‫‪ :‬أو ًال ‪ :‬جلــد املدعــى عليــه مائــة وخمســن جلــدة تعزيــر ًا بــن طائفــة مــن‬\n‫املؤمنــن تنفــذ علــى دفعتــن بالتســاوي بــن كل دفعــة وأخــرى عشــرة‬\n‫أيــام ‪ .‬ثاني ـ ًا ‪ :‬ســجن املدعــى عليــه شــهرين مــع وقــف التنفيــذ املشــروط‬\n‫بعــدم العــودة ملثــل مــا بــدر منــه فــإن عــاد يف تنفيــذ احلكــم بالســجن علــى‬\n‫مــا ذكــر ووقــف تنفيــذ العقوبــة خــاص بالســجن أمــا اجللــد فينفــذ كمــا‬\n‫أن وقــف تنفيــذ العقوبــة ال يؤثــر علــى اجلرميــة الالحقــة وبعــرض احلكــم‬\n‫علــى احملكــوم عليــه قــرر القناعــة باحلكــم أمــا املدعــي العــام فطلــب‬\n‫اســتئنافه مكتفيـ ًا بالئحــة الدعــوى ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/07/26‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1433/11/24‬ه ـ‬\n‫افتتحــت اجللســة بعــد أن وردنــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة‬\n‫اجلزائيــة الرابعــة مبحكمــة االســتئناف بالريــاض برقــم (‪)33434661‬‬\n‫وتاريــخ ‪1433/10/22‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪......... /‬‬\n‫املتضمــن مــا نصــه (وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n\n\n                                                                                         ‫‪334‬‬\n\f      ‫لوحــظ باألكثريــة أن اجلــزاء التعزيــري قليــل الســيما أن املدعــى عليــه‬\n      ‫رجــل أمــن ومتــزوج واختلــى بهــا عــدة مــرات) وبعــد اإلطــاع علــى مــا‬\n      ‫ذكــره أصحــاب الفضيلــة يف قرارهــم فأقــول جوابــا علــى ذلــك بــأن‬\n      ‫التعزيــر عقوبــة مفــوض تقديرهــا إلــى القاضــي وعليــه مراعــاة ظــروف‬\n      ‫اجلانــي ومالبســات احلادثــة وقــد رأيــت أن املدعــى عليــه مــن ذوي الهيئــة‬\n      ‫احلســنة والصيانــة فخففــت عنــه التعزيــر لذلــك وقــد قــال النبــي صلــى‬\n      ‫اهلل عليــه وســلم (أقيلــوا ذوي الهيئــات عثراتهــم إال يف احلــدود) واحلديــث‬\n      ‫صحيــح وقــد نقــل املــاوردي يف األحــكام الســلطانية ‪ :‬أن تأديــب ذي‬\n      ‫الهيئــة مــن أهــل الصيانــة أخــف مــن تأديــب أهــل البــذاءة والســفاهة كما‬\n      ‫أنــه قــد ظهــر لــي صــدق توبتــه وعزمــه علــى عــدم العــودة فعليــه فإنــي‬\n      ‫الزلــت علــى مــا حكمــت بــه وأرى مناســبة العقوبــة التعزيريــة املقــدرة‬\n      ‫وأســأل اهلل الســداد للجميــع ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n               ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫الرابعــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزئيــة بالريــاض برقــم ‪ 332009460‬وتاريــخ‬\n      ‫‪1433/11/29‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة املــازم‬\n      ‫القضائــي باحملكمــة الشــيخ ‪ ......... /‬املســجل برقــم‪ 33356003‬وتاريــخ‬\n      ‫‪1433/7/26‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪ ......... /‬التهامــه‬\n      ‫بربــط عالقــة محرمــة مــع امــرأة واالختــاء بهــا علــى النحــو املوضــح‬\n      ‫بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون بــه وحيــث ســبق دراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه‬\n      ‫ـاء علــى قرارنــا‬‫فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنـ ً‬\n\n‫‪335‬‬\n\f‫رقــم ‪ 33434661‬وتاريــخ ‪1433/10/22‬ه قــررت الدائــرة باألكثريــة‬\n‫املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪.‬واهلل املوفــق وصلــى اهلل‬\n                                ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                               ‫‪336‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":330,"source_page_end":336,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b634910581d0cc72cfa7d060fcda30b29869e8d3c318ff1584f36821b836ce7c","normalized_text_hash":"6b3e1b752835dde1bb0e65fd98449274d3596740f5ef28c2e76284e77d1edd2b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p330-33356003"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"bbf6ebd0-3591-5705-811f-045b6b5b0509","document_type":"judgment","category":"judicial","subcategory":"general","title":"زنا -خلوة محرمة -اعتداء بالضرب -إحداث إصابات -ممارسة دعارة -إقرار املدعى عليهم -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","document_number":"34349928","case_number":"34213064","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/4","year":"1434","subject":"زنا -خلوة محرمة -اعتداء بالضرب -إحداث إصابات -ممارسة دعارة -إقرار املدعى عليهم -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34349928 :‬تاريخه ‪1434/11/4 :‬هـ‬\n                   ‫رقم الدعوى‪34213064 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34389266‬تاريخه‪1434/12/26 :‬هـ‬\n\n\n‫زنــا ‪ -‬خلــوة محرمــة ‪ -‬اعتــداء بالضــرب ‪ -‬إحــداث إصابــات ‪ -‬ممارســة‬\n‫دعــارة ‪ -‬إقــرار املدعــى عليهــم ‪ -‬تعزيــر بالســجن واجللــد والتوصيــة‬\n                                                 ‫باإلبعــاد عــن البــاد‪.‬‬\n\n\n\n‫‪ -‬قولــه صلــى اهلل عليــه وســلم ( مــا خــا رجــل بامرأة إال كان الشــيطان‬\n                                                                ‫ثالثهما ) ‪.‬‬\n                       ‫‪ -‬املادة ( ‪ )162‬من نظام اإلجراءات اجلزائية ‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليهــم األولــى والثانية والثالثــة والرابع‬\n‫باالختــاط احملــرم ‪ ،‬واتهــام املدعــى عليهــا الثانيــة مبمارســة الدعــارة‪،‬‬\n‫واتهــام املدعــى عليــه الرابــع بإيوائهــن واالعتــداء عليهــن بالضــرب‬\n‫وإحــداث إصابــات بهــن‪ ،‬وطلــب املدعــي العــام إثبــات إدانتهــم مبــا أســند‬\n‫إليهــم وتعزيرهــم لذلــك‪ ،‬أقــر املدعــى عليهــم مبــا جــاء بدعــوى املدعــي‬\n‫العــام‪ ،‬حكمــت احملكمــة بتعزيــر املدعــى عليهــم بالســجن واجللــد‬\n‫والتوصيــة باإلبعــاد عــن البــاد بعــد انتهــاء محكوميتهــم‪ ،‬قنــع املدعــى‬\n‫عليهــم باحلكــم‪ ،‬و قــرر املدعــي عليهــم االعتــراض بــدون الئحــة‪ ،‬صــدق‬\n                                           ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n                                                                                      ‫‪290‬‬\n\f      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة الرئيــس‬\n      ‫برقــم وتاريــخ ‪1434/05/07‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ‬\n      ‫‪1434/05/07‬ه ـ يف يــوم االثنــن املوافــق‪ 1434/11/03‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة احلاديــة عشــرة وخمــس دقيقــة وفيهــا حضــر املدعــي‬\n      ‫ال مــن ‪ ... -1‬اندونيســية اجلنســية‬ ‫العــام ‪ ...‬وادعــى علــى احلاضــر معــه ك ً‬\n      ‫بطاقــة بديلــة رقــم (‪ ...-2 )../..‬اندونيســية اجلنســية بطاقــة بديلــة رقــم‬\n      ‫(‪ ...-3 )../..‬اندونيســية اجلنســية بطاقــة بديلــة رقــم (‪ ...-4 )../..‬بنغالــي‬\n      ‫ا يف دعــواه عليهــم قــد انتهــى التحقيــق إلــى‬  ‫اجلنســية إقامــة رقــم ‪ ...‬قائ ـ ً‬\n      ‫توجيــه االتهــام للمدعــى عليهــم باالختــاط احملــرم شــرع ًا واتهــام املدعى‬\n      ‫عليهــا ‪ ...‬مبمارســة الدعــارة واتهــام املدعــى عليــه ‪ ...‬بإيوائهــن واالعتــداء‬\n      ‫عليهــن بالضــرب وأحــداث اصابــات بهــن املوصوفــة بالتقاريــر املرفقــة‬\n      ‫لــذا أطلــب إثبــات مــا أســند إليهــم واحلكــم عليهــم بعقوبــة تعزيريــة‬\n      ‫(علمـ ًا بــأن احلــق اخلــاص الزال قائمـاً) وبعــرض ذلــك علــى املدعــى عليهــم‬\n      ‫بواســطة املترجمــن ‪ ...‬و‪ ..‬أجابــت كل واحــدة مــن املدعــى عليهــن‬\n      ‫األولــى والثانيــة والثالثــة قائلــة مــا ذكــره املدعــي العــام يف دعــواه كلــه‬\n      ‫صحيــح هكــذا أجابــت كل واحــدة منهــن وأجــاب املدعــى عليــه الرابــع‬\n      ‫مــا ذكــره املدعــي العــام يف دعــواه كلــه صحيــح هكــذا أجــاب ثــم‬\n      ‫جــرى منــي االطــاع علــى أوراق املعاملــة ومحاضــر القبــض والتقاريــر‬\n      ‫الطبيــة فوجدتهــا كمــا ذكــر املدعــي العــام واســتناد ًا للمــادة رقــم‬\n      ‫(‪ )162‬مــن نظــام اإلجــراءات اجلزائيــة اكتفيــت باعتــراف املدعــى‬\n\n‫‪291‬‬\n\f‫عليهــم وإقرارهــم مبجلــس احلكــم فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واجلــواب وإقــرار املدعــى عليهــم مبــا نســب إليهــم وملــا يف فعلهــم مــن اجلرأة‬\n‫يف الباطــل والتعــرض لألعــراض واالختــاء احملــرم شــرع ًا ولقولــه عليــه‬\n‫الصــاة والســام ‪(:‬مــا خــا رجــل بامــرأة إال كان الشــيطان ثالثهمــا)‬\n‫ولــكل مــا تقــدم فقــد ثبــت لــدي إدانــة املدعــى عليهــم مبــا نســب إليهــم‬\n‫يف دعــوى املدعــي العــام مــن دعــوى املدعــي العــام وحكمــت علــى كل‬\n‫واحــد منهــم بســجنه مــدة ســبعة أشــهر وجلــده مائتــي جلــدة مفرقــة عليــه‬\n‫أربــع مــرات كل مــرة خمســون جلــدة بــن كل مــرة والتــي تليهــا ســبعة‬\n‫أيــام وأوصــي بإبعادهــم جميع ـ ًا لبالدهــم بعــد انتهــاء محكومياتهــم‬\n‫وعــدم الســماح لهــم بدخــول هــذه البــاد إال مبــا تقضــي بــه تعليمــات‬\n‫احلــج والعمــرة وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليهــم قــرر‬\n‫املدعــي العــام اإلعتــراض بــدون الئحــة وقــرروا املدعــى عليهــم جميع ـ ًا‬\n‫القناعــة بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم جــرى النطــق باحلكــم الســاعة احلاديــة وثالثــن دقيقــة‬\n                                                       ‫بتاريــخ ‪1434/11/03‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد جــرى‬\n‫منــا نحــن قضــاة الدائــرة اجلزائيــة الســابعة مبحكمــة االســتئناف يف‬\n‫منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الواردة مــن فضيلة رئيس‬\n‫احملكمــة اجلزائيــة مبكــة املكرمــة رقــم وتاريــخ ‪1434/12/1‬ه ـ‬\n‫املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪ ...‬القاضــي باحملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة رقــم وتاريــخ ‪1434/11/4‬ه ـ احملكــوم فيــه‬\n‫مبــا دون بباطــن القــرار املتضمــن دعــوى املدعــى العــام ضــد‪ ...‬بنغالــي‬\n‫اجلنســية ورفيقاتــه املتهــم يف االختــاط احملــرم شــرع ًا وبدراســة القــرار‬\n\n\n                                                                                        ‫‪292‬‬\n\f      ‫وصــورة ضبطــه تقــررت املوافقــة علــى احلكم باألكثريــة ‪ ،‬واهلل املوفق‪.‬‬\n                      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪293‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":290,"source_page_end":293,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"18edc82e89d64675c20e1fb1eda7e998958f61c9fa34792a772c44862816662a","normalized_text_hash":"0b5c11f5f233faad7a277d0a6d6e26ac66c18054aebcd46a1436fa5d5c8c82cf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p290-34349928"},{"id":"42c008b3-8691-54bc-b8e9-3f21649d9241","document_type":"judgment","category":"judicial","subcategory":"general","title":"ممارسة الدعارة -حيازة مقاطع جنسية وإرسالها -إقرار -تعزير بالسجن واجللد -مصادرة -توصية باإلبعاد .","document_number":"34334680","case_number":"34410155","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"ممارسة الدعارة -حيازة مقاطع جنسية وإرسالها -إقرار -تعزير بالسجن واجللد -مصادرة -توصية باإلبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34334680 :‬تاريخه‪1434/1/20:‬هـ‬\n                  ‫رقم الدعوى‪34410155 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34380498‬تاريخه‪1434/12/18 :‬هـ‬\n\n\n‫ممارســة الدعــارة ‪ -‬حيــازة مقاطــع جنســية وإرســالها ‪ -‬إقــرار ‪ -‬تعزيــر‬\n                     ‫بالســجن واجللــد ‪ -‬مصــادرة ‪ -‬توصيــة باإلبعــاد ‪.‬‬\n\n\n\n‫‪ -‬قولــه تعالــى « إن الذيــن يحبــون أن تشــيع الفاحشــة يف الذيــن آمنــوا‬\n                                  ‫لهــم عــذاب أليــم يف الدنيــا و اآلخــرة )‪.‬‬\n       ‫‪-‬أن الشريعة جاءت بحفظ الضروريات اخلمس ومنها العرض ‪.‬‬\n\n\n\n‫أقــام املدعــى العــام دعــواه ضــد املدعــى عليهمــا مبمارســة أعمــال‬\n‫الدعــارة والفســاد‪ ،‬وحيــازة األولــى مقاطــع جنســية علــى هاتفهــا اخللــوي‬\n‫وطلــب احلكــم عليهمــا بعقوبــة تعزيريــة وعلــى األولــى باملــادة السادســة‬\n‫مــن نظــام مكافحــة اجلرائــم املعلوماتيــة حيــث قبــض عليهمــا يف أحــد‬\n‫األســواق وهمــا يف غايــة الســفور والتبــرج وعثــر يف هاتفهمــا علــى رســائل‬\n‫تــدل علــى ممارســتهما العالقــات احملرمــة ومبواجهتهمــا بذلــك اعترفتــا‬\n‫وعليــه قــررت احملكمــة ســجن كل واحــدة منهمــا مــدة ســنة وجلــد‬\n‫كل واحــدة تســعة وثالثــن جلــدة مكــررة ‪ 3‬مــرات ومصــادرة اجلــواالت‬\n‫املضبوطــة والتوصيــة باإلبعــاد عــن البــاد بعــد تنفيــذ احلكــم وجــرى‬\n‫االعتــراض مــن املدعــى العــام وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n                                                                                  ‫‪294‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ‪ .‬فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبحافظــة جــدة برقــم ‪ 34410155‬وتاريــخ‬\n      ‫‪1434/09/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 342086437‬وتاريــخ‬\n      ‫‪1434/08/29‬ه ـ ففــي يــوم االثنــن املوافــق ‪1434/10/19‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر املدعــي العــام ‪ ... -:‬ســعودي‬\n      ‫ال من‪-:‬‬  ‫اجلنســية بالســجل املدنــي رقــم ‪ ....‬وقــدم الئحتــه مدعيـ ًا علــى ك ً‬\n      ‫‪ )20( ،....-1‬عامـاً‪ ،‬اندونيســية اجلنســية مبوجــب البطاقــة البديلــة رقــم‬\n      ‫(‪ )...‬الصــادرة مــن مركــز شــرطة الشــمالية ‪ ،‬غيــر محصنــة‪ ،‬ال تعمــل‪،‬‬\n      ‫موقوفــة بالســجن العــام بأمــر التمديد رقــم (‪ )56280‬يف ‪1434/8/17‬هـ‬\n                            ‫اســتناد ًا للمــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة ‪.‬‬\n      ‫‪ )21( ،....-2‬عام ـاً‪ ،‬اندونيســية اجلنســية مبوجــب البطاقــة البديلــة‬\n      ‫رقــم (‪ )...‬الصــادرة مــن مركــز شــرطة الشــمالية ‪ ،‬غيــر محصنــة‪،‬‬\n      ‫ال تعمــل‪ ،‬موقوفــة بالســجن العــام بأمــر التمديــد رقــم (‪ )56278‬يف‬\n      ‫‪1434/8/17‬ه ـ اســتناد ًا للمــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة ‪.‬‬\n      ‫فإنــه بتاريــخ ‪1434/8/12‬ه ـ قبــض علــى املدعــى عليهمــا مــن قبــل هيئــة‬\n      ‫األمــر باملعــروف والنهــي عــن املنكــر بعــد أن شــاهدوهما تتجــوالن يف‬\n      ‫ســوق (‪ )...‬وهمــا يف غايــة التبــرج والســفور وترتديــان مالبــس قصيــرة‬\n      ‫وباســتيقافهما حاولتــا إخفــاء هواتفهمــا اخللويــة‪ ،‬وبتفتيــش هاتــف‬\n      ‫األولــى ُضبطــت بــه محادثــات ورســائل مــع رجــال تــدل علــى ممارســتها‬\n      ‫للدعــارة كمــا شــوهد رســالة تــدل علــى مســاومتها لشــخص يطلــب منهــا‬\n\n‫‪295‬‬\n\f‫أن تســهر معــه فــردت عليــه وطلبــت مقابــل ذلــك ألــف ريــال‪ .‬وبتفتيــش‬\n‫هاتــف املدعــى عليهــا الثانيــة شــوهد بــه عــدة رســائل بأســماء رجــال‬\n‫يرغبــون إقامــة عالقــات محرمــة معهــا ويطلبــون منهــا أن تعرفهــم علــى‬\n‫نســاء أخريــات فأرســلت لهــم أســماء عــدد مــن النســاء ومــن تلك الرســائل‬\n‫رســالة مــن شــخص طلــب منهــا أن تســهر معــه فطلبــت منــه رصيــد شــحن‬\n                                              ‫اتصــال وقــال لهــا (بكــرة أجــي)‪.‬‬\n‫وبإســتجواب املدعــى عليهــا األولــى اعترفــت بتجولهــا يف ســوق (‪)....‬‬\n‫وهــي تضــع املســاحيق التجميليــة بوجههــا وكانــت تريــد الذهــاب إلــى‬\n‫إحــدى صديقاتهــا كمــا اعترفــت بأنهــا تقيــم عالقــات محرمــة مــع‬\n‫رجــال لغــرض التعــارف وأنهــا واعدتهــم كــي تقابلهــم‪ ،‬وأضافــت أنهــا‬\n                                        ‫حتــوز بهاتفهــا اخللــوي مقاطــع جنســية‪.‬‬\n‫باســتجواب املدعــى عليهــا الثانيــة اعترفــت أنهــا كانــت تتجــول بســوق‬\n‫(‪ ).. ..‬وكانــت ترغــب بالذهــاب إلــى إحــدى صديقاتهــا وكانــت ترتــدي‬\n‫مالبــس قصيــرة (برمــودا) كمــا اعترفــت بأنهــا تقيــم عالقــات محرمــة‬\n‫مــع رجــال ‪ .‬وقــد أســفر التحقيــق عــن توجيــه االتهــام إلــى املدعــى عليهمــا‬\n‫ممارســة أعمــال الدعــارة والفســاد‪ ،‬وحيــازة األولــى مقاطــع جنســية‬\n‫بهاتفهــا اخللــوي وإرســال صورتهــا لشــخص وهــي عاريــة وذلــك لألدلــة‬\n                                                             ‫والقرائــن التاليــة‪-:‬‬\n                         ‫املنوه عنه املدون ص (‪ )5-1‬لفة (‪)11‬‬   ‫‪-1‬اعترافهما ّ‬\n                                 ‫املنوه عنه لفة (‪)6‬‬\n                                                 ‫‪-2‬ما جاء مبحضر القبض ّ‬\n              ‫املنوه عنه املرفق لفة (‪)13.12‬‬    ‫‪-3‬ما جاء مبحضر املشاهدة ّ‬\n‫وباإلطــاع علــى صحيفــة ســوابقهما لــم تــرد حتــى تاريخــه ‪ .‬حيــث إن مــا‬\n‫أقدمــت عليــه املذكورتــان وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا فعــل‬\n\n\n                                                                                      ‫‪296‬‬\n\f      ‫محــرم ومعاقــب عليــه شــرع ًا ومــا قامــت بــه األولــى هــو مجــرم نظام ـ ًا‬\n      ‫طبق ـ ًا لنظــام مكافحــة جرائــم املعلوماتيــة لــذا أطلــب إثبــات مــا أســند‬\n      ‫إليهمــا واحلكــم عليهمــا بعقوبــة تعزيريــة رادعــة واحلكــم علــى األولــى‬\n      ‫مبــا ورد يف الفقــرة األولــى مــن املــادة السادســة مــن نظــام مكافحــة‬\n      ‫اجلرائــم املعلوماتيــة واحلكــم مبصــادرة الهاتفــن اخللويــن املضبوطــن‬\n      ‫(نــوع جالكســي) املــدون بهــا األرقــام التسلســلية التاليــة (‪)............‬‬\n                                      ‫و(‪ )............‬هــذه دعــواي وأســألهما اجلــواب ‪.‬‬\n      ‫وبســؤال املدعــى عليهمــا عــن الدعــوى أجابتــا قائلتــن وهمــا يتكلمــان‬\n      ‫اللغــة العربيــة مــا ذكــره املدعــي العــام صحيــح ونحــن تائبتــن ونادمتــن‬\n      ‫وعازميــن علــى عــدم العــودة ملثــل مــا بــدر منــا هكــذا أجابتــا ‪ .‬وباالطالع‬\n      ‫علــى أوراق املعاملــة واملتضمنــة اعتــراف املدعــى عليهمــا وكذلــك مــا‬\n      ‫جــاء يف محضــر القبــض ومحضــر املشــاهدة حيــث إن مــا أقدمتــا عليــه‬\n      ‫فعــل محــرم شــرع ًا وفيــه نشــر للفســاد والرذيلــة مــع املجاهــرة وألن‬\n      ‫الشــريعة جــاءت بحفــظ الضروريــات اخلمــس ومنهــا العــرض ‪ .‬لقولــه‬\n      ‫تعالــى « إن الذيــن يحبــون أن تشــيع الفاحشــة يف الذيــن آمنــوا لهــم عــذاب‬\n      ‫أليــم يف الدنيــا و اآلخــرة»‪ .‬وألن املدعــى عليهمــا أجنبيتــان وال مصلحــة يف‬\n      ‫إطالــة ســجنهما‪ .‬ولــكل مــا تقــدم قــررت تعزيــر كل واحــدة منهمــا مبــا‬\n      ‫يلــي‪ -:‬أو ًال ‪ :‬ســجن كل واحــدة منهمــا ملــدة ســنة كاملــة حتتســب منهــا‬\n      ‫مــدة إيقافهمــا يف هــذه القضيــة‪ .‬ثاني ـاً‪ :‬جلــد كل واحــدة منهمــا تســعة‬\n      ‫وثالثــن (‪ )39‬جلــدة مكــررة ثالثــة مــرات وبــن كل دفعــة واألخــرى‬\n      ‫عشــرة أيــام‪ .‬ثالثـاً‪ :‬مصــادرة اجلــواالت املضبوطــة يف هــذه القضيــة‪ .‬رابعـاً‪:‬‬\n      ‫أوصيــت بإبعادهمــا عــن البــاد بعــد انتهــاء محكوميتهمــا مــع منعهمــا‬\n      ‫ال إال وفــق تعليمــات احلــج والعمــرة ‪ .‬وبذلــك كلــه‬    ‫مــن دخولهــا مســتقب ً‬\n\n\n‫‪297‬‬\n\f‫حكمــت وبعرضــه عليهمــا قررتــا قناعتهمــا باحلكــم وأبــدى املدعــي‬\n‫العــام اعتراضــه وطلــب متييــزه بالئحــة فأفهــم بنــص النظــام ‪ .‬وصلــى اهلل‬\n‫علــى ســيدنا محمــد وعلــى آلــه وصحبه وســلم حــرر يف ‪1434/10/19‬هـ‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ ...‬نحــن رئيــس‬\n‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة اإلســتئناف مبنطقــة‬\n‫مكــة املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪34334680‬‬\n‫وتاريــخ ‪1434/10/20‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ..../‬القاضــي‬\n‫باحملكمــة اجلزائيــة مبحافظــة جــدة‪ ،‬املتضمــن دعــوى املدعــي العــام‬\n‫ضــد‪ ..../‬اندونيســية اجلنســية ورفيقتهــا ‪ ،‬املتهمتــان مبمارســة أعمــال‬\n‫الدعــارة‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة القــرار وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل‬\n‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،،،،،‬‬\n\n\n\n\n                                                                                  ‫‪298‬‬\n\f299\n\f300\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":294,"source_page_end":300,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ae5eabee964bd7f443e8681e827ebae36204fbe5fda17ee362bb71e228d7b92b","normalized_text_hash":"62ced452a832fd75a46e428c7a5be56da278ef9258875683094efca5ae5b73dc","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p294-34334680"},{"id":"3605225b-b6e0-5a02-851a-d69c0b972245","document_type":"judgment","category":"judicial","subcategory":"general","title":"خلوة محرمة -إقامة عالقة محرمة -انتهاك حرمة منزل -ثبوت اإلدانة باإلقرار -املدعى عليه محصن -التعزير بالسجن واجللد وأخذ التعهد واإلبعاد عن الباد.","document_number":"3420794","case_number":"345694","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/24","year":"1434","subject":"خلوة محرمة -إقامة عالقة محرمة -انتهاك حرمة منزل -ثبوت اإلدانة باإلقرار -املدعى عليه محصن -التعزير بالسجن واجللد وأخذ التعهد واإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3420794:‬تاريخه ‪1434/01/24 :‬هـ‬\n                           ‫رقم الدعوى‪345694 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34182428‬تاريخه‪1434/4/8 :‬هـ‬\n\n\n      ‫خلــوة محرمــة ‪ -‬إقامــة عالقــة محرمــة ‪ -‬انتهــاك حرمــة منــزل ‪ -‬ثبــوت‬\n      ‫اإلدانــة باإلقــرار ‪ -‬املدعــى عليــه محصــن ‪ -‬التعزيــر بالســجن واجللــد‬\n                                            ‫وأخــذ التعهــد واإلبعــاد عــن البــاد‪.‬‬\n\n\n\n                       ‫‪ -1‬قوله تعالى‪( :‬وال تفسدوا يف األرض بعد إصالحها)‪.‬‬\n                         ‫‪ -2‬قوله تعالى‪( :‬وال تعتدوا إن اهلل ال يحب املعتدين)‪.‬‬\n      ‫‪ -3‬قولــه صلــى اهلل عليــه وســلم‪( :‬كل املســلم علــى املســلم حــرام دمــه‬\n                                                                  ‫ومالــه وعرضــه)‪.‬‬\n      ‫‪ -4‬قولــه صلــى اهلل عليــه وســلم‪( :‬مــا خــا رجــل بامــرأة إال كان‬\n                                                           ‫الشــيطان ثالثهمــا)‪.‬‬\n\n\n\n\n      ‫توجيــه االتهــام للمدعــى عليــه مقيم غير مســلم محصــن بإقامة عالقة مع‬\n      ‫امــرأة عاملــة منزليــة ال متــت لــه بصلــة ودخــول منــزل كفيلهــا واالختــاء‬\n      ‫بهــا ‪ ،‬حيــث تقــدم أحــد املواطنــن ببــاغ لــدى الشــرطة يتضمــن قيــام‬\n      ‫املدعــى عليــه بدخــول منزلــه واالختــاء باخلادمــة يف فنــاء املنــزل ومكــث‬\n      ‫مــدة مــن الزمــن ثــم خــرج وهــو يرتــدي عبــاءة نســائية وقــد شــاهد دخولــه‬\n      ‫وخروجــه شــاهدان همــا مــن قامــا باإلبــاغ عنــه ومت القبــض عليــه بعــد‬\n\n‫‪301‬‬\n\f‫خروجــه مــن املنــزل‪ ،‬طلــب املدعــي العــام إثبــات مــا أســند للمدعــى عليــه‬\n‫واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره‪ ،‬أقــر املدعــى عليــه‬\n‫مبــا نســب إليــه وذكــر أنــه قــد أســلم يف الســجن‪ ،‬حكمــت احملكمــة‬\n‫بثبــوت مــا أســند للمدعــى عليــه وتعزيــره لقــاء ذلــك بســجنه ثالثــة أشــهر‬\n‫مــن تاريــخ إيقافــه وجلــده ثمانــن جلــدة علــى دفعتــن وأخــذ التعهــد عليــه‬\n                       ‫واإلبعــاد‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫ـدي‬\n ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ النبــي بعــده وبعــد فلـ َّ‬\n‫ـاء علــى‬\n        ‫أنــا ‪ ................‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫املعاملــة الــواردة إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة‬\n‫األحســاء برقــم ‪ 28‬وتاريــخ ‪1434/01/03‬ه ـ واملقيــدة بهــذه احملكمــة‬\n‫برقم‪3426307‬وتاريــخ ‪1434/01/05‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n‫الرئيــس برقــم ‪ 345694‬وتاريــخ ‪1434/01/05‬ه ـ فتحــت اجللســة‬\n‫األولــى الســاعة احلاديــة عشــرة والنصــف وفيهــا حضــر املدعــي العــام‬\n‫‪ ........‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطــاب ســعادة‬\n‫رئيــس دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء ذي الرقــم‬\n‫ا بصفتــي مدعيـ ًا‬     ‫‪ 13415‬والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه قائـ ً‬\n‫عامـ ًا بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي علــى ‪،................‬‬\n‫البالــغ مــن العمــر(‪ )28‬عامـ ًا ‪ ،‬فلبينــي اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫رقــم (‪ ).............‬غيــر مســلم‪ ،‬محصــن‪ ،‬ميكانيكــي ســيارات‪ ،‬قبــض‬\n‫علي ــه بـتـاري ــخ ‪1433/12/11‬ه ـ أوق ــف بـم ــوجب أمــر التوقيــف رقــم (ه ـ‬\n‫ق‪ )11453/2/2‬وتاريــخ ‪1433/12/12‬ه ـ اســتنادا للقــرار الــوزاري‬\n\n                                                                                        ‫‪302‬‬\n\f      ‫(‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ وجــرى متديــد توقيفــه (‪ )25‬يـوم ـ ًا اعتبارا‬\n      ‫مــن ‪1433/12 /16‬ه ـ مبوجــب أمــر التمديــد رقــم (ه ـ ق ‪)58020/3/ 1‬‬\n      ‫وتاريــخ ‪1433/12/15‬ه ـ اســتنادا للمــادة (‪ )114‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة وأحيــل إلــى شــعبة ســجن محافظــة األحســاء‪ .‬أنــه بتاريــخ‬\n      ‫‪1433/12/11‬ه ـ مت القبــض عليــه بنــاء علــى بــاغ يتضمــن قيــام املدعــى‬\n      ‫عليــه بدخــول منــزل ‪....../‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫(‪ ).......‬وأنــه يوجــد شــاهدين شــاهدوه وهــو يخــرج مــن املنــزل يرتــدي‬\n      ‫عباءة نســائية‪ .‬وبضبط أقوال الشــاهد األول‪........‬باكســتاني‪ -‬اجلنســية‬\n      ‫مبوجــب رخصــة اإلقامــة رقــم (‪ ).....‬أفــاد أنــه كان يجلــس مــع زميلــه‬\n      ‫وشــاهدا املدعــى عليــه وهــو يدخــل املنــزل وبقيــا أمــام املنــزل وبعــد قرابــة‬\n      ‫الســاعة والنصــف خرجــت اخلادمــة مــن املنــزل وألقــت نظرة علــى الطريق‬\n      ‫وشــاهدها وزميلــه وبعــد دخولهــا بحوالــي عشــر دقائــق خــرج املدعــى‬\n      ‫عليــه مــن املنــزل وهــو يرتــدي عبــاءة نســائية وقامــا باإلبــاغ عنــه ومت‬\n      ‫القبــض عليــه‪ .‬وبضبــط أقــوال الشــاهد الثاني‪.....‬باكســتاني‪ -‬اجلنســية‬\n      ‫مبوجــب رخصــة اإلقامــة رقــم (‪ ).....‬جــاءت أقوالــه مطابقــة ألقــوال‬\n      ‫الشــاهد األول‪ .‬وبضبــط أقــوال اخلادمة‪.....‬فلبينيــة‪ -‬مبوجــب رخصــة‬\n      ‫اإلقامــة رقــم (‪( ).......‬صــدر لهــا أمــر حفــظ أوراق) أفــادت أنهــا تعــرف‬\n      ‫املتهــم يف الســابق وأنــه اتصــل عليهــا وأخبرهــا عــن رغبتــه يف مقابلتهــا‬\n      ‫وقامــت بوصــف منــزل كفيلهــا لــه وحضــر لهــا املدعــى عليــه ومكنتــه‬\n      ‫مــن دخــول منــزل كفيلهــا وجلــس معــه يف فنــاء املنــزل وملــا شــعر بــأن‬\n      ‫هنــاك أشــخاص شــاهدوه طلــب منهــا عبــاءة وقامــت بإعطائــه العبــاءة‪.‬‬\n      ‫وباســتجواب املدعــى عليــه ‪ ........ /‬أقــر بأنــه علــى عالقــة باخلادمــة يف‬\n      ‫الســابق وأنهــا مكنتــه مــن دخــول منــزل كفيلهــا ودخــل منــزل كفيلهــا‬\n\n\n‫‪303‬‬\n\f‫وبقــي معهــا يف فنــاء املنــزل وملــا شــعر بــأن هنــاك أشــخاص شــاهدوه قــام‬\n‫بلبــس عبــاءة نســائية بغــرض التخفــي‪ .‬وقــد أســفر التحقيــق عــن توجيــه‬\n‫االتهــام لــه بإقامــة عالقــة مــع امــرأة ال متــت لــه بصلــة و دخــول منــزل‬\n                ‫كفيلهــا واالختــاء بهــا وذلــك لألدلــة والقرائــن التاليــة ‪-:‬‬\n‫‪-1‬أقوالــه املدونــة علــى الصفحتــن رقــم (‪ )4،3‬مــن دفتــر التحقيــق‬\n                                                         ‫املرفــق علــى اللفــة (‪.)12‬‬\n‫‪-2‬أقــوال اخلادمــة املدونــة علــى الصفحــات (‪ )10،9‬مــن دفتــر‬\n                          ‫االســتدالالت األوليــة املرفــق علــى اللفــة (‪.)1‬‬\n‫‪-3‬مــا جــاء يف شــهادة الشــاهدين املدونــة علــى الصفحــات (‪ )14،13‬مــن‬\n                            ‫دفتــر االســتدالالت األوليــة املرفــق علــى اللفــة (‪.)1‬‬\n‫‪-4‬توافــق أقــوال املتهــم مــع مــا جــاء يف أقــوال اخلادمــة والشــاهدين‪.‬‬\n‫وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق مســجلة‬\n‫حتــى تاريخــه‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه‬\n‫املعتبــرة شــرع ًا ـ فعــل محــرم ومعاقــب عليــه شــرع ًا اطلــب إثبــات مــا‬\n‫أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره ‪( .‬علمـ ًا‬\n‫بــأن احلــق اخلــاص ال زال قائم ـاً) عليــه فقــد حضــر املدعــى عليــه وبعــد‬\n‫التأكــد مــن هويتــه جــرى عــرض دعــوى املدعــي العــام عليــه بواســطة‬\n‫املترجــم فلبينــي اجلنســية مبوجــب رخصــة اإلقامــة الصــادرة مــن جــوازات‬\n‫معروف لدينــا بالعدالة فأجاب قائالً‪:‬‬  ‫ٌ‬        ‫الهفــوف برقــم (‪ )....‬مســلم الديانــة‬\n‫مــا ذكــره املدعــي العــام مــن اتهامــي بإقامــة عالقــه مــع امــرأ ٍة المتــت‬\n‫لــي بصلــة ودخــول منــزل كفيلهــا واالختــاء بهــا فصحيــح وذلــك أننــي‬\n‫تعرفــت علــى املــرأة املذكــورة وهــي مــن جنســية فلبينيــة وحضــرت إلــى‬\n‫منــزل كفيلهــا وقامــت بتمكينــي مــن دخــول املنــزل وجلســت أتكلــم‬\n\n\n                                                                                         ‫‪304‬‬\n\f      ‫ـأن هنــاك أشــخاص ًا شــاهدوني طلبــت‬                    ‫ـعرت بـ َّ‬\n                                                                      ‫معهــا يف فنــاء املنــزل وملــا شـ ُ‬\n      ‫مت القبــض علــي وأنــا متــزوج لكننــي‬                 ‫منهــا عبــاءة ولبســتها وعنــد اخلــروج َّ‬\n      ‫مطلــق وقــد أســلمت بحمــد اهلل يف الســجن وأرجــو مــن اهلل التوبــة‬\n      ‫واملغفــرة هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة‬\n      ‫ومنهــا كــرت ســوابق املدعــى عليــه املتضمــن عــدم وجــود ســوابق عليــه‬\n      ‫كمــا جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه املتضمنــة‬\n      ‫ـاء علــى ماتقــدم مــن الدعــوى‬                 ‫أ َّنــه أوقــف بتاريخ‪1433/12/11‬ه ـ فبنـ ً‬\n      ‫واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه والتأكــد مــن أهليتــه وبعــد‬\n      ‫أن املدعــى عليــه أقـ َّـر بإقامــة عالقــة‬          ‫دراســة أوراق املعاملــة وتأملهــا ومبــا َّ‬\n      ‫أن‬‫مــع امــرأ ٍة المتــت لــه بصلــة ودخــول منــزل كفيلهــا واالختــاء بهــا ومبــا َّ‬\n      ‫{و َل ُت ْف ِسـ ُـدوا‬\n                          ‫مــا صــدر مــن املدعــى عليــه مــن احملــرم شــرع ًا قــال تعالــى ‪َ :‬‬\n                      ‫{وال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n      ‫الل ال ُي ِحـ ُّـب‬                            ‫ض َب ْعَــد ِإ ْص َلحِ َهــا } وقــال تعالــى ‪َ :‬‬         ‫ِف ْ َ‬\n                                                                                                        ‫ال ْر ِ‬\n      ‫ْال ُْع َتدِ يـ َـن } وقــال صلــى اهلل عليــه وســلم ‪(( :‬كلُّ املســلم علــى املســلم‬\n      ‫وعرضــه)) وقــال صلــى اهلل عليــه وســلم ‪ ( :‬مــا خــا‬                 ‫ُ‬       ‫دم ـ ُه وما ُل ـ ُه‬\n                                                                                                       ‫ـرام ُ‬‫حـ ٌ‬\n      ‫رجــل بامــرأة إال كان الشــيطان ثالثهمــا ) ممايســتوجب تعزيــر املدعــى‬\n      ‫عليــه علــى ذلــك لــذا كلــه وألجــل احلــق العــام حكمت علــى املدعى عليه‬\n      ‫ـدي إدانــة املدعــى عليــه بإقامــة عالقــة مــع امــرأ ٍة‬          ‫مبــا يلــي ‪ :‬أو ًال ‪ /‬ثبــت لـ َّ‬\n      ‫المتــت لــه بصلــة ودخــول منــزل كفيلهــا واالختــاء بهــا وعزرتــه لقــاء ذلــك‬\n      ‫بســجنه ثالثــة أشــهر مــن تاريــخ إيقافــه علــى ذمــة القضيــة وبجلــده ثمانني‬\n      ‫جلــدة علــى دفعتــن متســاويتني كل دفعــة أربعــون جلــدة بــن كل دفعــة‬\n      ‫وأخــرى مــدة التقــل عــن عشــرة أيــام ‪ .‬ثالث ـ ًا ‪/‬يؤخــذ عليــه التعهــد بعــدم‬\n      ‫العــودة ملثــل مــا صــدر منــه ويبعــد عــن اململكــة بعــد انتهــاء محكوميتــه‬\n      ‫ـاء لشــره ‪ .‬وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعــى عليــه بحقــه‬                              ‫اتقـ ً‬\n\n‫‪305‬‬\n\f‫يف متييــز احلكــم بواســطة مترجــم احملكمــة قــرر قناعتــه بــه وطلــب‬\n‫املدعــي العــام رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق‬\n‫احلكــم دون الئحــة اعتراضيــة مكتفي ـ ًا مبــا ورد يف الئحــة الدعــوى‬\n‫وأقفلــت اجللســة الســاعة الثانيــة عشــرة وصلــى اهلل وس ـلَّم علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر يف ‪1434/01/24‬هــ‪ .‬احلمــد‬\n‫هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة األولــى‬\n‫مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء برقــم ‪3426307‬‬\n‫وتاريــخ ‪1434/2/9‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪/34/371707‬ج‪1‬‬\n‫وتاريــخ ‪1434/2/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ املســجل برقــم ‪ 3420794‬وتاريــخ ‪1434/1/24‬ه ـ‬\n‫اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ ........ /‬فلبينــي اجلنســية يف قضيــة‬\n‫اختــاء محــرم وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                         ‫وصحبــه وســلم حــرر يف ‪1434/4/7‬ه ـ‬\n\n\n\n\n                                                                                          ‫‪306‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":301,"source_page_end":306,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0370bc5ce255dbccdb57ba72fb34fd8c15aa05e94f36cc5ec86f9d091b3169b1","normalized_text_hash":"4a327f25311af8fe035facf86a09cbc6903952c7e0855b49cb814bf4f0188d0e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p301-3420794"},{"id":"b6527ac6-dc7e-5fb6-836b-402064915b5a","document_type":"judgment","category":"judicial","subcategory":"general","title":"خلوة محرمة -إقامة عالقة محرمة -إيواء فتاة -تغرير بفتاة قاصر -تغييب فتاة عن أهلها -مطالبة بتعزير للحق اخلاص - إقرار املدعى عليه -مين -التعزير بالسجن واجللد -صرف النظر -قول اهلل تعالى ( :وتعاونوا على البر والتقوى وال تعاونوا على اإلثم والعدوان).","document_number":"3412775","case_number":"3370087","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/14","year":"1434","subject":"خلوة محرمة -إقامة عالقة محرمة -إيواء فتاة -تغرير بفتاة قاصر -تغييب فتاة عن أهلها -مطالبة بتعزير للحق اخلاص - إقرار املدعى عليه -مين -التعزير بالسجن واجللد -صرف النظر -قول اهلل تعالى ( :وتعاونوا على البر والتقوى وال تعاونوا على اإلثم والعدوان).","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3412775 :‬تاريخه ‪1434/1/14:‬هـ‬\n                         ‫رقم الدعوى‪3370087 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34229755‬تاريخه‪1434/6/4 :‬هـ‬\n\n\n      ‫خلــوة محرمــة ‪ -‬إقامــة عالقــة محرمــة ‪ -‬إيــواء فتــاة ‪ -‬تغريــر بفتــاة‬\n      ‫قاصــر ‪ -‬تغييــب فتــاة عــن أهلهــا ‪ -‬مطالبــة بتعزيــر للحــق اخلــاص ‪-‬‬\n      ‫إقــرار املدعــى عليــه ‪ -‬ميــن ‪ -‬التعزيــر بالســجن واجللــد ‪ -‬صــرف النظــر‬\n\n\n\n\n      ‫‪ -‬قــول اهلل تعالــى ‪( :‬وتعاونــوا علــى البــر والتقــوى وال تعاونــوا علــى‬\n                                                                ‫اإلثــم والعــدوان)‪.‬‬\n      ‫‪ -‬قولــه تعالــى (إن الذيــن يحبــون أن تشــيع الفاحشــة يف الذيــن آمنــوا‬\n                                         ‫لهــم عــذاب أليــم يف الدنيــا واآلخــرة )‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه عــن اتهامــه بالتغريــر بفتــاة‬\n      ‫قاصــر‪ ،‬وإقامــة عالقــة محرمــة‪ ،‬وتغييبهــا‪ ،‬وإيوائهــا يف منزلــه‪،‬‬\n      ‫حيــث تقــدم أحــد األشــخاص مخبــر ًا عــن تغيــب ابنتــه عــن منزلــه‪،‬‬\n      ‫وطلــب املدعــي العــام تعزيــر املدعــى عليــه لقــاء مــا نســب إليــه ومصــادرة‬\n      ‫اجلــوال املســتخدم يف اجلرميــة‪ ،‬أقــر املدعــى عليــه بدعــوى املدعــي العــام‬\n      ‫بخصــوص العالقــة وأنكــر مــا ســوى ذلــك‪ ،‬طلــب مــن املدعــي العــام‬\n      ‫بينتــه علــى دعــواه فذكــر انــه ليــس لديــه إال مــا جــاء يف أوراق املعاملــة‪:‬‬\n      ‫ومنهــا محضــر االســتجواب واملتضمــن انطبــاق مــا ذكرتــه الفتــاة علــى‬\n\n‫‪307‬‬\n\f‫صفــة الشــقة العائــدة للمدعــى عليــه ‪ ،‬حكمــت احملكمــة للشــبهة‬\n‫بتعزيــر املدعــى عليــه بالســجن واجللــد لقــاء توجــه التهمــة بحــق مــا جــاء‬\n‫يف دعــوى املدعــي العــام ‪ ،‬قنــع املدعــى عليــه باحلكــم ‪ ،‬واملدعــي العــام‬\n‫قــرر اعتراضــه علــى احلكــم بالئحــة اعتراضيــة ‪ ،‬صــدق احلكــم مــن‬\n‫محكمــة االســتئناف ‪ ،‬حضــر املدعــي اخلــاص وطلــب حقــه اخلــاص مــن‬\n‫املدعــى عليــه وذلــك بتعزيــر املدعــى عليــه ‪ ،‬أنكــر املدعــى عليــه مــا‬\n‫جــاء بدعــوى املدعــي اخلــاص ‪ ،‬طلــب مــن املدعــي اخلــاص بينتــه علــى‬\n‫دعــواه ضــد املدعــى عليــه ‪ ،‬فقــرر أنــه ليــس لديــه بينــة ســوى مــا جــاء‬\n‫يف أوراق املعاملــة ‪ ،‬وجــرى إفهامــه بــأن لــه ميــن املدعــى عليــه علــى نفــي‬\n‫دعــواه ‪ ،‬فوافــق علــى ذلــك وبعــرض اليمــن علــى املدعــى عليــه‪ ،‬حلفهــا‬\n‫علــى الصفــة املطلوبــة‪ .‬حكمــت احملكمــة بصــرف النظــر عــن دعــوى‬\n‫املدعــي اخلــاص ضــد املدعــى عليــه ‪ ،‬قنــع املدعــي اخلــاص واملدعــى عليــه‬\n‫باحلكــم ‪ ،‬أمــر القاضــي املدعــي العــام التحقيــق مــع الفتــاة ‪ ،‬وتطبيــق‬\n‫نظــام اإلجــراءات اجلزائيــة يف حقهــا حســب التعليمــات ألن املــرأة خرجــت‬\n                                                           ‫بطوعهــا واختيارهــا ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة‬\n‫اجلزائيــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم وتاريــخ‬\n‫‪ 1433/12/25‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ ‪1433/12/22‬‬\n‫ه ـ ففــي يــوم األربعــاء املوافــق‪ 1434/01/07‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 11 : 45‬وفيهــا حضــر املدعــي العــام املكلــف باالدعــاء العــام‬\n\n                                                                                     ‫‪308‬‬\n\f      ‫مبوجــب خطــاب هيئــة التحقيــق واالدعــاء العــام رقــم ‪ 15832‬وتاريــخ‬\n      ‫‪1433/3/6‬ه ـ وأدعــى قائــا بصفتــي عضــو هيئــة التحقيــق واالدعــاء‬\n      ‫العــام بدائــرة محافظــة جــدة أدعــي علــى ‪)36( ........‬عام ـ ًا محصــن‬\n      ‫‪ ........‬ســعودي اجلنســية ‪ ،‬مبوجــب ســجل مدنــي رقم(‪،)....‬قبــض‬\n      ‫عليــه بتاريــخ ‪1433/11/1‬ه ـ وأوقــف مبوجــب أمــر التوقيــف رقــم ه ـ‬\n      ‫م‪70692/3/2‬وتاريــخ ‪1433/11/2‬ه ـ وأحيــل لســجون محافظــة جــدة‬\n      ‫مبوجــب أمــر التمديــد رقــم ه ـ م‪ 73265/3/2‬وتاريــخ ‪1433/11/15‬ه ـ‬\n      ‫اســتنادا للمــادة (‪ )113‬مــن نظــام اإلجــراءات اجلزائيــة حيــث أنــه بتاريــخ‬\n      ‫‪1433/11/26‬ه ـ قبــض علــى املتهــم أعــاه بعــد أن تقــدم املواطــن‪........‬‬\n      ‫تغيــب ابنتــه‪)15(، ........‬عام ـ ًا ‪،‬عــن منــزل ذويهــا وبســماع أقــوال‬\n      ‫الفتــاة‪)15( ........‬عام ـ ًا ذكــرت أنهــا تعرفــت علــى املتهــم عــن طريــق‬\n      ‫اإلنترنــت وكان بينهمــا مكاملــات وقــد تقــدم خلطبتهــا مــن والدهــا ولــم‬\n      ‫يوافــق والدهــا علــى زواجهمــا‪ ،‬وأنــه قــام املتهــم باحلضــور إلــى منزلهــا يف‬\n      ‫‪ ........‬وأخذهــا ملنزلــه يف ‪ ........‬وبقيــت عنــده مــن يــوم األربعــاء إلــى يــوم‬\n      ‫األحــد وكان يوجــد معهــا شــقيقات املتهــم ‪ ،‬وبعــد ذلــك أعادهــا ملنــزل‬\n      ‫والدهــا يف ‪ ،........‬كمــا ذكــرت أن ســبب خروجهــا مــن منزلهــا هــو‬\n      ‫وجــود خــاف بينهــا وبــن والدهــا وبســؤال شــقيقة املتهــم الفتــاة‪، ........‬‬\n      ‫(‪)22‬عامـ ًا بأنهــا ليــس لهــا عالقــة باملدعيــة ولــم تكــن موجــودة باملنــزل‬\n      ‫أثنــاء تواجــد الفتــاة كمــا تدعــي‪ ،‬وبوصفهــا ملنــزل شــقيقها املتهــم‬\n      ‫انطبقــت األوصــاف علــى مــا ســبق وادعــت بــه املدعيــة وباســتجواب‬\n      ‫املتهم‪........‬أفــاد بأنــه تعــرف علــى الفتــاة عــن طريــق اإلنترنــت وأصبــح‬\n      ‫بينهمــا مكاملــات هاتفيــة وبعــد ذلــك ذهــب لوالــد الفتــاة خلطبتهــا والــذي‬\n      ‫قــام برفضــه ولكنــه لــم يحضرهــا ملنزلــه وبالبحــث عــن ســوابقه عثــر لــه‬\n\n\n‫‪309‬‬\n\f‫علــى قضيــة ســابقة أحيلــت للمحكمــة اجلزئيــة برقــم ه ـ م‪56518/3/2‬‬\n‫وتاريــخ ‪1433/8/20‬ه ـ بتهمــة إقامــة عالقــة بفتــاة واالختالء بهــا وتقبيله‬\n‫لهــا وقــد أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليــه بتغريــره‬\n‫بفتــاة قاصــر وإقامــة عالقــة محرمــة معهــا وتغييبهــا وإيوائهــا مبنزلــه‬\n‫‪،‬وذلــك لألدلــة والقرائــن التاليــة مــا جــاء بأقــوال املتهــم املدونــة مبحضــر‬\n‫االســتجواب املرفــق لفــه رقــم (‪ )13‬صفحــة رقــم (‪ )2-1‬مــا جــاء بأقــوال‬\n‫الفتــاة املدونــة مبحضــر االســتجواب لفــه رقــم (‪ )13‬صفحــة رقــم(‪)5-4‬‬\n‫وانطبــاق مــا ذكرتــه مــن وصــف علــى شــقة املتهــم وحيــث إن مــا أقــدم‬\n‫عليــه املذكــور يعــد فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات‬\n‫مــا نســب إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك كمــا أطلــب‬\n‫مصــادرة جهــاز اجلــوال املســتخدم يف اجلرميــة نــوع ‪ ....‬موديــل واحملجــوز‬\n                         ‫برقــم ه ـ م‪ 79422/3/2‬وتاريــخ ‪1433/12/18‬هــ‪.‬‬\n‫وبعــرض مــا ورد بدعــوى املدعــي العــام علــى املدعــي عليــه احلاضــر يف‬\n‫ا مــا ذكــر املدعــي العــام يف دعــواه مــن‬      ‫املجلــس الشــرعي قــرر قائ ـ ً‬\n‫توجيــه االتهــام لــي بالتغريــر بفتــاه قاصــر وإقامــة عالقــة محرمــه معهــا‬\n‫وتغيبهــا وإيوائهــا مبنزلــي فغيــر صحيــح جملــة وتفصيــا والصحيــح أننــي‬\n‫قــد تقدمــت لطلــب خطبــه الفتــاة املذكــورة عــن طريــق أحــد مواقــع‬\n‫الــزواج وأعطانــي املوقــع رقــم والدهــا وتواصلــت معــه وطلبــت منــه الــزواج‬\n‫مــن أبنتــه فرفــض ذلــك إال أن الفتــاه اتصلــت علــى وأخبرتنــي برغبتهــا‬\n‫بالــزواج منــي وأخــذت تتواصــل معــي وتخبرنــي عــن عــدم اقتناعهــا مبــا‬\n‫أتخــذه أهلهــا مــن قــرار بعــدم املوافقــة علــى الــزواج منــي وأخبرتنــي‬\n‫أنهــا ســتهرب إلــى جدهــا ألجــل الضغــط علــى أهلهــا إلقناعهــم بالــزواج‬\n‫فنصحتهــا بعــدم فعــل ذلــك ثــم أتصــل علــي والدهــا بعــد ذلــك وســألني‬\n\n\n                                                                                       ‫‪310‬‬\n\f      ‫عــن البنــت فأخبرتــه بذلــك وعــن عــدم معرفتــي مبكانهــا فأخــذ يســبني‬\n      ‫ثــم أغلــق اجلــوال هــذا مــا لــدي وبعــرض ذلــك علــى املدعــي العــام قــال‬\n      ‫الصحيــح مــا ذكــرت وبســؤال املدعــي العــام هــل لديــه بينــه علــى مــا‬\n      ‫ذكــر قــال بينتــي تتمثــل يف أقــوال املتهــم املدونــة مبحضــر االســتجواب‬\n      ‫املرفــق رقــم (‪ )13‬صفحــة رقــم (‪)2-1‬أقــوال الفتــاه املدونــة مبحضــر‬\n      ‫االســتجواب لفــة رقــم (‪)13‬صفحــة رقــم (‪)4-3‬وانطبــاق مــا ذكرتــه مــن‬\n      ‫وصــف علــى شــقة املتهــم عليــه فقــد جــرى االطــاع علــى أوراق املعاملــة‬\n      ‫فوجدتهــا طبقــا ملــا ذكــر املدعــي العــام يف الئحتــه كمــا وجــدت تطابــق‬\n      ‫أقــوال الفتــاه مــع أقــوال شــقيقة املتهــم يف وصــف الشــقة العائــدة لــه هــذا‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا ورديف أقــوال املدعــى‬\n      ‫عليــه وجوابــه علــى الدعــوى وحيــث أن املدعــى عليــه توجــد عليــه قضيــة‬\n      ‫أخــرى مشــابهه لهــذه القضيــة مشــار إليهــا يف الئحــة الدعــوى العامــة‬\n      ‫ولقولــه تعالــى (وتعاونــوا علــى البــر والتقــوى وال تعاونــوا علــى اإلثــم‬\n      ‫والعــدوان ) ولقولــه تعالــى (إن الذيــن يحبــون أن تشــيع الفاحشــة يف‬\n      ‫الذيــن آمنــوا لهــم عــذاب اليــم )وجلميــع مــا تقــدم وحيــث أن مــا ســبق ال‬\n      ‫يكفــى إلثبــات إدانــة املتهــم ويقــوى الشــبهة يف حقــه يف توجيــه االتهــام‬\n      ‫لــه مبــا ســبق وجلميــع مــا تقــدم فقــد حكمــت علــى املدعــى عليــه نظيــر‬\n      ‫ذلــك بســجنه ملــده ســنه ونصــف وجلــده مائتــي ســوط علــى دفعــات كل‬\n      ‫دفعــة خمســن ســوط وبــن كل والتــي تليهــا مــده ال تقــل عــن خمســة‬\n      ‫أيــام وبعرضــه علــى الطرفــن قــرر املدعــى عليــه القناعــة وقــرر املدعــي‬\n      ‫العــام عــدم القناعــة وطلــب االســتئناف فجــرى إجابتــه لذلــك وســيجرى‬\n      ‫اتخــاذ الــازم حســب إجــراءات االســتئناف جــرى النطــق باحلكــم يف‬\n      ‫متــام الســاعة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n‫‪311‬‬\n\f                                ‫وصحبــه وســلم حــرر يف ‪ 1434/01/07‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء املوافــق ‪1434/6/20‬ه ـ الســاعة‬\n‫العاشــرة والربــع فتحــت اجللســة لــدي القاضــي باحملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة والقائــم بعمــل القاضــي مبوجــب خطــاب التكليــف رقــم‬\n‫يف ‪1434/5/19‬ه ـ وجــرى اإلطــاع علــى أوراق املعاملــة وكانــت قــد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة وبرفقهــا‬\n‫قرارهــا رقــم يف ‪1434/6/4‬ه ـ باملصادقــة علــى احلكــم ونــص احلاجــة‬\n‫منــه (وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر‬\n‫املوافقــة علــى احلكــم واهلل املوفــق )وموقــع ومختــم مــن اصحــاب‬\n‫الفضيلــة أعضــاء الدائــرة اجلزائيــة الرابعــة وهــم كال مــن الشــيخ ‪........‬‬\n‫والشــيخ ‪ ........‬والشــيخ ‪ ........‬فجــرى تدوينــه حفظــا للواقــع وجــرى قفلهــا‬\n‫يف متــام الســاعة العاشــرة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/20‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي إنــا القاضــي باحملكمــة اجلزائيــة مبحافظة‬\n‫جــده وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة برقــم‬\n‫يف ‪1434/8/23‬ه ـ ويف يــوم األحــد املوافــق ‪1434/9/6‬ه ـ الســاعة‬\n‫الواحــدة وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ ........‬وادعــى علــى الســجني احلاضــر باملجلــس الشــرعي ‪ ........‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬قائــا يف دعــواه إن املدعــى‬\n‫عليــه احلاضــر إمامكــم يف املجلــس الشــرعي قــد قــام بالتغريــر بابنتــي‬\n‫وأخذهــا مــن منــزل جدهــا مبحافظــة ‪ ........‬إلــى منزلــه مبحافظــة ‪........‬‬\n‫وغيبهــا عنــده أربعــة أيــام كمــا ورديف الئحــة الدعــوى العامــة ثــم قــام‬\n‫بإعادتهــا لــذا فأنــي آمــل مــن فضيلتكــم معاقبــة املدعــى عليــه يف حقــي‬\n\n\n                                                                                      ‫‪312‬‬\n\f      ‫اخلــاص حيــال مــا بــدر منــه هــذه دعــواي واســأله اجلــواب وبعــرض مــا‬\n      ‫ورد بدعــوى املدعــي علــى املدعــى عليــه قــال مــا ورد يف دعــوى املدعــي‬\n      ‫اخلــاص فغيــر صحيــح جملــة وتفصيــا وبســؤال املدعــي عــن بينتــه فقــال‬\n      ‫بينتــي هــي مــا ورد يف أوراق املعاملــة وحيــث أن مــا ورد يف أوراق املعاملــة‬\n      ‫ال يكفــي إلثبــات مــا ورد يف دعــوى املدعــي كمــا تقــدم عليــه فقــد‬\n      ‫جــرى ســؤاله هــل لديــه بينــه علــى مــا ذكــر قــال ال بينتــه لــدي عليــه فقــد‬\n      ‫جــرى إفهامــه بــأن لــه ميــن املدعــى عليــه علــى نفــي مــا ورد يف دعــواه‬\n      ‫فقــال اطلــب ميينــه وبعــرض اليمــن علــى املدعــى عليــه اســتعد احللــف‬\n      ‫قائــا واهلل العظيــم الــذي ال الــه إال هــو عالــم الغيــب والشــهادة إن مــا‬\n      ‫ورد يف دعــوى املدعــي اخلــاص غيــر صحيــح فلــم أقــم بأخــذ بنــت املدعــي‬\n      ‫اخلــاص وال تغييبهــا وال إيوائهــا واهلل العظيــم هــذا فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة وحلــف املدعــى عليــه اليمــن كمــا طلــب منــه‬\n      ‫فقــد صرفــت النظــر عــن دعــوى املدعــي اخلــاص وبعرضــه علــى الطرفــن‬\n      ‫قــررا القناعــة وحيــث إن الفتــاة قــد خرجــت يطوعهــا واختيارهــا كمــا‬\n      ‫ورد يف ملــف القضيــة لــذا فقــد أمــرت املدعــي العــام التحقيــق مــع الفتــاة‬\n      ‫وتطبيــق نظــام اإلجــراءات اجلزائيــة يف حقهــا حســب التعليمــات وجــرى‬\n      ‫قفلهــا يف متــام الســاعة الواحــدة والنصــف وصلــى اهلل وســلم علــى نبينــا‬\n                                   ‫محمــد والــه وصحبــه وســلم حرر‪1434/9/6‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ ...‬نحــن رئيــس‬\n      ‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقة مكة‬\n      ‫املكرمــة جــرى منــا االطــاع علــى القــرار رقــم وتاريــخ ‪1434/1/14‬ه ـ‬\n      ‫الصــادر مــن فضيلــة الشــيخ‪ ........‬القاضــي باحملكمــة اجلزائيــة بجــدة‪،‬‬\n      ‫املتضمــن دعــوى املدعــي العــام ضــد‪ ، ........‬املتهــم بإقامــة عالقــة محرمــة‬\n\n\n‫‪313‬‬\n\f‫بفتــاة واالختــاء بهــا وتقبيلــه لهــا ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n‫وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة‬\n‫علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                             ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                 ‫‪314‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":307,"source_page_end":314,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3abf0dedfc6292e8890d6069ea64ae6a7eb2516be52ee812bbdd1850897719a1","normalized_text_hash":"4ae4d632c93d2750004c264c3a565c2202dbd0b61ac3fa594de37ff6f6550379","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p307-3412775"},{"id":"e4edca14-b96a-59b1-9798-cf21ad939ac8","document_type":"judgment","category":"judicial","subcategory":"general","title":"إقامة عالقة محرمة مع فتاة -ابتزاز فتاة -تهديد بنشر صور - عدم ثبوت اإلدانة -تعزير للشبهة -تعزير بالسجن واجللد.","document_number":"33299196","case_number":"33306253","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/15","year":"1434","subject":"إقامة عالقة محرمة مع فتاة -ابتزاز فتاة -تهديد بنشر صور - عدم ثبوت اإلدانة -تعزير للشبهة -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33299196 :‬تاريخه‪1433/6/15 :‬هـ‬\n                         ‫رقم الدعوى‪33306253 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 35272648‬تاريخه‪1435/6/17:‬هـ‬\n\n\n      ‫إقامــة عالقــة محرمــة مــع فتــاة ‪ -‬ابتــزاز فتــاة ‪ -‬تهديــد بنشــر صــور ‪-‬‬\n            ‫عــدم ثبــوت اإلدانــة ‪ -‬تعزيــر للشــبهة ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــول اهلل تعالــى‪( :‬إن الذيــن يحبــون أن تشــيع الفاحشــة يف الذيــن‬\n      ‫آمنوا لهم عذاب أليم يف الدنيا و اآلخرة و اهلل يعلم و أنتم ال تعلمون)‬\n                                                                       ‫النــور آيــة (‪.)19‬‬\n                                  ‫‪ -2‬قاعدة اإلقرار حجه على صاحبه مؤاخذ به ‪.‬‬\n      ‫‪ -3‬الرجــوع عــن اإلقــرار مبــا يوجــب التعزير حلق اهلل تعالى ال يقبل من‬\n      ‫صاحبــه جــاء يف املغنــي (‪( .)389/10‬وال يقبــل رجــوع املقــر عــن إقــراره إال‬\n      ‫فيمــا كان حــد ًا هلل تعالــى يــدرأ بالشــبهات ويحتــاط إلســقاطه فأمــا‬\n      ‫حقــوق اآلدميــن وحقــوق اهلل تعالــى التــي ال تدرأ بالشــبهات كالزكاة‬\n                   ‫والكفــارات فــا يقبــل رجوعــه عنهــا و ال نعلــم يف هــذا خالفـ ًا)‬\n\n\n\n      ‫توجــه االتهــام للمدعــى عليــه األول بالتســتر علــى املتهــم الثانــي يف قضيــة‬\n      ‫إقامــة عالقــة محرمــة مــع فتــاة وابتزازهــا وتهديــده للفتــاة وعلــى املدعــي‬\n      ‫عليــه الثانــي بإقامــة عالقــة محرمــة مــع فتــاة وابتزازهــا وتهديدهــا بنشــر‬\n      ‫صورهــا‪ ،‬حيــث تلقــى مركــز هيئــة األمــر باملعــروف والنهــي عن املنكر‬\n\n‫‪315‬‬\n\f‫اتصــا ًال هاتفيـ ًا مــن فتــاة تســتنجد وتســتغيث مــن قيــام شــاب بتهديدهــا‬\n‫وابتزازهــا بصــور قــد حتصــل عليهــا عــن طريــق عالقــة محرمــة بينهمــا‪،‬‬\n‫وأن الشــاب حتصــل علــى مبلــغ عشــرة آالف ريــال مــن الفتــاة عــن طريــق‬\n‫االبتــزاز‪ ،‬وأن الفتــاة حتصلــت علــى هــذا املبلــغ عــن طريــق الســرقة مــن‬\n‫والدتهــا ومكافأتهــا اجلامعيــة‪ ،‬حضــر املدعــى عليــه الثانــي برفقــة‬\n‫األول ملنــزل الفتــاة ألخــذ بطاقــة الصــراف ‪ ،‬ألقــت الفتــاة البطاقــة خــارج‬\n‫الســور‪ ،‬أخــذ املدعــى عليــه الثانــي البطاقــة فتــم القبــض عليــه مــن قبــل‬\n‫أعضــاء هيئــة األمــر باملعــروف والنهــي عــن املنكــر‪ ،‬بتفتيــش جــوال‬\n‫املدعــى عليــه الثانــي وجــدت رســائل التهديــد‪ ،‬طلــب املدعــي العــام إثبات‬\n‫إدانتهمــا مبــا نســب إليهمــا واحلكــم علــى املدعــى عليــه الثانــي بالســجن‬\n‫والغرامــة أو بإحــدى هاتــن العقوبتــن ومصــادرة الهاتــف اجلــوال العائــد‬\n‫للمدعــى عليــه الثانــي واحلكــم عليهمــا بعقوبــة تعزيريــة والتشــديد علــى‬\n‫املدعــى عليــه الثانــي‪ ،‬لــم يحضــر املدعــى عليــه األول‪ ،‬حضــر املدعــى‬\n‫عليــه الثانــي و جــرى عــرض الدعــوى عليــه فأنكــر جميع ما نســب إليه‪،‬‬\n‫أحضــر املدعــي العــام بينتــه عضــوي هيئــة األمــر باملعــروف و النهــي عــن‬\n‫املنكــر ‪ ،‬شــهدا مبــا جــاء يف محضــر القبــض‪ ،‬أقــر املدعــى عليــه الثاني‬\n‫بــأن بطاقــة الصــراف اخلاصــة بالفتــاة بحوزتــه وذلــك مــن أجــل اســتيفاء‬\n‫مســتحقات ماليــة‪ ،‬جــرى االطــاع علــى محاضــر التحقيــق ومشــاهدة‬\n‫الرســائل وبرنــت املكاملــات الصــادرة والــواردة مــن هاتــف املدعــى‬\n‫عليــه الثانــي‪ ،‬صــدر احلكــم بإدانــة املدعــى عليــه الثانــي بإقامــة عالقــة‬\n‫محرمــة مــع فتــاة ال متــت لــه بصلــة‪ ،‬لــم تثبــت اإلدانــة باالبتــزاز والتهديــد‬\n‫ونشــر الصــور وإمنــا توجــه الشــبهة لذلــك‪ ،‬حكمــت احملكمــة بتعزيــر‬\n‫املدعــى عليــه الثانــي بالســجن ســنتني وجلــده مائتــي جلــدة مفرقــة علــى‬\n\n\n                                                                                         ‫‪316‬‬\n\f      ‫أربــع دفعــات ‪ ،‬صــرف النظــر عــن طلــب املدعــي العــام بتطبيــق املادتــن‬\n      ‫(‪ )13/3‬مــن نظــام مكافحــة اجلرائــم املعلوماتيــة ‪ ،‬صــدق احلكــم مــن‬\n                                                            ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ .....‬القاضــي باحملكمــة اجلزئيــة بتبــوك‬\n      ‫بنــاء علــى املعاملــة الــواردة إلــى احملكمــة مــن هيئــة التحقيــق واإلدعــاء‬\n      ‫العــام بتبــوك بكتابهــم رقــم ‪ .....‬وتاريــخ ‪1433/4/28‬ه ـ واحملالــة إلــي‬\n      ‫مــن فضيلــة الرئيــس املســاعد برقــم ‪ 33306253‬وتاريــخ ‪1433/5/2‬ه ـ‬\n      ‫عليــه حضــر املدعــي العــام ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ .....‬واملكلــف لــدى احملكمــة مبوجــب كتــاب التعميــد رقــم يف‬\n      ‫‪1432/11/13‬ه ـ وادعــى علــى الغائــب عــن مجلــس احلكــم ‪ .....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬واحلاضــر معــه ‪ .....‬ســعودي‬\n      ‫ا يف حتريــر دعــواه إنــه‬    ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬قائـ ً‬\n      ‫بتاريــخ ‪1433/3/4‬ه ـ ورد ملركــز شــرطة اخلالديــة محضــر الدوريــات‬\n      ‫األمنيــة رقــم (‪ ).......‬ومحضــر مركــز هيئــة اخلالديــة لألمــر باملعــروف‬\n      ‫والنهــي عــن املنكــر رقــم (‪ ).....‬املتضمــن القبــض علــى كل مــن املدعــو‪/‬‬\n      ‫‪ .....‬واملدعــو‪ ..... /‬بتهمــة تهديــد وابتــزاز حيــث تضمن محضر هيئة األمر‬\n      ‫باملعــروف والنهــي عــن املنكــر تلقيهــم اتصــال هاتفــي مــن فتــاة تســتنجد‬\n      ‫وتســتغيث مــن قيــام شــاب بتهديدهــا وابتزازهــا بصــور قــد حتصــل عليها‬\n      ‫عــن طريــق عالقــة محرمــة بينهمــا التــي أصبــح يتخذهــا وســيلة للضغــط‬\n      ‫علــى الفتــاة حتــى تســتجيب ملطالبــه الدنيئــة واحلصــول علــى املبالــغ املاليــة‬\n      ‫التــي يريدهــا مبينـ ًا للفتــاة أنــه ســوف يقــوم بنشــر صورهــا وفضــح أمرهــا‬\n\n‫‪317‬‬\n\f‫عنــد إخوتهــا إن لــم تســتجب لــكل مطالبــه حيــث حتصــل علــى مبلــغ‬\n‫مالــي وقــدره عشــرة آالف ريــال أرغمهــا علــى ســرقته مــن أمهــا إضافــة‬\n‫إلــى مبالــغ ماليــة أخــرى حتصــل عليهــا عــن طريــق مكافــأة اجلامعــة‬\n‫ويطلــب منهــا أيض ـ ًا متكينــه مــن نفســها وقــد اختلــى بهــا عــدة مــرات‬\n‫وأفــادت أنــه يحتفــظ علــى صورهــا بذواكــر يضعهــا يف منزلــه وتقدمــت‬\n‫بشــكوى خطيــة مرفــق صــوره منهــا إضافــة إلــى محاضــر مشــاهدة‬\n‫للرســائل التــي قــام الشــاب بإرســالها إلــى جــوال الفتــاة مرفــق صــور‬\n‫منهــا ويف هــذا اليــوم قــام الشــاب باالتصــال علــى جــوال الفتــاة وطلــب‬\n‫منهــا إعطائــه مبلــغ مالــي وقــدره ألــف ريــال وألــح يف طلبهــا وأنــه ســوف‬\n‫ا لتقــوم الفتــاة برمــي بطاقــة‬  ‫يحضــر إلــى منزلهــا بعــد الســاعة ‪ 12‬لي ـ ً‬\n‫الصــراف اآللــي اخلاصــة بهــا أمــام املنــزل ليقــوم هــو بــدوره باحلصــول علــى‬\n‫املبلــغ املالــي مــن حســابها فتــم التنســيق مــع الدوريــات األمنيــة مســبق ًا‬\n‫واالنتقــال للموقــع للتحــري والتثبــت أثنــاء ذلــك حضــرت ســيارة مــن نــوع‬\n‫‪ .....‬حتمــل الرقــم (‪ ).....‬والتــي يســتقلها املدعــى عليهمــا األول والثانــي‬\n‫وقامــت بالوقــوف أمــام منــزل الفتــاة فقــام الراكــب وهــو املدعــى عليــه‬\n‫الثانــي (الــذي يقــوم بتهديــد الفتــاة) بالنــزول أمــام املنــزل حيــث قامــت‬\n‫الفتــاة برمــي بطاقــة الصــراف اآللــي لــه وعــاد إلــى ســيارة زميلــه وعنــد‬\n‫محاولــة قائــد الســيارة املدعــى عليــه األول وزميلــه املدعــى عليــه الثانــي‬\n‫مغــادرة املوقــع مت اســتيقافهما مبســاندة الدوريــات األمنيــة والقبــض‬\n‫عليهمــا فعثــر بحــوزة املدعــى عليــه الثانــي علــى جهــاز جــوال مــن نــوع‬\n‫‪ ......‬يحتــوي علــى الرقــم (‪ ).....‬الــذي يســتخدمه بتهديــد الفتــاة وابتزازهــا‬\n‫وبطاقــة الصــراف اآللــي التــي أخذهــا مــن الفتــاة وأفــاد أنــه حتصــل علــى‬\n‫مبلــغ مالــي قــدره عشــرة آالف ريــال مــن الفتــاة إضافــة إلــى مبالــغ ماليــة‬\n\n\n                                                                                       ‫‪318‬‬\n\f      ‫أخــرى وقــد حتصــل أيضـ ًا علــى صورهــا التــي اتخذهــا وســيلة لتهديدهــا‬\n      ‫وابتزازهــا وإرغامهــا لالســتجابة ملطالبــه أمــا الســائق وهــو املدعــى عليــه‬\n      ‫األول فهــو مــن قــام بإيصــال املدعــى عليــه الثانــي بســيارته إلــى منــزل‬\n      ‫الفتــاة وهــو علــى إطــاع مبــا يقــوم بــه املدعــى عليــه الثانــي مــن تهديــدات‬\n      ‫للفتــاة ويخشــى منــه أن يفضــح أمــر الفتــاة ومت إحالتهمــا ملركــز شــرطة‬\n      ‫‪ ........‬وقــد مت إعــداد محاضــر مشــاهدة للرســائل مــن قبــل أعضــاء هيئــة‬\n      ‫األمــر باملعــروف والنهــي عــن املنكــر وكانــت علــى النحــو التالــي أ‪/‬‬\n      ‫فهــذا مــا متــت مشــاهدته مــن رســائل مرســلة مــن جــوال الشــاب املهــدد‬\n      ‫رقــم (‪ ).....‬ورقــم (‪ ).....‬إلــى جــوال الفتــاة املبلغــة وهــي علــى النحــو التالــي‬\n      ‫‪(.1‬ورب البيــت مــو تهديــد إال فعــل وأنــا عــارف ليــش تســوي كــذا تبغــي‬\n      ‫متلكــي خيــر إن شــاء اهلل واهلل لفركشــها وأنــا دريــت بــكل شــيء)‬\n      ‫مــن جــوال رقــم (‪ ).....‬وتاريــخ ‪ 2012/1/23‬م يف متــام الســاعة ‪ 1:40‬م‬\n      ‫‪(.2‬تكفــي فزعتــك أبــي ‪ 1000‬واهلل غالتــك عنــدي مــا بنســاها لــك‬\n      ‫وبردهــا لــك بأســرع وقــت وعــد ولــي يســعدك حبيبتــي) مــن جــوال رقــم‬\n      ‫(‪ ).....‬وتاريــخ ‪ 2012/1/22‬م يف متــام الســاعة ‪10:40‬م ‪(.3‬تــري واهلل‬\n      ‫أدري انــه انتظــار حتــى لــو قفلتــي اخلــط لكــن تشــويف اليــوم ردت فعلــي)‬\n      ‫مــن جــوال رقــم (‪ ).....‬وتاريــخ ‪ 2012/1/22‬م يف متــام الســاعة ‪ 5:32‬م‬\n      ‫‪(.4‬يعنــي الزم اخربهــا معاكــي عشــان حتترمينــي طيــب) مــن جــوال رقــم‬\n      ‫(‪ ).....‬يف تاريــخ ‪ 2012/1/22‬م يف متــام الســاعة ‪ 1:12‬ص ‪(.5‬شــايفتيني‬\n      ‫غبــي يصيــر خيــر بــس خلينــي اتشــافى) مــن جــوال رقــم (‪ ).....‬ويف تاريــخ‬\n      ‫‪ 2012/1/21‬م ويف متــام الســاعة ‪ 7:31‬م ب‪ /‬فهــذا مــا متــت مشــاهدته‬\n      ‫مــن رســائل مرســلة مــن جــوال الشــاب املهــدد رقــم (‪ ).....‬إلــى جــوال الفتــاة‬\n      ‫املهــددة وهــي علــى النحــو التالــي ‪( :‬ال تســتحقريني ورب الكعبــة تــرى‬\n\n\n‫‪319‬‬\n\f‫أســويها) (كلمينــي احلــن وال واهلل أكــون أبــن حــرام لــو مــا ســويتها)‬\n‫(يازفــت احنــا ماتفقنــا الصبــاح وكيــف مــا تقــدري تكلمينــي وجوالــك‬\n‫كان انتظــار واهلل تــرى جــاد واهلل مــا يصبح الصبح إال واخوانك داريني‬\n‫بــكل شــيء واهلل عــادي إذا أنتــي مســتحقرتني ومنتــي شــايفتني شــيء‬\n‫واهلل مــا أشــوفك شــيء أبغــى افهــم ليــش مــا تبغــي تكلمينــي) (واهلل مــا‬\n‫لــو مــا تكلمينــي احلــن جليــب العيــد احلــن) (شــويف أنــا بكتــب بورقــة أنــا‬\n‫وأحطهــا عنــد البــاب احلــن بعــد الصــاة بــس قرصــة أذن لكــي علشــان‬\n‫تعــريف أنــي جــاد) (واهلل حلطهــا جــوا الســيارة علشــان مــا ميديــك تأخذيهــا‬\n‫بدخلهــا مــع فتحــة القــزاز) (كذابــة أنتــي وعدتينــي الصبــاح لكــن‬\n‫صادقــة اللــي قالــت عنــك راعيــت ســواقني لكــن طبيعــي واهلل ألخلــي‬\n‫أخوانــك مــن ظهــر رجــال) (وعنــدي اإلثبــات والدليــل واهلل ألربيكــي‬\n‫وال مــا أكــون مــن ظهــر رجــال) (مــا توقعــت أنــه يجــي يــوم وأســويها‬\n‫لكــن خلــي اهلل يكبــر برأســك ينفعــك علــى بالــك مــا أعــرف وضعــك‬\n‫أكثــر مــن ســنتني وأنــا معاكــي أدري لــو تبغــي تكلمينــي كلمتينــي‬\n‫لكــن أنــا احلــن واقــف عنــد املســجد الزنــك خليهــم بــس يدخلــوا بيوتهــم‬\n‫واهلل ألســويها) (واهلل رقــم وعنــدي ألعطيهــا صــورك) ج‪ /‬فهــذا مــا متــت‬\n‫مشــاهدته مــن رســائل مرســلة مــن جــوال الشــاب املهــدد رقــم (‪ ).....‬إلــى‬\n‫جــوال الفتــاة املهــددة وهــي علــى النحــو التالــي ( ‪ .....‬أنتــي وحــده كذابــة‬\n‫وتصرفاتكــي واضحــة لكــن خيــر إن شــاء اهلل اليــوم) (واهلل لربيكــي‬\n‫علــى احلركــة) (مكذبــة أيــن أســويها طيــب شــويف أيــش بحــط علــى‬\n‫الســيارة اللــي بــرا) (واهلل لقلبهــا عــزا الليلــة وأنــا احلــن طالــع لبيتــك)‬\n‫(شــغلي الوســائط يف شــيء راح يعجبــك) (علشــان االنتظــار واهلل حلطهــا‬\n‫احلــن يــاهلل طســي) (خليــك قدهــا) د ‪ /‬فهــذا مــا متــت مشــاهدته مــن‬\n\n\n                                                                                       ‫‪320‬‬\n\f      ‫رســائل مرســلة مــن جــوال الشــاب املهــدد رقــم (‪ ).....‬علــى جــوال الفتــاة‬\n      ‫املهــددة وهــي علــى النحــو التالــي (موعدنــا الصبــاح يــا ال تقولــي إنــي‬\n      ‫ماكلمتــك) (طيــب أرميهــا مــن فــوق مبحفظــه تــرى مــو اختــراع)‬\n      ‫(كلمتــي مــا أثنيهــا وال تنتظــري منــي أي رســالة بعــد هــذي الرســالة‬\n      ‫الصبــاح باتصــل اتصــال ولــو مــا رديتــي وقتهــا تشــويف ردة فعلــي)‪ .‬وقــد‬\n      ‫مت اإلطــاع علــى برنــت املكاملــات ووجــد فيــه عــدة اتصــاالت ورســائل‬\n      ‫واردة وصــادرة مــن رقــم جــوال املتهــم الثانــي (‪ ).....‬إلــى جــوال الفتــاة‪.....‬‬\n      ‫رقــم (‪ ).....‬وإلــى اجلــوال رقــم (‪ )....‬وبضبــط إفــادة الفتــاة املبتــزة ‪.....‬‬\n      ‫واملعرفــة مــن قبــل عضــو هيئــة األمــر باملعــروف والنهــي عــن املنكــر ‪.....‬‬\n      ‫أفــادت بأنهــا قبــل ســنتني قامــت بالتعــرف علــى املدعــى عليــه الثانــي عــن‬\n      ‫طريــق الترقيــم وبــدأت العالقــة بينهمــا باملكاملــات ثــم خرجــت معــه‬\n      ‫مــرات عديــدة وقــد قــام بتصويرهــا بوضــع مخــل وقــد أغواهــا الشــيطان‬\n      ‫وذلــك عــن طريــق جهــازه اجلــوال وكان ذلــك يف بيــت عمه ثــم أخبرها أنه‬\n      ‫سيمســح الصــور ولــم تــرى الصــور بعدهــا صــار يطلــب منهــا مبالــغ ماليــة‬\n      ‫وكانــت تســلمه هــذه املبالــغ بعدهــا صــار يرســل لهــا رســائل ويطلــب‬\n      ‫فيهــا مطالــب ويهددهــا بالصــور بعدهــا قامــت بكتابــة شــكوى ورفعهــا‬\n      ‫للهيئــة وذكــرت أن أرقــام اجلــواالت التــي يقــوم بتهديدهــا هــي ثالثــة‬\n      ‫أرقــام وأنهــا ال حتفــظ إال رقــم واحــد وهــو ( ‪ ).....‬وباســتجواب املدعــى‬\n      ‫عليــه األول‪ ..... /‬بعــد إحاطتــه علم ـ ًا باجلهــة التــي تباشــر التحقيــق معــه‬\n      ‫وبالتهمــة املنســوبة إليــه أنكــر قيامــه بالتســتر علــى املدعــى عليــه الثانــي‬\n      ‫يف قضيــة ابتــزاز فتــاة وذكــر بأنــه ال يعلــم عــن عالقــة املدعــى عليــه‬\n      ‫الثانــي بالفتــاة وأن املدعــى عليــه الثانــي لديــه عــدة أرقــام جــواالت لكنــه‬\n      ‫ال يحفــظ إال الرقــم (‪ )........‬وباســتجواب املدعــى عليــه الثانــي‪ ........‬بعــد‬\n\n\n‫‪321‬‬\n\f‫إحاطتــه علمـ ًا باجلهــة التــي تباشــر التحقيــق معــه وبالتهمــة املنســوبة إليــه‬\n‫أنكــر قيامــه بتهديــد وابتــزاز فتــاة وأعتــرف بعالقتــه بالفتــاة ‪ ........‬عــن‬\n‫طريــق الهاتــف واخلــروج مع ـ ًا برضاهــا وذكــر بــأن رقــم اجلــوال (‪)........‬‬\n‫يعــود لــه وأن رقــم اجلــوال (‪ )........‬يعــود لصديقــة الفتــاة ويرفــض ذكــر‬\n‫اســم صديقــة الفتــاة وذكــر بأنــه ال يعــرف الرقــم (‪ )........‬ملــن يعــود‬\n‫وبإجــراء املواجهــة بــن الفتــاة املبتــزة ‪ ........‬واملدعــى عليــه الثانــي أفــادت‬\n‫الفتــاة بقيــام املدعــى عليــه الثانــي بتصويرهــا بوضــع مخــل يف بيــت عمــه‬\n‫وقيامــه بأخــذ مبالــغ ماليــة منهــا وتهديدهــا بنشــر صورهــا وذلــك عبــر‬\n‫رســائل اجلــوال وبســؤال املدعــى عليــه الثانــي عــن دعــوى الفتــاة أنكــر‬\n‫مــا ذكرتــه جملــة وتفصيــا وذكــر املدعــى عليــه الثانــي بأنــه يطلــب‬\n‫إحضــار ولــي أمــر الفتــاة جلهــة التحقيــق لكــي يحلــون املوضــوع ولــم‬\n‫يتبــن جلهــة التحقيــق أثنــاء املواجهــة أي إجــراء وقــد أســفر التحقيــق إلــى‬\n‫توجيــه االتهــام للمدعــى عليــه األول‪ ........‬بالتســتر علــى املتهــم الثانــي يف‬\n‫قضيــة إقامتــه عالقــة محرمــة مــع فتــاة وابتــزازه وتهديــده للفتــاة وتوجيــه‬\n‫االتهــام للمدعــى عليــه الثانــي ‪ ........‬بقيامــة بإقامــة عالقــة محرمــة مــع‬\n‫فتــاة وابتزازهــا وتهديدهــا بنشــر صورهــا وذلــك لألدلــة والقرائــن التاليــة‬\n‫‪ .1‬اعتــراف املدعــى عليــه الثانــي بعالقتــه بالفتــاة وإرســاله رســائل مــن‬\n‫جوالــه رقــم (‪ )................‬للفتــاة املنــوه عنــه املــدون علــى الصفحــات‬\n‫رقــم (‪ )6-5-4‬مــن دفتــر التحقيــق املرفــق علــى اللفــة رقــم (‪.2 )32‬مــا‬\n‫جــاء بأقــوال املدعــى عليــه األول بــأن املدعــى عليــه الثانــي لديــه عــدة‬\n‫أرقــام جــواالت املنــوه عنــه املــدون علــى الصفحتــن رقــم (‪ )2-1‬مــن دفتــر‬\n                                        ‫التحقيــق املرفــق علــى اللفــة رقــم (‪)32‬‬\n‫‪.3‬مــا جــاء باحملضــر املعــد مــن قبــل أعضــاء هيئــة األمــر باملعــروف والنهــي‬\n\n\n                                                                                          ‫‪322‬‬\n\f      ‫عــن املنكــر املنــوه عنــه املرفــق علــى اللفتــن رقــم (‪.4 )20-19‬مــا جــاء‬\n      ‫مبحضــر مشــاهدة الرســائل املعــد مــن قبــل أعضــاء هيئة األمــر باملعروف‬\n      ‫والنهــي عــن املنكــر املنــوه عنــه املرفــق علــى اللفــات رقــم (‪-15-14-13‬‬\n      ‫‪.5 )16‬مــا جــاء ببرنــت املكاملــات املنــوه عنــه املرفــق علــى اللفــة رقم (‪)98‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا فعــل محــرم ومعاقــب عليــه‬\n      ‫شــرع ًا ومجــرم نظام ـ ًا اســتناد ًا للفقرتــن الرابعــة واخلامســة مــن املــادة‬\n      ‫الثالثــة واملــادة التاســعة مــن نظــام اجلرائــم املعلوماتيــة الصــادر بقــرار‬\n      ‫مجلــس الــوزراء رقــم ( م ‪ )17 /‬وتاريــخ ‪1428/3/8‬ه ـ لــذا أطلــب مايلــي‬\n      ‫‪.1‬إثبــات إدانتهمــا مبــا أســند إليهمــا ‪.2‬احلكــم علــي املدعــى عليــه الثانــي‬\n      ‫بالســجن والغرامــة أو بإحــدى هاتــن العقوبتــن اســتناد ًا للمــادة الثالثــة‬\n      ‫مــن الفقرتــن ( ‪ )5 ،4‬وانطبــاق املــادة التاســعة علــى املتهــم األول من ذات‬\n      ‫النظــام املشــار إليــه ‪.3‬مصــادرة جهــاز اجلــوال املســتخدم يف اجلرميــة جــوال‬\n      ‫مــن نــوع نوكيــا الــذي يحمــل الرقــم التسلســلي رقــم (‪ )........‬اســتناد ًا‬\n      ‫للمــادة (‪ )13‬مــن ذات النظــام املشــار إليــه العائــد للمدعــى عليــه الثانــي‬\n      ‫‪.4‬احلكــم عليهمــا بعقوبــة تعزيريــة رادعــة لهمــا وزاجــرة لغيرهمــا لقاء ما‬\n      ‫أســند إليهما وذلك بقيام املدعى عليه األول بالتســتر على املدعى عليه‬\n      ‫الثانــي يف قضيــة إقامتــه عالقــة محرمــة مــع فتــاة وابتزازه وتهديــده للفتاة‬\n      ‫وقيــام املدعــى عليــه الثانــي بإقامــة عالقــة محرمــة مــع فتــاة ‪.5‬التشــديد‬\n      ‫علــى املدعــى عليــه الثانــي يف العقوبــة ( علم ـ ًا بــأن احلــق اخلــاص مــا زال‬\n      ‫قائم ـ ًا ) هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n      ‫الثانــي ‪ ........‬وســؤاله أجــاب بقولــه مــا ذكــره املدعــي العــام مــن قيامــي‬\n      ‫بإقامــة عالقــة محرمــة مــع فتــاة وتهديدهــا وابتزازهــا بنشــر صورهــا غير‬\n      ‫ا هكــذا أجــاب وبســؤال املدعــي العــام إن كان‬         ‫صحيــح جملــة وتفصيـ ً‬\n\n\n‫‪323‬‬\n\f‫ـدي بينــة ومســتعد بإحضارهــا‬   ‫لديــه بينــة علــى دعــواه أجــاب بقولــه نعــم لـ َّ‬\n‫يف جلســة أخــرى هكــذا أجــاب ويف جلســة أخــرى حضــر املدعــي العــام‬\n‫واملدعــى عليــه وبســؤال املدعــي العــام عــن بينتــه التــي اســتعد بإحضارهــا‬\n‫احضر للشــهادة وأدائها كال من ‪ .....‬ســعودي اجلنســية مبوجب الســجل‬\n‫املدنــي رقــم ‪ .....‬املولــود بعــام ‪1405‬ه ـ يســكن تبــوك ويعمــل بهيئــة األمــر‬\n‫باملعــروف والنهــي عــن املنكــر وال تربطــه باملدعــى عليــه عالقــة قرابــة‬\n‫أو جتــارة حســب مــا أفــاد بــه وبســؤاله عمــا لديــه مــن شــهادة أجــاب‬\n‫بقولــه أشــهد هلل تعالــى بأنــه وردت لدينــا معلومــات حــول ابتــزاز املدعــى‬\n‫عليــه لفتــاة بنشــر صورهــا لتمكينــه مــن نفســها وأنــه يطلــب منهــا مبالــغ‬\n‫ماليــة كمــا أخبرتنــا الفتــاة أن املدعــى عليــه طلــب منهــا مبلــغ ألــف ريــال‬\n‫حتــت الضغــط وأنــه ســيحضر ألخذهــا فتــم االنتقــال للموقــع أمــام منــزل‬\n‫املدعيــة باحلــق اخلــاص ومت القبــض عليــه ووجــد بحوزتــه بطاقــة الصــراف‬\n‫العائــدة للفتــاة كمــا أنــه أقــر أمامــي داخــل الدوريــة األمنيــة أنــه أخــذ‬\n‫مــن الفتــاة املدعيــة مبلــغ عشــرة أالف ريــال ومســتعد بإعادتهــا ألجــل‬\n‫إنهــاء وضعــه هكــذا شــهد كمــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .....‬املولــود بعــام ‪1404‬ه ـ يســكن ‪ .....‬ويعمــل بهيئــة‬\n‫األمــر باملعــروف والنهــي عــن املنكــر وال تربطــه باملدعــى عليــه عالقــة‬\n‫قرابــة أو جتــارة حســب مــا أفــاد بــه وبســؤاله عمــا لديــه مــن شــهادة أجــاب‬\n‫بقولــه أشــهد هلل تعالــى بأنــه وردت لدينــا معلومــات حــول ابتــزاز املدعــى‬\n‫عليــه لفتــاة بنشــر صورهــا لتمكينــه مــن نفســها وأنــه يطلــب منهــا مبالــغ‬\n‫ماليــة كمــا أخبرتنــا الفتــاة أن املدعــى عليــه طلــب منهــا مبلــغ ألــف‬\n‫ريــال حتــت الضغــط وأنــه ســيحضر ألخذهــا فتــم االنتقــال للموقــع أمــام‬\n‫منــزل املدعيــة باحلــق اخلــاص ومت القبــض عليــه ووجــد بحوزتــه بطاقــة‬\n\n\n                                                                                          ‫‪324‬‬\n\f      ‫الصــراف العائــدة للفتــاة كمــا أن محضــر مشــاهدة الرســائل يــدل‬\n      ‫داللــة واضحــة علــى ابتــزاز املدعــى عليــه للفتــاة هكــذا شــهد وبعــرض‬\n      ‫الشــاهدين وشــهادتهما علــى املدعــى عليــه قــال أمــا الشــاهدان فليــس‬\n      ‫ـدي مــا أقــدح بــه فيهمــا أمــا بخصــوص الشــهادة فأنــا لــم أقــر بأخــذي‬‫لـ َّ‬\n      ‫ملبلــغ العشــرة أالف ريــال كمــا أن بطاقــة الصــراف ضبطــت بحوزتــي‬\n      ‫إال أنهــا كانــت ألجــل اســتيفاء مســتحقات ماليــة بينــي وبــن املدعيــة‬\n      ‫باحلــق اخلــاص هكــذا قــال وبســؤال املدعــي العــام إن كان لديــه مزيــد‬\n      ‫ـدي ســوى مــن أحضــرت ومــا يف أوراق املعاملــة‬   ‫بينــة أجــاب بقولــه ليــس لـ َّ‬\n      ‫هكــذا أجــاب فجــرى اإلطــاع علــى التحقيــق احملــرر علــى الصحيفــة‬\n      ‫رقــم (‪ )6-4‬املرفــق باملعاملــة لفــة رقــم (‪ )32‬املتضمــن مــا نصــه (س‪/‬‬\n      ‫كيــف مت القبــض عليــك ؟ ج‪ /‬أفيدكــم أنــه بتاريــخ ‪1433/3/4‬ه ـ‬\n      ‫ـاء قمــت باالتصــال علــى جــوال الفتــاة ‪ .....‬والتــي‬\n                                                            ‫حوالــي الســاعة ‪ 10‬مسـ ً‬\n      ‫تعرفــت عليهــا قبــل ســنتني تقريب ـ ًا عــن طريــق املعاكســة والترقيــم‬\n      ‫وجلســت أتواصــل معهــا ملــدة ثالثــة أشــهر عــن طريــق اجلــوال وكنــت‬\n      ‫أقــوم بإيصالهــا ملشــاوير حيــث أننــي أعمــل علــى توصيــل املشــاوير ثــم‬\n      ‫بعدهــا انقطعــت عالقتــي بهــا) كمــا ان فيــه مــا نصــه (أفيدكــم بأننــي‬\n      ‫أقمــت عالقــة معهــا عــن طريــق الهاتــف وقــد خرجــت معــي برضاهــا)‬\n      ‫ويظهــر مــن التحقيــق إقــرار املدعــى عليــه الثانــي ‪ .....‬بعالقتــه بالفتــاة‬\n      ‫املدعيــة وبعرضــه عليــه قــال حدثــت بينــي وبــن املدعيــة عالقــة بالهاتــف‬\n      ‫أمــا اخلــروج معــي فغيــر صحيــح هكــذا قــال كمــا جــرى اإلطــاع علــى‬\n      ‫محضــر مشــاهدة الرســائل املرفــق باملعاملــة لفــة رقــم (‪ )16-13‬وفيــه مــا‬\n      ‫نصــه (تــرى واهلل أدري أنهــا إنتظــار حتــى لــو قفلتــي اخلــط لكــن تشــويف‬\n      ‫اليــوم ردت فعلــي) (يعنــي الزم أخربهــا معاكــي عشــان حتترميني طيب)‬\n\n\n‫‪325‬‬\n\f‫(شــايفتيني غبــي يصيــر خيــر بــس خلينــي أتشــافى) واملرســلة مــن جــوال‬\n‫املدعــى عليــه ذي الرقــم (‪ ).....‬للمدعيــة وبعــرض ذلــك علــى املدعــى عليــه‬\n‫وســؤاله عنــه وعــن األرقــام التــي تعــود لــه أجــاب بقولــه الرقــم املذكــور‬\n‫يعــود لــي شــخصي ًا وســبب هــذه الرســائل كونــي أطالــب الفتــاة مبالــغ‬\n‫ماليــة وقمــت بإرســال هــذه الرســائل لهــا ألجــل ذلــك هكــذا أجاب كما‬\n‫جــرى تصفــح برنــت املكاملــات الــواردة والصــادرة املرفــق باملعاملــة لفــة‬\n‫رقــم (‪ )98‬والــذي يظهــر منــه جليـ ًا كثــرة االتصــاالت والرســائل الــواردة‬\n‫والصــادرة بــن املدعــى عليــه واملجنــي عليهــا ممــا يقــوي التهمــة بجانــب‬\n‫املدعــى عليــه وأن األمــر ليــس مجــرد عالقــة عمــل كمــا يزعــم فبنــاء‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وملَّــا أنكــر املدعــى عليــه الثانــي‬\n‫‪ .....‬التهمــة املنســوبة إليــه يف دعــوى املدعــي العــام وحيــث إن املدعــى‬\n‫عليــه أقــر بإقامــة لعالقــة محرمــة علــى مــدار ســنتني مــع فتــاة ال متــت‬\n‫لــه بصلــة عــن طريــق الهاتــف وحيــث إن اإلقــرار حجــة علــى صاحبــه‬\n‫مؤاخــذ بــه كمــا أقــر بخروجهــا معــه حتقيقـ ًا والــذي قــرر رجوعــه عنــه‬\n‫وحيــث إن الرجــوع عمــا يوجــب التعزيــر حلــق اهلل تعالــى ال يقبــل مــن‬\n‫(و َل ُي ْق َبــلُ ُر ُجــو ُع ْالُقِ ـ ِّـر َعــنْ ْإقـ َـرا ِر ِه َّإل‬\n                                                                       ‫صاحبــه جــاء يف املغنــي ‪َ 389/10‬‬\n‫اط ِه َف َأ َّمــا‬\n                 ‫ـاط ِ ِل ْسـ َـق ِ‬  ‫ات َو ُي ْح َتـ ُ‬‫الشـ ُـب َه ِ‬                                ‫ان َحـ ًّـدا ِ َّ ِ‬\n                                                                   ‫ل َت َعا َلــى ُيــدْ َر ُأ ِب ُّ‬                  ‫ك َ‬   ‫يمــا َ‬‫فِ َ‬\n‫كا ِة‬   ‫كالـ َّـز َ‬ ‫ات َ‬  ‫الشـ ُـب َه ِ‬                                               ‫ـوق َّ ِ‬\n                                      ‫الل َت َعا َلــى ا َّل ِتــي َل ُتــدْ َر ُأ ِب ُّ‬     ‫ن َو ُح ُقـ ُ‬   ‫ـوق ْال َدمِ ِّيـ َ‬‫ُح ُقـ ُ‬\n‫وع ـ ُه َع ْن َهــا َو َل ن َْع َلـ ُـم ِف َهـ َـذا خِ َل ًفــا) وحيــث‬             ‫ات َفـ َـا ُي ْق َبــلُ ُر ُج ُ‬ ‫ـار ِ‬‫ك َّفـ َ‬‫َوا ْل َ‬\n‫قامــت البينــة علــى ضبــط املدعــى عليــه وبحوزتــه بطاقــة الصــراف اآللــي‬\n‫العائــد للفتــاة املجنــي عليهــا وقــد أقــر املدعــى عليــه بذلــك ممــا يثيــر‬\n‫شــبهة قويــة جتاهــه باالبتــزاز ونظــر ًا لكــون مــا دفــع بــه مــن املطالبــات‬\n‫املاليــة ال يبــرر فعلتــه فاالســتحقاقات املاليــة ال تأخــذ بهــذه الطريقــة‬\n\n\n                                                                                                                                            ‫‪326‬‬\n\f      ‫مــن التخفــي وتبقــى علــى مــدار هــذا الوقــت الطويــل دون علــم ولــي أمــر‬\n      ‫الفتــاة بتلــك االســتحقاقات كمــا أن مــا شــهد بــه الشــاهد األول مــن‬\n      ‫إقــراره أمامــه بأخــذه ملبلــغ عشــرة أالف ريــال مــن الفتــاة واســتعداده‬\n      ‫لردهــا بغيــة إنهــاء املوضــوع يقــوي شــبهة االبتــزاز جتــاه املدعــى عليــه‬\n      ‫وحيــث إن التهديــد باالبتــزاز عمــل محــرم يــدل علــى شــدة جــرم صاحبــه‬\n      ‫وفســاد طبعــه وســوء خلقــه وفيــه إشــاعة للفاحشــة يف املجتمــع وقــد قــال‬\n                        ‫ـيع ا ْل َفاحِ َش ـ ُة ِف الَّذِ يـ َـن َ‬\n      ‫آم ُنــوا َل ُهـ ْـم‬                                            ‫ـون َأن َت ِشـ َ‬   ‫اهلل تعالــى ( ِإ َّن الَّذِ ي َــن ُي ِح ُّبـ َ‬\n      ‫ـون) «النــور ‪»19‬‬                                                     ‫الد ْن َيــا َو ْالخِ ــر ِة َو َّ ُ‬\n                              ‫الل َي ْع َلـ ُـم َو َأن ُتـ ْـم َل َت ْعل َُمـ َ‬                               ‫اب َأ ِليـ ٌـم ِف ُّ‬ ‫َعـ َـذ ٌ‬\n                                                                                       ‫َ‬\n      ‫ـدي إدانــة املدعــى عليــه الثانــي ‪.....‬‬                         ‫لــذا وجلميــع مــا تقــدم فقــد ثبــت لـ َّ‬\n      ‫ـدي إدانتــه‬    ‫بإقامتــه عالقــة محرمــة مــع فتــاة ال متــت لــه بصلــة ولــم يثبــت لـ َّ‬\n      ‫باالبتــزاز والتهديــد بنشــر الصــور وإمنــا توجــه الشــبهة لــه بذلــك وقــررت‬\n      ‫مــا يلــي أو ًال تعزيــر املدعــى عليــه الثانــي ‪ .....‬لقــاء مــا ثبــت بحقــه مــن‬\n      ‫إقامــة عالقــة محرمــة ولشــبهة االبتــزاز بســجنه ملــدة ســنتني يحتســب مــن‬\n      ‫ذلــك مــدة إيقافــه بســبب هــذه القضيــة وجلــده مائتــي جلــدة مفرقــة علــى‬\n      ‫أربــع دفعــات كل دفعــة خمســن جلــدة بــن كل دفعــة وأخــرى عشــرة‬\n      ‫أيــام ثانيـ ًا صرفــت النظــر عــن طلــب املدعــي العــام تطبيــق املادتــن (‪-3‬‬\n      ‫‪ )13‬مــن نظــام مكافحــة اجلرائــم املعلوماتيــة لعــدم ثبــوت موجــب لذلــك‬\n      ‫وبذلــك حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n      ‫قناعتــه بــه أمــا املدعــي العــام فقــد قــرر اعتــراض مكتفيـ ًا مبــا جــاء يف‬\n      ‫أوراق املعاملــة عــن تقــدمي الئحــة اعتراضيــة وســتتم محاكمــة املدعــى‬\n      ‫عليــه األول حــال إحضــاره بــإذن اهلل وللبيــان حــرر يف ‪1433/6/14‬ه ـ‬\n                           ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد وردت املعاملــة مــن محكمــة االســتئناف‬\n\n\n‫‪327‬‬\n\f‫مبنطقــة اجلــوف وذلــك مبوجــب كتــاب رئيــس محكمــة االســتئناف‬\n‫مبنطقــة اجلــوف برقــم وتاريــخ ‪1434/3/9‬ه ـ واملرفــق بــه قــرار املالحظــة‬\n‫الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم وتاريــخ ‪1434/3/8‬ه ـ ونــص‬\n‫احلاجــة منــه (وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ‬\n‫باألكثريــة أو ًال لــم يتطــرق فضيلتــه ملــا طلبــه املدعــي العــام مــن مصــادرة‬\n‫جهــاز اجلــوال املســتخدم يف اجلرميــة ثاني ـ ًا يوجــد خطــأ يف رقــم املادتــن‬\n‫(‪ )4‬و(‪ )5‬حيــث ذكــر فضيلتــه يف حكمــه رقمهــا (‪ )3‬و(‪ )13‬فعلــى‬\n‫فضيلتــه إكمــال الــازم حيــال مــا ذكــر وإضافــة مــا يجــد للضبــط‬\n‫وصورتــه والقــرار وســجله ومــن ثــم إعــادة املعاملــة كاملتبــع واهلل املوفــق)‬\n‫وعليــه أجيــب أصحــاب الفضيلــة مبــا يلــي أو ًال أنــه مت صــرف النظــر عــن‬\n‫طلــب املدعــي العــام تطبيــق املــادة (‪ )13‬مــن نظــام مكافحــة اجلرائــم‬\n‫املعلوماتيــة وهــي املــادة اخلاصــة باملصــادرة ثانيـ ًا أن املادتــن املشــار إليهما‬\n‫يف احلكــم صحيحــة أمــا مــا ذكره أصحــاب الفضيلة فهي فقرات املادة‬\n‫الثالثــة هــذا مــا لــزم اإلجابــة عنــه واهلل أســأل الهدايــة للحــق والصــواب‬\n‫وألصحــاب الفضيلــة قضــاة محكمــة االســتئناف املوقــرة فائــق التقديــر‬\n‫واالحتــرام وللبيــان حــرر يف ‪1434/4/1‬ه ـ وصلــى اهلل علــى نبينــا محمــد‬\n                                                     ‫وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n‫احلمــدهلل وحــده وبعــد ‪ ...‬فقــد أطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الثانيــة لتمييــز القضايــا اجلزائيــة مبحكمــة اإلســتئناف باجلــوف علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بتبــوك املكلــف‬\n‫الشــيخ‪ ...../‬برقــم وتاريخ‪1434/4/7‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة الشــيخ ‪ ..... /‬برقــم وتاريخ‪1433/6/15‬ه ـ اخلــاص بدعــوى‬\n‫املدعــي العــام ضــد‪ ..... /‬و رفيقــه يف اقامــة عالقــة محرمــة وقــد تضمــن‬\n\n\n                                                                                          ‫‪328‬‬\n\f      ‫القــرار حكــم فضيلتــه مبــا هــو مــدون و مفصــل فيــه وبدراســة القــرار‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة تقــرر املصادقــة علــى احلكــم بعــد‬\n      ‫اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                  ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪329‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":315,"source_page_end":329,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bf3f9cd36410608ebf9d2209e3ec1750de19edc46457b58afcad1d244c500170","normalized_text_hash":"c06727c9eb6c7d2fd33f1e1c4edce8e91c32117190a311d6abfd5e01d77a7925","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p315-33299196"},{"id":"f3c94604-7e9d-5f0a-97a3-cc9fe2a1d8e5","document_type":"judgment","category":"judicial","subcategory":"general","title":"خلوة محرمة -إقامة عالقة محرمة مع امرأة -املدعى عليه محصن -ممارسة مقدمات الفاحشة -أسباب تخفيف العقوبة - وقف تنفيذ العقوبة.","document_number":"33356003","case_number":"33464877","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1435/7/26","year":"1434","subject":"خلوة محرمة -إقامة عالقة محرمة مع امرأة -املدعى عليه محصن -ممارسة مقدمات الفاحشة -أسباب تخفيف العقوبة - وقف تنفيذ العقوبة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33356003 :‬تاريخه ‪1435/7/26 :‬هـ‬\n                     ‫رقم الدعوى‪33464877 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 3430186‬تاريخه‪1434/2/5 :‬هـ‬\n\n\n ‫خلــوة محرمــة ‪ -‬إقامــة عالقــة محرمــة مــع امــرأة ‪ -‬املدعــى عليــه‬\n ‫محصــن ‪ -‬ممارســة مقدمــات الفاحشــة ‪ -‬أســباب تخفيــف العقوبــة ‪-‬‬\n                                                 ‫وقــف تنفيــذ العقوبــة‪.‬‬\n\n\n\n ‫‪ -1‬قــول الرســول صلــى اهلل عليــه وســلم (ال يخلــون رجــل بامــرأة إال‬\n                                                 ‫كان الشــيطان ثالثهمــا)‬\n ‫‪ -2‬قــول الرســول صلــى اهلل عليــه وســلم (أقيلــوا ذوي الهيئــات عثراتهــم‬\n                                                              ‫إال يف احلــدود)‬\n ‫‪ -3‬نقــل ملــا ورد يف األحــكام الســلطانية أن تأديــب ذي الهيئــة مــن أهــل‬\n                     ‫الصيانــة أخــف مــن تأديــب أهــل البــذاءة والســفاهة‪.‬‬\n\n\n\n ‫توجيــه االتهــام للمدعــى عليــه باالرتبــاط بعالقــة محرمــة بفتــاة واالختالء‬\n ‫بهــا يف إحــدى الشــقق املفروشــة واســتغالل عملــه بذلــك‪ ،‬حيــث قبــض‬\n ‫عليــه مــن قبــل هيئــة األمــر باملعــروف والنهــي عــن املنكــر إثــر قيامــه‬\n ‫بــإركاب امــرأة (مت التســتر عليهــا) والتوجــه بهــا إلــى إحــدى الشــقق‬\n ‫املفروشــة‪ ،‬أقــر أمــام الفرقــة باالختــاء وممارســة مقدمــات الفاحشــة‪،‬‬\n ‫طلــب املدعــي العــام اتبــاع مــا أســند إليــه للمدعــى عليــه و احلكــم عليــه‬\n\n\n                                                                                      ‫‪330‬‬\n\f      ‫بعقوبــة تعزيريــة‪ ،‬أقــر املدعــى عليــه باالرتبــاط بعالقــة محرمــة مــع امــرأة‬\n      ‫ال حتــل لــه وأنــه جلــس معهــا أكثــر مــن مــرة يف مــكان عــام‪ ،‬أنكــر‬\n      ‫اخللــوة التــي متــت يف الســيارة وقــت الذهــاب للشــقة‪ ،‬كمــا أنكــر فعــل‬\n      ‫مقدمــات الفاحشــة‪ ،‬أظهــر املدعــى عليه التوبــة والندم‪ ،‬اكتفى املدعي‬\n      ‫العــام مبــا يف أوراق املعاملــة‪ ،‬ذكــر القاضــي أســباب تخفيــف احلكــم‪،‬‬\n      ‫حكمــت احملكمــة بإدانــة املدعــى عليــه بحصــول اخللــوة وتوجــه التهمــة‬\n      ‫مبمارســة مقدمــات الفاحشــة وتعزيــر املدعــى عليــه باجللــد مئــة وخمســن‬\n      ‫جلــدة بــن طائفــة مــن املؤمنــن علــى دفعتــن وســجنه شــهرين مــع وقــف‬\n      ‫عقوبــة الســجن املشــروط بعــدم العــودة ملثــل مــا بــدر منــه ‪ ،‬صــدق احلكــم‬\n                                                            ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬املــازم القضائــي لــدى فضيلــة‬\n      ‫الشــيخ ‪.........‬القاضــي يف احملكمــة اجلزائيــة بالريــاض واملكلــف مــن‬\n      ‫قبلــه بنظــر هــذه القضيــة وبنــاء على املعاملة احملالة لنــا من فضيلة رئيس‬\n      ‫احملكمة اجلزائية بالرياض برقم ‪ 33464877‬وتاريخ ‪1433/07/14‬هـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331322442‬وتاريــخ ‪ 1433/07/14‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافق‪1433/07/26‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 15‬‬\n      ‫وفيهــا قــدم املدعــي العــام ‪.........‬دعــواه ضــد ‪ 32،.........‬ســنه ‪ ،‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ،).........‬محصــن ‪ ،‬مقيــم مبدينــة‬\n      ‫الريــاض ‪ ،‬صــدر لــه أمــر اإلفــراج قم‪.........‬وتاريــخ ‪1433 /6 / 18‬ه ـ‬\n                           ‫اســتناد ًا للمــادة ‪ 120‬مــن نظــام اإلجــراءات اجلزائيــة‪.‬‬\n      ‫الوقائــع ‪ :‬انــه بتاريخ‪1433/6/17‬ه ـ قبــض علــى املذكــور مــن قبــل هيئة‬\n\n‫‪331‬‬\n\f‫األمــر باملعــروف والنهــي عــن املنكــر مركــز هيئــة ‪ .........‬و‪ ....‬أثر قيامه‬\n‫بــإركاب امــرأة ( مت التســتر عليهــا) والتوجــه بهــاء إلــى إحــدى الشــقق‬\n‫املفروشــة‪ ،‬وبانتقــال الفرقــة للموقــع مت مشــاهدته وقــد ظهــرت عليــه‬\n‫عالمــات اإلرتبــاك واخلــوف وبــادر بطلــب الســتر عليــه وأفــاد للفرقــة أنــه‬\n‫تعــرف علــى املــرأة عــن طريــق عملــه وأنــه اختلــى بهــا أكثــر مــن مــرة‬\n                                   ‫بســيارته ومــارس معهــا مقدمــات الفاحشــة ‪.‬‬\n‫وأســفرت إجــراءات التحقيــق عــن اتهــام املذكور بربــط العالقة احملرمة‬\n‫بفتــاة واالختــاء احملــرم بهــايف إحدى الشــقق املفروشــة واســتغالل عمله‬\n                                          ‫بذلــك‪ .‬وذلــك لألدلــة والقرائــن اآلتية ‪-:‬‬\n‫‪ -1‬مــا جــاء يف أقوالــه املدونــة علــى الصفحــة رقــم (‪ )4‬مــن دفتــر‬\n                                                         ‫االســتدالل املرفــق لفــه‪.‬‬\n                                         ‫‪ -2‬ما جاء مبحضر القبض املرفق لفه‪.‬‬\n‫وبالبحــث بســجله اجلنائــي لــم يعثــر لــه علــى ســوابق مســجلة حتــى‬\n‫تاريخــه‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه‬\n‫شــرع ًا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــه لقــاء‬\n‫مــا أســند إليــه‪ .‬هــذه دعــواي‪ ،‬وبســؤال املدعــى عليــه أجــاب بقولــه مــا‬\n‫ذكــره املدعــي العــام يف اجلملــة صحيــح فقــد قبــض علــي وكنــت قــد‬\n‫ربطــت عالقــة محرمــة مــع امــرأة ال حتــل لــي كمــا إننــي جلســت مــع‬\n‫هــذه املــرأة أكثــر مــن مــرة يف مــكان عــام ولــم اختـ ِـل بهــا إال يف ســيارتي‬\n‫وقمــت بالذهــاب إلــى الشــقة يف الوقــت الــذي مت القبــض علينــا مــن قبــل‬\n‫الهيئــة وأنــا رجــل عســكري وليــس علــي ســوابق جنائيــة وأنــا تائــب إلــى‬\n‫اهلل تعالــى وأتعهــد بعــدم العــودة ملثــل مــا بــدر منــي كما إن املــرأة كبيرة‬\n‫الســن وعمرهــا يقــارب اخلمســن ســنة وأنــا رجل متزوج ولــي عيال بحاجة‬\n\n\n                                                                                         ‫‪332‬‬\n\f      ‫إلــي كمــا إننــي لــم أمــارس مقدمــات الفاحشــة معهــا هكــذا أجــاب‬\n      ‫وجــرى االطــاع علــى محضــر الهيئــة املــدون علــى اللفــة (‪ )5‬مــن املعاملــة‬\n      ‫وقــد تضمــن ( فإنــه يف هــذا اليــوم وردتنــا معلومــات عــن املذكــور أعــاه‬\n      ‫بأنــه قــام بإدخــال امــرأة إلــى الشــقق املفروشــة ‪ .........‬وعنــد االنتقــال إلــى‬\n      ‫املوقــع اســتدعي الطــرف األول لتحقيــق مــن حالتــه وعنــد رؤيتــه للفرقــة‬\n      ‫ظهــرت عليــه عالمــات اخلــوف واالرتبــاك وبــادر الفرقــة بطلــب الســتر‬\n      ‫عليــه وأفــاد بأنــه تعــرف علــى املــرأة عــن طريــق عملــه بســكة احلديــد‬\n      ‫منــذ مــا يقــارب أربعــة أشــهر وأنــه اختلــى بهــا أكثــر مــن مــرة بســيارته‬\n      ‫ويف هــذا اليــوم اختلــى بهــا يف الشــقق املفروشــة ومــارس معهــا مقدمــات‬\n      ‫الفاحشــة جــرى تدويــن هــذا احملضــر حفظ ـ ًا للواقــع وإبــراء للذمــة )‬\n      ‫وبعرضــه علــى املدعــى عليــه قــرر بقولــه ‪ :‬الصحيــح أننــي اجتمعــت معهــا‬\n      ‫يف أمكنــة عامــة كاألســواق واملجمعــات التجاريــة كمــا إننــي اختليــت‬\n      ‫بهــا مــرة واحــدة ســاعة القبــض علــي مــن قبــل الهيئــة يف ســيارتي وقــد‬\n      ‫تعرفــت عليهــا عــن طريــق عملــي حيــث أعمــل عســكري يف ســكة‬\n      ‫احلديــد كمــا إنــه لــم يحصــل بيننــا مقدمــات الفاحشــة غيــر اخللــوة علــى‬\n      ‫مــا ذكــرت يف جوابــي هكــذا قــرر فبنــاء علــى مــا ســلف مــن الدعــوى‬\n      ‫واإلجابــة ونظــر ًا لكــون املدعــى عليــه صــادق علــى دعــوى املدعــي العــام‬\n      ‫وأقــر بحصــول اخللــوة وقــد قــال النبــي صلــى اهلل عليــه وســلم ( ال يخلــون‬\n      ‫رجل بامرأة إال كان الشــيطان ثالثهما ) إذ اخللوة مظنة وقوع الفاحشــة‬\n      ‫كمــا أن املدعــى عليــه أنكــر حصــول مقدمــات الفاحشــة مــن غيــر‬\n      ‫اخللــوة علــى مــا ذكــر يف محضــر الهيئــة بعاليــه وحيــث بنــي احملضر على‬\n      ‫إفــادة املدعــى عليــه واملــرء مؤاخــذ بإقــراره شــرع ًا وألن مــا أقــدم عليــه‬\n      ‫املدعــى عليــه يعــد أمــر ًا محرمـ ًا يســتحق العقوبــة عليهــا ومبــا أن العقوبــة‬\n\n\n‫‪333‬‬\n\f‫شــرعت لتكــون زاجــرة للنــاس عــن فعــل احملــرم وكفــارة عمــن وقــع‬\n‫فيهــا كمــا أن وقــف تنفيــذ العقوبــة وجعلهــا ســيف ًا مســلط ًا علــى املدعــى‬\n‫عليــه لــه األثــر البليــغ يف الــردع مــن اإليقــاع نفســه كمــا إن إيقــاف تنفيــذ‬\n‫عقوبــة الســجن فيهــا جتنيــب للمحكــوم مــن اآلثــار الســيئة علــى املدعــى‬\n‫عليــه نتيجــة االختــاط داخــل الســجن مــع معتــادي اإلجــرام إضافــة‬\n‫إلــى مــا ســبق ظهــر لــي صــدق توبــة املدعــى عليــه ولظروفــه الشــخصية‬\n‫املذكــورة بعاليــه وبعــد االطــاع علــى املعاملــة ثبــت لــدي إدانــة املدعــى‬\n‫عليــه بحصــول اخللــوة إلقــراره لــدي بذلــك كمــا توجهــت لــدي التهمــة‬\n‫مبمارســة املدعــى عليــه ملقدمــات الفاحشــة معهــا ومــن ثــم قــررت مــا يلــي‬\n‫‪ :‬أو ًال ‪ :‬جلــد املدعــى عليــه مائــة وخمســن جلــدة تعزيــر ًا بــن طائفــة مــن‬\n‫املؤمنــن تنفــذ علــى دفعتــن بالتســاوي بــن كل دفعــة وأخــرى عشــرة‬\n‫أيــام ‪ .‬ثاني ـ ًا ‪ :‬ســجن املدعــى عليــه شــهرين مــع وقــف التنفيــذ املشــروط‬\n‫بعــدم العــودة ملثــل مــا بــدر منــه فــإن عــاد يف تنفيــذ احلكــم بالســجن علــى‬\n‫مــا ذكــر ووقــف تنفيــذ العقوبــة خــاص بالســجن أمــا اجللــد فينفــذ كمــا‬\n‫أن وقــف تنفيــذ العقوبــة ال يؤثــر علــى اجلرميــة الالحقــة وبعــرض احلكــم‬\n‫علــى احملكــوم عليــه قــرر القناعــة باحلكــم أمــا املدعــي العــام فطلــب‬\n‫اســتئنافه مكتفيـ ًا بالئحــة الدعــوى ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/07/26‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1433/11/24‬ه ـ‬\n‫افتتحــت اجللســة بعــد أن وردنــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة‬\n‫اجلزائيــة الرابعــة مبحكمــة االســتئناف بالريــاض برقــم (‪)33434661‬‬\n‫وتاريــخ ‪1433/10/22‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪......... /‬‬\n‫املتضمــن مــا نصــه (وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n\n\n                                                                                         ‫‪334‬‬\n\f      ‫لوحــظ باألكثريــة أن اجلــزاء التعزيــري قليــل الســيما أن املدعــى عليــه‬\n      ‫رجــل أمــن ومتــزوج واختلــى بهــا عــدة مــرات) وبعــد اإلطــاع علــى مــا‬\n      ‫ذكــره أصحــاب الفضيلــة يف قرارهــم فأقــول جوابــا علــى ذلــك بــأن‬\n      ‫التعزيــر عقوبــة مفــوض تقديرهــا إلــى القاضــي وعليــه مراعــاة ظــروف‬\n      ‫اجلانــي ومالبســات احلادثــة وقــد رأيــت أن املدعــى عليــه مــن ذوي الهيئــة‬\n      ‫احلســنة والصيانــة فخففــت عنــه التعزيــر لذلــك وقــد قــال النبــي صلــى‬\n      ‫اهلل عليــه وســلم (أقيلــوا ذوي الهيئــات عثراتهــم إال يف احلــدود) واحلديــث‬\n      ‫صحيــح وقــد نقــل املــاوردي يف األحــكام الســلطانية ‪ :‬أن تأديــب ذي‬\n      ‫الهيئــة مــن أهــل الصيانــة أخــف مــن تأديــب أهــل البــذاءة والســفاهة كما‬\n      ‫أنــه قــد ظهــر لــي صــدق توبتــه وعزمــه علــى عــدم العــودة فعليــه فإنــي‬\n      ‫الزلــت علــى مــا حكمــت بــه وأرى مناســبة العقوبــة التعزيريــة املقــدرة‬\n      ‫وأســأل اهلل الســداد للجميــع ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n               ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫الرابعــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزئيــة بالريــاض برقــم ‪ 332009460‬وتاريــخ‬\n      ‫‪1433/11/29‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة املــازم‬\n      ‫القضائــي باحملكمــة الشــيخ ‪ ......... /‬املســجل برقــم‪ 33356003‬وتاريــخ‬\n      ‫‪1433/7/26‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪ ......... /‬التهامــه‬\n      ‫بربــط عالقــة محرمــة مــع امــرأة واالختــاء بهــا علــى النحــو املوضــح‬\n      ‫بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون بــه وحيــث ســبق دراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه‬\n      ‫ـاء علــى قرارنــا‬‫فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنـ ً‬\n\n‫‪335‬‬\n\f‫رقــم ‪ 33434661‬وتاريــخ ‪1433/10/22‬ه قــررت الدائــرة باألكثريــة‬\n‫املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪.‬واهلل املوفــق وصلــى اهلل‬\n                                ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n           